    def _preflight_existing_photo_schema(self, conn: sqlite3.Connection) -> None:
        self._preflight_review_candidates_schema(conn)
        self._preflight_safe_mode_overrides_schema(conn)
        for table, columns in self._photo_table_column_migrations():
            if not self._table_exists(conn, table):
                continue
            for column, definition in columns:
                self._ensure_column(conn, table, column, definition)

    def _preflight_review_candidates_schema(self, conn: sqlite3.Connection) -> None:
        if not self._table_exists(conn, "review_candidates"):
            return
        for column, definition in self._review_candidate_column_migrations():
            self._ensure_column(conn, "review_candidates", column, definition)

    def _preflight_safe_mode_overrides_schema(self, conn: sqlite3.Connection) -> None:
        if not self._table_exists(conn, "safe_mode_overrides"):
            return
        columns = {str(row["name"]) for row in conn.execute("PRAGMA table_info(safe_mode_overrides)").fetchall()}
        if "content_hash" in columns and "asset_id" not in columns:
            return
        migrated_rows: list[tuple[str, int, str, str]] = []
        reason_expr = "COALESCE(reason, '')" if "reason" in columns else "''"
        created_expr = "COALESCE(created_at, '')" if "created_at" in columns else "''"
        order_expr = "COALESCE(created_at, '')" if "created_at" in columns else "''"
        joined_reason_expr = "COALESCE(smo.reason, '')" if "reason" in columns else "''"
        joined_created_expr = "COALESCE(smo.created_at, '')" if "created_at" in columns else "''"
        joined_order_expr = "COALESCE(smo.created_at, '')" if "created_at" in columns else "''"
        if "override_sensitive" in columns:
            if "content_hash" in columns:
                try:
                    migrated_rows.extend(
                        (
                            str(row["content_hash"] or ""),
                            1 if bool(row["override_sensitive"]) else 0,
                            str(row["reason"] or ""),
                            str(row["created_at"] or ""),
                        )
                        for row in conn.execute(
                            f"""
                            SELECT content_hash, override_sensitive, {reason_expr} AS reason, {created_expr} AS created_at
                            FROM safe_mode_overrides
                            WHERE COALESCE(content_hash, '') <> ''
                            ORDER BY {order_expr} ASC
                            """
                        ).fetchall()
                    )
                except sqlite3.DatabaseError:
                    migrated_rows = []
            if "asset_id" in columns and self._table_exists(conn, "photo_assets"):
                photo_columns = {str(row["name"]) for row in conn.execute("PRAGMA table_info(photo_assets)").fetchall()}
                if "asset_id" in photo_columns and "content_hash" in photo_columns:
                    try:
                        migrated_rows.extend(
                            (
                                str(row["content_hash"] or ""),
                                1 if bool(row["override_sensitive"]) else 0,
                                str(row["reason"] or ""),
                                str(row["created_at"] or ""),
                            )
                            for row in conn.execute(
                                f"""
                                SELECT pa.content_hash AS content_hash, smo.override_sensitive AS override_sensitive,
                                       {joined_reason_expr} AS reason, {joined_created_expr} AS created_at
                                FROM safe_mode_overrides AS smo
                                JOIN photo_assets AS pa ON pa.asset_id = smo.asset_id
                                WHERE COALESCE(pa.content_hash, '') <> ''
                                ORDER BY {joined_order_expr} ASC
                                """
                            ).fetchall()
                        )
                    except sqlite3.DatabaseError:
                        pass
        conn.execute("DROP TABLE IF EXISTS safe_mode_overrides")
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS safe_mode_overrides (
                content_hash TEXT PRIMARY KEY,
                override_sensitive INTEGER NOT NULL,
                reason TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL
            )
            """
        )
        if migrated_rows:
            conn.executemany(
                """
                INSERT OR REPLACE INTO safe_mode_overrides(content_hash, override_sensitive, reason, created_at)
                VALUES(?, ?, ?, ?)
                """,
                [(content_hash, value, reason, created_at or now_iso()) for content_hash, value, reason, created_at in migrated_rows if content_hash],
            )

    def _run_photo_startup_repairs(self, conn: sqlite3.Connection) -> None:
        row = conn.execute(
            "SELECT value FROM meta WHERE key = ? LIMIT 1",
            (PHOTO_STARTUP_REPAIR_META_KEY,),
        ).fetchone()
        if row and str(row["value"] or "") == PHOTO_STARTUP_REPAIR_VERSION:
            return
        self._backfill_photo_album_item_positions(conn)
        self._backfill_photo_timestamp_defaults(conn)
        self._repair_photo_duplicate_group_summaries(conn)
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES(?, ?)",
            (PHOTO_STARTUP_REPAIR_META_KEY, PHOTO_STARTUP_REPAIR_VERSION),
        )

    def _backfill_photo_album_item_positions(self, conn: sqlite3.Connection) -> None:
        if not self._table_exists(conn, "photo_album_items"):
            return
        rows = conn.execute(
            """
            SELECT i.rowid AS item_rowid, i.album_id, i.asset_id, i.position, i.added_at, a.created_at AS album_created_at
            FROM photo_album_items AS i
            LEFT JOIN photo_albums AS a ON a.album_id = i.album_id
            ORDER BY i.album_id ASC, i.position ASC, i.added_at ASC, item_rowid ASC
            """
        ).fetchall()
        positions: dict[str, int] = {}
        now = now_iso()
        for row in rows:
            album_id = str(row["album_id"] or "")
            asset_id = str(row["asset_id"] or "")
            if not album_id or not asset_id:
                continue
            position = positions.get(album_id, 0)
            positions[album_id] = position + 1
            added_at = str(row["added_at"] or "") or str(row["album_created_at"] or "") or now
            if int(row["position"] or 0) == position and str(row["added_at"] or ""):
                continue
            conn.execute(
                """
                UPDATE photo_album_items
                SET position = ?, added_at = ?
                WHERE album_id = ? AND asset_id = ?
                """,
                (position, added_at, album_id, asset_id),
            )

