    def _repair_photo_duplicate_group_summaries(self, conn: sqlite3.Connection) -> None:
        if not self._table_exists(conn, "photo_duplicate_groups") or not self._table_exists(conn, "photo_duplicate_group_items"):
            return
        item_rows = conn.execute(
            """
            SELECT group_id, asset_id
            FROM photo_duplicate_group_items
            ORDER BY group_id ASC, position ASC, asset_id ASC
            """
        ).fetchall()
        counts: dict[str, int] = {}
        primary_assets: dict[str, str] = {}
        for row in item_rows:
            group_id = str(row["group_id"] or "")
            asset_id = str(row["asset_id"] or "")
            if not group_id or not asset_id:
                continue
            counts[group_id] = counts.get(group_id, 0) + 1
            primary_assets.setdefault(group_id, asset_id)
        for row in conn.execute("SELECT group_id, item_count, primary_asset_id FROM photo_duplicate_groups").fetchall():
            group_id = str(row["group_id"] or "")
            if not group_id:
                continue
            item_count = counts.get(group_id, int(row["item_count"] or 0))
            primary_asset_id = str(row["primary_asset_id"] or "") or primary_assets.get(group_id, "")
            conn.execute(
                """
                UPDATE photo_duplicate_groups
                SET item_count = ?, primary_asset_id = ?
                WHERE group_id = ?
                """,
                (item_count, primary_asset_id, group_id),
            )

    def _candidate_payload(self, candidate: Any) -> dict[str, Any]:
        if is_dataclass(candidate):
            payload = asdict(candidate)
        elif isinstance(candidate, dict):
            payload = dict(candidate)
        else:
            payload = {
                "candidate_id": getattr(candidate, "candidate_id", ""),
                "source_path": getattr(candidate, "source_path", ""),
                "person_name": getattr(candidate, "person_name", ""),
                "best_ref_id": getattr(candidate, "best_ref_id", None),
                "best_ref_path": getattr(candidate, "best_ref_path", None),
                "score": getattr(candidate, "score", 0.0),
                "band": getattr(candidate, "band", ""),
                "quality": getattr(candidate, "quality", 0.0),
                "model_name": getattr(candidate, "model_name", ""),
                "pose_bucket": getattr(candidate, "pose_bucket", "unknown"),
                "status": getattr(candidate, "status", "pending"),
                "note": getattr(candidate, "note", ""),
                "risk_flags": getattr(candidate, "risk_flags", []),
                "media_kind": getattr(candidate, "media_kind", "image"),
                "media_source_path": getattr(candidate, "media_source_path", ""),
                "video_timestamp_ms": getattr(candidate, "video_timestamp_ms", None),
                "video_frame_index": getattr(candidate, "video_frame_index", None),
                "video_duration_ms": getattr(candidate, "video_duration_ms", None),
                "video_track_id": getattr(candidate, "video_track_id", ""),
                "video_track_version": getattr(candidate, "video_track_version", ""),
                "video_track_start_ms": getattr(candidate, "video_track_start_ms", None),
                "video_track_end_ms": getattr(candidate, "video_track_end_ms", None),
                "video_track_frame_count": getattr(candidate, "video_track_frame_count", 0),
                "video_track_keyframe_timestamps_ms": getattr(candidate, "video_track_keyframe_timestamps_ms", []),
                "video_track_keyframe_indices": getattr(candidate, "video_track_keyframe_indices", []),
                "source_hash": getattr(candidate, "source_hash", ""),
                "review_priority": getattr(candidate, "review_priority", 0.0),
                "review_lane": getattr(candidate, "review_lane", ""),
                "calibrated_probability": getattr(candidate, "calibrated_probability", None),
                "calibration_source": getattr(candidate, "calibration_source", ""),
                "calibration_version": getattr(candidate, "calibration_version", ""),
                "created_at": getattr(candidate, "created_at", now_iso()),
            }
        return payload

    def _candidate_params(self, candidate: Any) -> tuple[Any, ...]:
        payload = self._candidate_payload(candidate)
        source_path = str(payload.get("source_path", ""))
        media_source_path = str(payload.get("media_source_path", "") or "")
        media_path = media_source_path or source_path
        try:
            folder_path = str(Path(media_path).expanduser().parent) if media_path else ""
        except (OSError, ValueError):
            folder_path = ""
        person_name = str(payload.get("person_name", ""))
        risk_flags = normalize_risk_flags(payload.get("risk_flags"), str(payload.get("note", "")))
        payload["risk_flags"] = risk_flags
        risk_flags_text = " ".join(risk_flags)
        close_runner_up = int(bool({"close-runner-up", "ambiguous-person-margin"} & set(risk_flags)))
        single_reference_match = int(bool({"single-reference-match", "single-reference-close-runner-up", "single-reference-hard-pose"} & set(risk_flags)))
        review_priority_value = payload.get("review_priority", payload.get("reviewPriority", 0.0))
        try:
            review_priority = float(review_priority_value or 0.0)
        except (TypeError, ValueError):
            review_priority = 0.0
        review_lane = str(payload.get("review_lane", payload.get("reviewLane", "")) or "")
        return (
            str(payload.get("candidate_id", "")),
            source_path,
            person_name,
            person_name.casefold(),
            str(payload.get("best_ref_id") or ""),
            str(payload.get("best_ref_path") or ""),
            float(payload.get("score", 0.0) or 0.0),
            str(payload.get("band", "")),
            float(payload.get("quality", 0.0) or 0.0),
            str(payload.get("model_name", "")),
            str(payload.get("status", "pending")),
            str(payload.get("note", "")),
            risk_flags_text,
            close_runner_up,
            single_reference_match,
            str(payload.get("media_kind", "image") or "image"),
            media_source_path,
            media_path,
            folder_path,
            payload.get("video_timestamp_ms"),
            payload.get("video_frame_index"),
            payload.get("video_duration_ms"),
            str(payload.get("source_hash", "")),
            review_priority,
            review_lane,
            str(payload.get("created_at", "") or now_iso()),
            json.dumps(payload, separators=(",", ":")),
        )

    def _upsert_candidate_sql(self) -> str:
        return """
            INSERT OR REPLACE INTO review_candidates(
                candidate_id, source_path, person_name, person_key, best_ref_id, best_ref_path,
                score, band, quality, model_name, status, note, risk_flags, close_runner_up, single_reference_match, media_kind, media_source_path,
                media_path, folder_path, video_timestamp_ms, video_frame_index, video_duration_ms, source_hash, review_priority, review_lane,
                created_at, payload_json
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """

    def _candidate_param_batches(self, candidates: Iterable[Any], batch_size: int = 1000) -> Iterator[list[tuple[Any, ...]]]:
        batch: list[tuple[Any, ...]] = []
        for candidate in candidates:
            batch.append(self._candidate_params(candidate))
            if len(batch) >= batch_size:
                yield batch
                batch = []
        if batch:
            yield batch

