    def record_photo_operation(
        self,
        *,
        operation_type: str,
        label: str,
        items: list[dict[str, Any]],
        created_at: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.record_photo_operation(
                    operation_type=operation_type,
                    label=label,
                    items=items,
                    created_at=created_at,
                    conn=local_conn,
                )
