    def photo_semantic_embedding_for_asset(
        self,
        *,
        asset_id: str,
        model_name: str,
        file_size: int,
        file_mtime_ns: int,
        conn: sqlite3.Connection | None = None,
    ) -> list[float] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_semantic_embedding_for_asset(
                    asset_id=asset_id,
                    model_name=model_name,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    conn=local_conn,
                )
        row = conn.execute(
            """
            SELECT vector_json
            FROM photo_semantic_embeddings
            WHERE asset_id = ?
                AND model_name = ?
                AND file_size = ?
                AND file_mtime_ns = ?
            LIMIT 1
            """,
            (str(asset_id or ""), str(model_name or ""), int(file_size), int(file_mtime_ns)),
        ).fetchone()
        if row is None:
            return None
        try:
            values = json.loads(str(row["vector_json"] or "[]"))
        except json.JSONDecodeError:
            return None
        if not isinstance(values, list):
            return None
        vector: list[float] = []
        for value in values:
            try:
                number = float(value)
            except (TypeError, ValueError):
                return None
            if not math.isfinite(number):
                return None
            vector.append(number)
        return vector or None

    def photo_semantic_index_generation(self, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_semantic_index_generation(local_conn)
        row = conn.execute(
            "SELECT value FROM meta WHERE key = ? LIMIT 1",
            (PHOTO_SEMANTIC_INDEX_GENERATION_META_KEY,),
        ).fetchone()
        try:
            return max(0, int(row["value"] if row is not None else 0))
        except (TypeError, ValueError):
            return 0

    def video_semantic_index_generation(self, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.video_semantic_index_generation(local_conn)
        row = conn.execute(
            "SELECT value FROM meta WHERE key = ? LIMIT 1",
            (VIDEO_SEMANTIC_INDEX_GENERATION_META_KEY,),
        ).fetchone()
        try:
            return max(0, int(row["value"] if row is not None else 0))
        except (TypeError, ValueError):
            return 0

    def photo_semantic_index_snapshot(
        self,
        *,
        model_name: str,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_semantic_index_snapshot(model_name=model_name, conn=local_conn)
        clean_model = str(model_name or "").strip()
        rows = conn.execute(
            """
            SELECT
                e.asset_id,
                a.source_path,
                e.file_size,
                e.file_mtime_ns,
                e.vector_json,
                e.updated_at
            FROM photo_semantic_embeddings AS e
            JOIN photo_assets AS a ON a.asset_id = e.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE e.model_name = ?
                AND a.media_kind = 'image'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY e.asset_id ASC
            """,
            (clean_model,),
        ).fetchall()
        items: list[dict[str, Any]] = []
        invalid_rows = 0
        for row in rows:
            try:
                raw_values = json.loads(str(row["vector_json"] or "[]"))
            except json.JSONDecodeError:
                invalid_rows += 1
                continue
            if not isinstance(raw_values, list) or not raw_values:
                invalid_rows += 1
                continue
            vector: list[float] = []
            valid = True
            for value in raw_values:
                try:
                    number = float(value)
                except (TypeError, ValueError):
                    valid = False
                    break
                if not math.isfinite(number):
                    valid = False
                    break
                vector.append(number)
            asset_id = str(row["asset_id"] or "").strip()
            source_path = str(row["source_path"] or "").strip()
            if not valid or not vector or not asset_id or not source_path:
                invalid_rows += 1
                continue
            items.append(
                {
                    "assetId": asset_id,
                    "sourcePath": source_path,
                    "fileSize": int(row["file_size"]),
                    "fileMtimeNs": int(row["file_mtime_ns"]),
                    "updatedAt": str(row["updated_at"] or ""),
                    "vector": vector,
                }
            )
        return {
            "generation": self.photo_semantic_index_generation(conn),
            "modelName": clean_model,
            "items": items,
            "invalidRows": invalid_rows,
            "rowCount": len(rows),
        }

    def upsert_photo_semantic_embedding(
        self,
        *,
        asset_id: str,
        model_name: str,
        source_path: str,
        file_size: int,
        file_mtime_ns: int,
        vector: Iterable[float],
        conn: sqlite3.Connection | None = None,
    ) -> None:
        if conn is None:
            with self.connect() as local_conn:
                self.upsert_photo_semantic_embedding(
                    asset_id=asset_id,
                    model_name=model_name,
                    source_path=source_path,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    vector=vector,
                    conn=local_conn,
                )
            return
        clean_asset_id = str(asset_id or "").strip()
        clean_model = str(model_name or "").strip()
        clean_source = str(source_path or "").strip()
        if not clean_asset_id or not clean_model or not clean_source:
            return
        values: list[float] = []
        for value in vector:
            try:
                number = float(value)
            except (TypeError, ValueError):
                return
            if not math.isfinite(number):
                return
            values.append(number)
        if not values:
            return
        conn.execute(
            """
            INSERT INTO photo_semantic_embeddings(
                asset_id, model_name, source_path, file_size, file_mtime_ns, vector_json, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(asset_id, model_name) DO UPDATE SET
                source_path=excluded.source_path,
                file_size=excluded.file_size,
                file_mtime_ns=excluded.file_mtime_ns,
                vector_json=excluded.vector_json,
                updated_at=excluded.updated_at
            """,
            (
                clean_asset_id,
                clean_model,
                clean_source,
                int(file_size),
                int(file_mtime_ns),
                json.dumps(values, separators=(",", ":")),
                now_iso(),
            ),
        )

    def photo_audio_index_is_current(
        self,
        *,
        asset_id: str,
        index_version: str,
        source_fingerprint: str,
        file_size: int,
        file_mtime_ns: int,
        transcription_enabled: bool,
        sound_events_enabled: bool,
        language: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> bool:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_audio_index_is_current(
                    asset_id=asset_id,
                    index_version=index_version,
                    source_fingerprint=source_fingerprint,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    transcription_enabled=transcription_enabled,
                    sound_events_enabled=sound_events_enabled,
                    language=language,
                    conn=local_conn,
                )
        row = conn.execute(
            """
            SELECT 1
            FROM photo_audio_index_state
            WHERE asset_id = ?
                AND index_version = ?
                AND source_fingerprint = ?
                AND file_size = ?
                AND file_mtime_ns = ?
                AND transcription_enabled = ?
                AND sound_events_enabled = ?
                AND language = ?
            LIMIT 1
            """,
            (
                str(asset_id or "").strip(),
                str(index_version or "").strip(),
                str(source_fingerprint or "").strip().lower(),
                int(file_size),
                int(file_mtime_ns),
                1 if transcription_enabled else 0,
                1 if sound_events_enabled else 0,
                re.sub(r"[^A-Za-z0-9_-]", "", str(language or "").strip().lower())[:16],
            ),
        ).fetchone()
        return row is not None

    @staticmethod
    def _photo_audio_segment_from_row(row: sqlite3.Row) -> dict[str, Any]:
        try:
            metadata = json.loads(str(row["metadata_json"] or "{}"))
        except (json.JSONDecodeError, TypeError, ValueError):
            metadata = {}
        confidence_value = row["confidence"]
        try:
            confidence = float(confidence_value) if confidence_value is not None else None
        except (TypeError, ValueError):
            confidence = None
        if confidence is not None and not math.isfinite(confidence):
            confidence = None
        return {
            "segmentId": str(row["segment_id"] or ""),
            "assetId": str(row["asset_id"] or ""),
            "segmentKind": str(row["segment_kind"] or ""),
            "startMs": max(0, int(row["start_ms"] or 0)),
            "endMs": max(0, int(row["end_ms"] or 0)),
            "timestampMs": max(0, int(row["timestamp_ms"] or 0)),
            "text": str(row["text"] or ""),
            "label": str(row["label"] or ""),
            "confidence": confidence,
            "language": str(row["language"] or ""),
            "modelName": str(row["model_name"] or ""),
            "modelVersion": str(row["model_version"] or ""),
            "indexVersion": str(row["index_version"] or ""),
            "sourceFingerprint": str(row["source_fingerprint"] or ""),
            "fileSize": int(row["file_size"] or -1),
            "fileMtimeNs": int(row["file_mtime_ns"] or -1),
            "metadata": metadata if isinstance(metadata, dict) else {},
            "updatedAt": str(row["updated_at"] or ""),
        }

    def replace_photo_audio_segments(
        self,
        *,
        asset_id: str,
        index_version: str,
        source_path: str,
        source_fingerprint: str,
        file_size: int,
        file_mtime_ns: int,
        transcription_enabled: bool,
        sound_events_enabled: bool,
        language: str,
        segments: Iterable[dict[str, Any]],
        conn: sqlite3.Connection | None = None,
    ) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.replace_photo_audio_segments(
                    asset_id=asset_id,
                    index_version=index_version,
                    source_path=source_path,
                    source_fingerprint=source_fingerprint,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    transcription_enabled=transcription_enabled,
                    sound_events_enabled=sound_events_enabled,
                    language=language,
                    segments=segments,
                    conn=local_conn,
                )
        clean_asset_id = str(asset_id or "").strip()
        clean_version = str(index_version or "").strip()
        clean_source = str(source_path or "").strip()
        clean_fingerprint = str(source_fingerprint or "").strip().lower()
        clean_language = re.sub(r"[^A-Za-z0-9_-]", "", str(language or "").strip().lower())[:16]
        if not clean_asset_id or not clean_version or not clean_source or not re.fullmatch(r"[a-f0-9]{64}", clean_fingerprint):
            raise ValueError("Photo audio index identity is incomplete.")
        now = now_iso()
        rows: list[tuple[Any, ...]] = []
        for raw in segments:
            if not isinstance(raw, dict):
                raise ValueError("Photo audio segment must be an object.")
            segment_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(raw.get("segmentId", "") or ""))[:160]
            segment_kind = str(raw.get("segmentKind", raw.get("kind", "")) or "").strip().lower()
            start_ms = max(0, int(raw.get("startMs", 0) or 0))
            end_ms = max(0, int(raw.get("endMs", 0) or 0))
            timestamp_ms = max(0, int(raw.get("timestampMs", start_ms) or start_ms))
            text = re.sub(r"\s+", " ", str(raw.get("text", "") or "")).strip()[:4_000]
            label = re.sub(r"\s+", " ", str(raw.get("label", "") or "")).strip()[:200]
            model_name = re.sub(r"\s+", " ", str(raw.get("modelName", raw.get("model", "")) or "")).strip()[:160]
            model_version = re.sub(r"\s+", " ", str(raw.get("modelVersion", "") or "")).strip()[:80]
            segment_language = re.sub(r"[^A-Za-z0-9_-]", "", str(raw.get("language", "") or "").strip().lower())[:16]
            if (
                not segment_id
                or segment_kind not in {"speech", "sound"}
                or end_ms <= start_ms
                or not start_ms <= timestamp_ms < end_ms
                or not model_name
                or not model_version
                or (segment_kind == "speech" and not text)
                or (segment_kind == "sound" and not label)
            ):
                raise ValueError("Photo audio segment is invalid.")
            confidence_raw = raw.get("confidence")
            confidence: float | None = None
            if confidence_raw is not None:
                confidence = float(confidence_raw)
                if not math.isfinite(confidence) or not 0.0 <= confidence <= 1.0:
                    raise ValueError("Photo audio segment confidence is invalid.")
            raw_metadata = raw.get("metadata", {})
            metadata = raw_metadata if isinstance(raw_metadata, dict) else {}
            rows.append(
                (
                    segment_id,
                    clean_asset_id,
                    segment_kind,
                    start_ms,
                    end_ms,
                    timestamp_ms,
                    text,
                    label,
                    confidence,
                    segment_language,
                    model_name,
                    model_version,
                    clean_version,
                    clean_fingerprint,
                    int(file_size),
                    int(file_mtime_ns),
                    self._clean_json_dict(metadata),
                    now,
                )
            )
        conn.execute("DELETE FROM photo_audio_segments WHERE asset_id = ?", (clean_asset_id,))
        if rows:
            conn.executemany(
                """
                INSERT INTO photo_audio_segments(
                    segment_id, asset_id, segment_kind, start_ms, end_ms, timestamp_ms,
                    text, label, confidence, language, model_name, model_version,
                    index_version, source_fingerprint, file_size, file_mtime_ns,
                    metadata_json, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
        conn.execute(
            """
            INSERT INTO photo_audio_index_state(
                asset_id, index_version, source_path, source_fingerprint, file_size,
                file_mtime_ns, transcription_enabled, sound_events_enabled, language,
                segment_count, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(asset_id) DO UPDATE SET
                index_version=excluded.index_version,
                source_path=excluded.source_path,
                source_fingerprint=excluded.source_fingerprint,
                file_size=excluded.file_size,
                file_mtime_ns=excluded.file_mtime_ns,
                transcription_enabled=excluded.transcription_enabled,
                sound_events_enabled=excluded.sound_events_enabled,
                language=excluded.language,
                segment_count=excluded.segment_count,
                updated_at=excluded.updated_at
            """,
            (
                clean_asset_id,
                clean_version,
                clean_source,
                clean_fingerprint,
                int(file_size),
                int(file_mtime_ns),
                1 if transcription_enabled else 0,
                1 if sound_events_enabled else 0,
                clean_language,
                len(rows),
                now,
            ),
        )
        self._index_photo_asset(clean_asset_id, conn)
        return len(rows)

    def list_photo_audio_segments(
        self,
        *,
        asset_id: str,
        conn: sqlite3.Connection | None = None,
    ) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_audio_segments(asset_id=asset_id, conn=local_conn)
        rows = conn.execute(
            """
            SELECT s.*
            FROM photo_audio_segments AS s
            JOIN photo_assets AS a ON a.asset_id = s.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE s.asset_id = ?
                AND a.media_kind = 'video'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY s.start_ms ASC, s.segment_kind ASC, s.segment_id ASC
            """,
            (str(asset_id or "").strip(),),
        ).fetchall()
        return [self._photo_audio_segment_from_row(row) for row in rows]

    def best_photo_audio_segments_for_assets(
        self,
        asset_ids: Iterable[str],
        query: str,
        *,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.best_photo_audio_segments_for_assets(asset_ids, query, conn=local_conn)
        clean_ids = [str(value or "").strip() for value in dict.fromkeys(asset_ids) if str(value or "").strip()]
        clean_query = re.sub(r"\s+", " ", str(query or "")).strip().casefold()
        terms = [term for term in re.findall(r"[\w'-]+", clean_query, flags=re.UNICODE) if len(term) > 1][:12]
        if not clean_ids or not clean_query:
            return {}
        candidates: dict[str, list[dict[str, Any]]] = {asset_id: [] for asset_id in clean_ids}
        for start in range(0, len(clean_ids), 800):
            chunk = clean_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT *
                FROM photo_audio_segments
                WHERE asset_id IN ({placeholders})
                ORDER BY asset_id ASC, start_ms ASC, segment_kind ASC, segment_id ASC
                """,
                tuple(chunk),
            ).fetchall()
            for row in rows:
                item = self._photo_audio_segment_from_row(row)
                haystack = self._photo_join_search_text(item["text"], item["label"]).casefold()
                if clean_query in haystack or any(term in haystack for term in terms):
                    candidates.setdefault(item["assetId"], []).append(item)

        def rank(item: dict[str, Any]) -> tuple[Any, ...]:
            haystack = self._photo_join_search_text(item.get("text", ""), item.get("label", "")).casefold()
            all_terms = bool(terms) and all(term in haystack for term in terms)
            return (
                0 if clean_query in haystack else 1 if all_terms else 2,
                0 if item.get("segmentKind") == "speech" else 1,
                -float(item.get("confidence") or 0.0),
                int(item.get("startMs", 0) or 0),
                str(item.get("segmentId", "") or ""),
            )

        return {
            asset_id: min(rows, key=rank)
            for asset_id, rows in candidates.items()
            if rows
        }

    def photo_audio_index_summary(
        self,
        *,
        index_version: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, int]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_audio_index_summary(index_version=index_version, conn=local_conn)
        clean_version = str(index_version or "").strip()
        version_sql = "AND s.index_version = ?" if clean_version else ""
        args: tuple[Any, ...] = (clean_version,) if clean_version else ()
        row = conn.execute(
            f"""
            SELECT
                (SELECT COUNT(*)
                 FROM photo_assets AS a
                 LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                 WHERE a.media_kind = 'video' AND COALESCE(m.hidden, 0) = 0 AND m.deleted_at IS NULL) AS candidate_count,
                COUNT(DISTINCT s.asset_id) AS indexed_count,
                COALESCE(SUM(s.segment_count), 0) AS segment_count,
                COALESCE(SUM((SELECT COUNT(*) FROM photo_audio_segments AS x WHERE x.asset_id = s.asset_id AND x.segment_kind = 'speech')), 0) AS transcript_count,
                COALESCE(SUM((SELECT COUNT(*) FROM photo_audio_segments AS x WHERE x.asset_id = s.asset_id AND x.segment_kind = 'sound')), 0) AS sound_event_count
            FROM photo_audio_index_state AS s
            JOIN photo_assets AS a ON a.asset_id = s.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE a.media_kind = 'video'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
                {version_sql}
            """,
            args,
        ).fetchone()
        return {
            "candidateCount": int(row["candidate_count"] or 0) if row else 0,
            "indexedCount": int(row["indexed_count"] or 0) if row else 0,
            "segmentCount": int(row["segment_count"] or 0) if row else 0,
            "transcriptCount": int(row["transcript_count"] or 0) if row else 0,
            "soundEventCount": int(row["sound_event_count"] or 0) if row else 0,
        }

    def video_semantic_segments_are_current(
        self,
        *,
        asset_id: str,
        model_name: str,
        index_version: str,
        source_fingerprint: str,
        file_size: int,
        file_mtime_ns: int,
        conn: sqlite3.Connection | None = None,
    ) -> bool:
        if conn is None:
            with self.connect() as local_conn:
                return self.video_semantic_segments_are_current(
                    asset_id=asset_id,
                    model_name=model_name,
                    index_version=index_version,
                    source_fingerprint=source_fingerprint,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    conn=local_conn,
                )
        row = conn.execute(
            """
            SELECT COUNT(*) AS segment_count
            FROM video_semantic_segments
            WHERE asset_id = ?
                AND model_name = ?
                AND index_version = ?
                AND source_fingerprint = ?
                AND file_size = ?
                AND file_mtime_ns = ?
            """,
            (
                str(asset_id or ""),
                str(model_name or ""),
                str(index_version or ""),
                str(source_fingerprint or ""),
                int(file_size),
                int(file_mtime_ns),
            ),
        ).fetchone()
        return bool(row is not None and int(row["segment_count"] or 0) > 0)

    def replace_video_semantic_segments(
        self,
        *,
        asset_id: str,
        model_name: str,
        index_version: str,
        source_path: str,
        source_fingerprint: str,
        file_size: int,
        file_mtime_ns: int,
        segments: Iterable[dict[str, Any]],
        conn: sqlite3.Connection | None = None,
    ) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.replace_video_semantic_segments(
                    asset_id=asset_id,
                    model_name=model_name,
                    index_version=index_version,
                    source_path=source_path,
                    source_fingerprint=source_fingerprint,
                    file_size=file_size,
                    file_mtime_ns=file_mtime_ns,
                    segments=segments,
                    conn=local_conn,
                )
        clean_asset_id = str(asset_id or "").strip()
        clean_model = str(model_name or "").strip()
        clean_version = str(index_version or "").strip()
        clean_source = str(source_path or "").strip()
        clean_fingerprint = str(source_fingerprint or "").strip().lower()
        if not all((clean_asset_id, clean_model, clean_version, clean_source, clean_fingerprint)):
            raise ValueError("Video semantic segment identity is incomplete.")
        now = now_iso()
        rows: list[tuple[Any, ...]] = []
        for raw in segments:
            if not isinstance(raw, dict):
                raise ValueError("Video semantic segment must be an object.")
            segment_id = str(raw.get("segmentId", "") or "").strip()
            preview_path = str(raw.get("previewPath", "") or "").strip()
            start_ms = max(0, int(raw.get("startMs", 0) or 0))
            end_ms = max(0, int(raw.get("endMs", 0) or 0))
            timestamp_ms = max(0, int(raw.get("timestampMs", 0) or 0))
            if not segment_id or not preview_path or end_ms <= start_ms or not start_ms <= timestamp_ms < end_ms:
                raise ValueError("Video semantic segment timeline is invalid.")
            vector_values = raw.get("vector")
            if not isinstance(vector_values, (list, tuple)) or not vector_values:
                raise ValueError("Video semantic segment vector is missing.")
            vector: list[float] = []
            for value in vector_values:
                number = float(value)
                if not math.isfinite(number):
                    raise ValueError("Video semantic segment vector is invalid.")
                vector.append(number)
            rows.append(
                (
                    segment_id,
                    clean_asset_id,
                    clean_model,
                    clean_version,
                    clean_source,
                    clean_fingerprint,
                    int(file_size),
                    int(file_mtime_ns),
                    start_ms,
                    end_ms,
                    timestamp_ms,
                    max(0, int(raw.get("frameIndex", 0) or 0)),
                    max(end_ms, int(raw.get("durationMs", end_ms) or end_ms)),
                    preview_path,
                    max(1, int(raw.get("sampleCount", 1) or 1)),
                    json.dumps(vector, separators=(",", ":")),
                    now,
                )
            )
        if not rows:
            raise ValueError("At least one video semantic segment is required.")
        conn.execute(
            "DELETE FROM video_semantic_segments WHERE asset_id = ? AND model_name = ?",
            (clean_asset_id, clean_model),
        )
        conn.executemany(
            """
            INSERT INTO video_semantic_segments(
                segment_id, asset_id, model_name, index_version, source_path,
                source_fingerprint, file_size, file_mtime_ns, start_ms, end_ms,
                timestamp_ms, frame_index, duration_ms, preview_path, sample_count,
                vector_json, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            rows,
        )
        return len(rows)

    def video_semantic_index_snapshot(
        self,
        *,
        model_name: str,
        index_version: str,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.video_semantic_index_snapshot(
                    model_name=model_name,
                    index_version=index_version,
                    conn=local_conn,
                )
        clean_model = str(model_name or "").strip()
        clean_version = str(index_version or "").strip()
        rows = conn.execute(
            """
            SELECT
                s.segment_id,
                s.asset_id,
                a.source_path,
                s.source_fingerprint,
                s.file_size,
                s.file_mtime_ns,
                s.start_ms,
                s.end_ms,
                s.timestamp_ms,
                s.frame_index,
                s.duration_ms,
                s.preview_path,
                s.sample_count,
                s.vector_json,
                s.updated_at
            FROM video_semantic_segments AS s
            JOIN photo_assets AS a ON a.asset_id = s.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE s.model_name = ?
                AND s.index_version = ?
                AND a.media_kind = 'video'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY s.segment_id ASC
            """,
            (clean_model, clean_version),
        ).fetchall()
        items: list[dict[str, Any]] = []
        invalid_rows = 0
        for row in rows:
            try:
                raw_values = json.loads(str(row["vector_json"] or "[]"))
            except json.JSONDecodeError:
                invalid_rows += 1
                continue
            if not isinstance(raw_values, list) or not raw_values:
                invalid_rows += 1
                continue
            try:
                vector = [float(value) for value in raw_values]
            except (TypeError, ValueError):
                invalid_rows += 1
                continue
            segment_id = str(row["segment_id"] or "").strip()
            asset_id = str(row["asset_id"] or "").strip()
            source_path = str(row["source_path"] or "").strip()
            preview_path = str(row["preview_path"] or "").strip()
            start_ms = max(0, int(row["start_ms"] or 0))
            end_ms = max(0, int(row["end_ms"] or 0))
            timestamp_ms = max(0, int(row["timestamp_ms"] or 0))
            if (
                not segment_id
                or not asset_id
                or not source_path
                or not preview_path
                or end_ms <= start_ms
                or not start_ms <= timestamp_ms < end_ms
                or not all(math.isfinite(value) for value in vector)
            ):
                invalid_rows += 1
                continue
            items.append(
                {
                    "segmentId": segment_id,
                    "assetId": asset_id,
                    "sourcePath": source_path,
                    "sourceFingerprint": str(row["source_fingerprint"] or ""),
                    "fileSize": int(row["file_size"]),
                    "fileMtimeNs": int(row["file_mtime_ns"]),
                    "startMs": start_ms,
                    "endMs": end_ms,
                    "timestampMs": timestamp_ms,
                    "frameIndex": max(0, int(row["frame_index"] or 0)),
                    "durationMs": max(end_ms, int(row["duration_ms"] or end_ms)),
                    "previewPath": preview_path,
                    "sampleCount": max(1, int(row["sample_count"] or 1)),
                    "updatedAt": str(row["updated_at"] or ""),
                    "vector": vector,
                }
            )
        return {
            "generation": self.video_semantic_index_generation(conn),
            "modelName": clean_model,
            "indexVersion": clean_version,
            "items": items,
            "invalidRows": invalid_rows,
            "rowCount": len(rows),
        }

    def _photo_duplicate_input_signature(self, conn: sqlite3.Connection) -> dict[str, Any]:
        asset_row = conn.execute(
            """
            SELECT
                COUNT(*) AS asset_count,
                SUM(CASE WHEN COALESCE(m.hidden, 0) = 0 AND m.deleted_at IS NULL THEN 1 ELSE 0 END) AS visible_asset_count,
                COALESCE(MAX(a.updated_at), '') AS max_asset_updated_at,
                COALESCE(MAX(m.updated_at), '') AS max_metadata_updated_at,
                SUM(CASE WHEN COALESCE(m.hidden, 0) != 0 THEN 1 ELSE 0 END) AS hidden_count,
                SUM(CASE WHEN m.deleted_at IS NOT NULL THEN 1 ELSE 0 END) AS deleted_count,
                COUNT(NULLIF(a.content_hash, '')) AS content_hash_count,
                COUNT(DISTINCT NULLIF(a.content_hash, '')) AS distinct_content_hash_count,
                COALESCE(SUM(LENGTH(COALESCE(a.content_hash, ''))), 0) AS content_hash_bytes,
                COALESCE(MIN(NULLIF(a.content_hash, '')), '') AS min_content_hash,
                COALESCE(MAX(NULLIF(a.content_hash, '')), '') AS max_content_hash,
                COALESCE(SUM(
                    CASE WHEN a.content_hash != '' THEN
                        LENGTH(a.content_hash) * 131
                        + COALESCE(unicode(substr(a.content_hash, 1, 1)), 0) * 17
                        + COALESCE(unicode(substr(a.content_hash, -1, 1)), 0) * 31
                        + COALESCE(unicode(substr(a.content_hash, max(1, (LENGTH(a.content_hash) + 1) / 2), 1)), 0) * 43
                    ELSE 0 END
                ), 0) AS content_hash_checksum,
                COUNT(NULLIF(a.perceptual_hash, '')) AS perceptual_hash_count,
                COUNT(DISTINCT NULLIF(a.perceptual_hash, '')) AS distinct_perceptual_hash_count,
                COALESCE(SUM(LENGTH(COALESCE(a.perceptual_hash, ''))), 0) AS perceptual_hash_bytes,
                COALESCE(MIN(NULLIF(a.perceptual_hash, '')), '') AS min_perceptual_hash,
                COALESCE(MAX(NULLIF(a.perceptual_hash, '')), '') AS max_perceptual_hash,
                COALESCE(SUM(
                    CASE WHEN a.perceptual_hash != '' THEN
                        LENGTH(a.perceptual_hash) * 131
                        + COALESCE(unicode(substr(a.perceptual_hash, 1, 1)), 0) * 17
                        + COALESCE(unicode(substr(a.perceptual_hash, -1, 1)), 0) * 31
                        + COALESCE(unicode(substr(a.perceptual_hash, max(1, (LENGTH(a.perceptual_hash) + 1) / 2), 1)), 0) * 43
                    ELSE 0 END
                ), 0) AS perceptual_hash_checksum
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            """
        ).fetchone()
        dismissal_row = conn.execute(
            """
            SELECT
                COUNT(*) AS dismissal_count,
                COALESCE(MAX(dismissed_at), '') AS max_dismissed_at
            FROM photo_duplicate_dismissals
            """
        ).fetchone()
        return {
            "version": 2,
            "assetCount": int(asset_row["asset_count"] or 0) if asset_row else 0,
            "visibleAssetCount": int(asset_row["visible_asset_count"] or 0) if asset_row else 0,
            "maxAssetUpdatedAt": str(asset_row["max_asset_updated_at"] or "") if asset_row else "",
            "maxMetadataUpdatedAt": str(asset_row["max_metadata_updated_at"] or "") if asset_row else "",
            "hiddenCount": int(asset_row["hidden_count"] or 0) if asset_row else 0,
            "deletedCount": int(asset_row["deleted_count"] or 0) if asset_row else 0,
            "contentHashCount": int(asset_row["content_hash_count"] or 0) if asset_row else 0,
            "distinctContentHashCount": int(asset_row["distinct_content_hash_count"] or 0) if asset_row else 0,
            "contentHashBytes": int(asset_row["content_hash_bytes"] or 0) if asset_row else 0,
            "minContentHash": str(asset_row["min_content_hash"] or "") if asset_row else "",
            "maxContentHash": str(asset_row["max_content_hash"] or "") if asset_row else "",
            "contentHashChecksum": int(asset_row["content_hash_checksum"] or 0) if asset_row else 0,
            "perceptualHashCount": int(asset_row["perceptual_hash_count"] or 0) if asset_row else 0,
            "distinctPerceptualHashCount": int(asset_row["distinct_perceptual_hash_count"] or 0) if asset_row else 0,
            "perceptualHashBytes": int(asset_row["perceptual_hash_bytes"] or 0) if asset_row else 0,
            "minPerceptualHash": str(asset_row["min_perceptual_hash"] or "") if asset_row else "",
            "maxPerceptualHash": str(asset_row["max_perceptual_hash"] or "") if asset_row else "",
            "perceptualHashChecksum": int(asset_row["perceptual_hash_checksum"] or 0) if asset_row else 0,
            "dismissalCount": int(dismissal_row["dismissal_count"] or 0) if dismissal_row else 0,
            "maxDismissedAt": str(dismissal_row["max_dismissed_at"] or "") if dismissal_row else "",
        }

    def _stored_photo_duplicate_input_signature(self, conn: sqlite3.Connection) -> dict[str, Any]:
        row = conn.execute("SELECT value FROM meta WHERE key = 'photoDuplicateGroupsInputSignature' LIMIT 1").fetchone()
        if row is None:
            return {}
        try:
            payload = json.loads(str(row["value"] or "{}"))
        except json.JSONDecodeError:
            return {}
        return payload if isinstance(payload, dict) else {}

    def _store_photo_duplicate_input_signature(self, conn: sqlite3.Connection, signature: dict[str, Any]) -> None:
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES('photoDuplicateGroupsInputSignature', ?)",
            (json.dumps(signature, separators=(",", ":"), sort_keys=True),),
        )

    def _mark_photo_duplicate_groups_stale(self, conn: sqlite3.Connection, *, reason: str = "") -> None:
        body = {
            "version": -1,
            "stale": True,
            "reason": str(reason or "")[:80],
            "updatedAt": now_iso(),
        }
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES('photoDuplicateGroupsInputSignature', ?)",
            (json.dumps(body, separators=(",", ":"), sort_keys=True),),
        )

    def ensure_photo_duplicate_groups(self, conn: sqlite3.Connection | None = None) -> dict[str, int | bool]:
        if conn is None:
            with self.connect() as local_conn:
                return self.ensure_photo_duplicate_groups(local_conn)
        signature = self._photo_duplicate_input_signature(conn)
        stored = self._stored_photo_duplicate_input_signature(conn)
        group_row = conn.execute("SELECT COUNT(*) AS n FROM photo_duplicate_groups").fetchone()
        item_row = conn.execute("SELECT COUNT(*) AS n FROM photo_duplicate_group_items").fetchone()
        group_count = int(group_row["n"] or 0) if group_row else 0
        item_count = int(item_row["n"] or 0) if item_row else 0
        if stored == signature:
            return {
                "rebuilt": False,
                "groups": group_count,
                "items": item_count,
            }
        if not stored and group_count > 0 and item_count > 0:
            # Legacy databases may have group rows without the denormalized
            # count/primary summaries. Repair that shape once when adopting the
            # input signature. Stable reads must remain read-only: previously
            # this loop issued one UPDATE per group on every duplicates page and
            # rail refresh even when the signature was unchanged.
            self._repair_photo_duplicate_group_summaries(conn)
            group_row = conn.execute("SELECT COUNT(*) AS n FROM photo_duplicate_groups").fetchone()
            item_row = conn.execute("SELECT COUNT(*) AS n FROM photo_duplicate_group_items").fetchone()
            self._store_photo_duplicate_input_signature(conn, signature)
            return {
                "rebuilt": False,
                "groups": int(group_row["n"] or 0) if group_row else 0,
                "items": int(item_row["n"] or 0) if item_row else 0,
            }
        result = self.rebuild_photo_duplicate_groups(conn)
        return {**result, "rebuilt": True}

    def rebuild_photo_duplicate_groups(self, conn: sqlite3.Connection | None = None) -> dict[str, int]:
        if conn is None:
            with self.connect() as local_conn:
                return self.rebuild_photo_duplicate_groups(local_conn)
        now = now_iso()
        existing_rows = conn.execute("SELECT group_id, created_at FROM photo_duplicate_groups").fetchall()
        existing_created = {str(row["group_id"] or ""): str(row["created_at"] or now) for row in existing_rows}
        dismissed_rows = conn.execute("SELECT algorithm, signature FROM photo_duplicate_dismissals").fetchall()
        dismissed_signatures = {
            (str(row["algorithm"] or ""), str(row["signature"] or ""))
            for row in dismissed_rows
        }
        conn.execute("DELETE FROM photo_duplicate_group_items")
        conn.execute("DELETE FROM photo_duplicate_groups")
        hash_rows = conn.execute(
            """
            SELECT a.content_hash, COUNT(*) AS n
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE a.content_hash != ''
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            GROUP BY a.content_hash
            HAVING COUNT(*) > 1
            ORDER BY n DESC, a.content_hash ASC
            """
        ).fetchall()
        group_count = 0
        item_count = 0
        exact_asset_ids: set[str] = set()
        for hash_row in hash_rows:
            signature = str(hash_row["content_hash"] or "")
            if not signature:
                continue
            asset_rows = conn.execute(
                """
                SELECT a.*
                FROM photo_assets AS a
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE a.content_hash = ?
                    AND COALESCE(m.hidden, 0) = 0
                    AND m.deleted_at IS NULL
                ORDER BY COALESCE(m.favorite, 0) DESC,
                    COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), a.added_at) DESC,
                    a.source_path ASC
                """,
                (signature,),
            ).fetchall()
            if len(asset_rows) < 2:
                continue
            if ("exact_hash", signature) in dismissed_signatures:
                exact_asset_ids.update(str(asset_row["asset_id"] or "") for asset_row in asset_rows)
                continue
            group_id = self._photo_duplicate_group_id("exact_hash", signature)
            primary_asset_id = str(asset_rows[0]["asset_id"] or "")
            conn.execute(
                """
                INSERT INTO photo_duplicate_groups(
                    group_id, algorithm, signature, item_count, primary_asset_id, created_at, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    group_id,
                    "exact_hash",
                    signature,
                    len(asset_rows),
                    primary_asset_id,
                    existing_created.get(group_id, now),
                    now,
                ),
            )
            for position, asset_row in enumerate(asset_rows):
                asset_id = str(asset_row["asset_id"] or "")
                conn.execute(
                    """
                    INSERT INTO photo_duplicate_group_items(group_id, asset_id, position, reason)
                    VALUES(?, ?, ?, ?)
                    """,
                    (group_id, asset_id, position, "content_hash"),
                )
                exact_asset_ids.add(asset_id)
                item_count += 1
            group_count += 1

        image_kinds = ("image", "raw", "screenshot")
        missing_hash_rows = conn.execute(
            """
            SELECT a.asset_id, a.source_path
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE a.media_kind IN (?, ?, ?)
                AND a.perceptual_hash = ''
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY a.source_path ASC
            """,
            image_kinds,
        ).fetchall()
        for row in missing_hash_rows:
            source_path = str(row["source_path"] or "")
            file_info = self._photo_asset_file_metadata(source_path)
            perceptual_hash = str(file_info.get("perceptualHash", "") or "")
            if len(perceptual_hash) != 16:
                continue
            conn.execute(
                """
                UPDATE photo_assets
                SET perceptual_hash = ?,
                    width = COALESCE(width, ?),
                    height = COALESCE(height, ?),
                    mime_type = COALESCE(NULLIF(mime_type, ''), ?),
                    updated_at = ?
                WHERE asset_id = ?
                """,
                (
                    perceptual_hash,
                    file_info.get("width"),
                    file_info.get("height"),
                    str(file_info.get("mimeType", "") or ""),
                    now,
                    str(row["asset_id"] or ""),
                ),
            )

        near_rows = conn.execute(
            """
            SELECT a.*, COALESCE(m.favorite, 0) AS metadata_favorite
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE a.media_kind IN (?, ?, ?)
                AND a.perceptual_hash != ''
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY COALESCE(m.favorite, 0) DESC,
                COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), a.added_at) DESC,
                a.source_path ASC
            """,
            image_kinds,
        ).fetchall()
        near_candidates = [
            row for row in near_rows
            if str(row["asset_id"] or "") not in exact_asset_ids
            and str(row["perceptual_hash"] or "") not in {"0000000000000000", "ffffffffffffffff"}
        ]
        row_index = {str(row["asset_id"] or ""): index for index, row in enumerate(near_candidates)}
        parents = {str(row["asset_id"] or ""): str(row["asset_id"] or "") for row in near_candidates}

        def find(asset_id: str) -> str:
            parent = parents.get(asset_id, asset_id)
            if parent != asset_id:
                parent = find(parent)
                parents[asset_id] = parent
            return parent

        def union(left: str, right: str) -> None:
            root_left = find(left)
            root_right = find(right)
            if root_left == root_right:
                return
            if row_index.get(root_right, 2_147_483_647) < row_index.get(root_left, 2_147_483_647):
                root_left, root_right = root_right, root_left
            parents[root_right] = root_left

        aspect_buckets: dict[int, list[sqlite3.Row]] = {}
        for row in near_candidates:
            width = int(row["width"] or 0)
            height = int(row["height"] or 0)
            if width <= 0 or height <= 0:
                continue
            aspect_bucket = int(round((width / height) * 20))
            aspect_buckets.setdefault(aspect_bucket, []).append(row)

        threshold = 6
        for bucket_rows in aspect_buckets.values():
            chunk_buckets: dict[tuple[int, str], list[sqlite3.Row]] = {}
            for row in bucket_rows:
                perceptual_hash = str(row["perceptual_hash"] or "")
                if len(perceptual_hash) != 16:
                    continue
                for chunk_index in range(8):
                    chunk = perceptual_hash[chunk_index * 2:chunk_index * 2 + 2]
                    chunk_buckets.setdefault((chunk_index, chunk), []).append(row)
            seen_pairs: set[tuple[str, str]] = set()
            for candidate_rows in chunk_buckets.values():
                if len(candidate_rows) < 2:
                    continue
                for left_index, left_row in enumerate(candidate_rows):
                    left_id = str(left_row["asset_id"] or "")
                    left_hash = str(left_row["perceptual_hash"] or "")
                    for right_row in candidate_rows[left_index + 1:]:
                        right_id = str(right_row["asset_id"] or "")
                        pair = tuple(sorted((left_id, right_id)))
                        if pair in seen_pairs:
                            continue
                        seen_pairs.add(pair)
                        distance = self._photo_hash_distance(left_hash, str(right_row["perceptual_hash"] or ""))
                        if distance <= threshold:
                            union(left_id, right_id)

        clusters: dict[str, list[sqlite3.Row]] = {}
        for row in near_candidates:
            asset_id = str(row["asset_id"] or "")
            clusters.setdefault(find(asset_id), []).append(row)
        for cluster_rows in clusters.values():
            if len(cluster_rows) < 2:
                continue
            cluster_rows.sort(key=lambda row: row_index.get(str(row["asset_id"] or ""), 2_147_483_647))
            hashes = sorted({str(row["perceptual_hash"] or "") for row in cluster_rows})
            signature = "|".join(hashes)
            if not signature:
                continue
            if ("perceptual_dhash", signature) in dismissed_signatures:
                continue
            group_id = self._photo_duplicate_group_id("perceptual_dhash", signature)
            primary_asset_id = str(cluster_rows[0]["asset_id"] or "")
            conn.execute(
                """
                INSERT INTO photo_duplicate_groups(
                    group_id, algorithm, signature, item_count, primary_asset_id, created_at, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    group_id,
                    "perceptual_dhash",
                    signature,
                    len(cluster_rows),
                    primary_asset_id,
                    existing_created.get(group_id, now),
                    now,
                ),
            )
            primary_hash = str(cluster_rows[0]["perceptual_hash"] or "")
            for position, asset_row in enumerate(cluster_rows):
                distance = self._photo_hash_distance(primary_hash, str(asset_row["perceptual_hash"] or ""))
                conn.execute(
                    """
                    INSERT INTO photo_duplicate_group_items(group_id, asset_id, position, reason)
                    VALUES(?, ?, ?, ?)
                    """,
                    (group_id, str(asset_row["asset_id"] or ""), position, f"perceptual_dhash:{distance}"),
                )
                item_count += 1
            group_count += 1
        self._store_photo_duplicate_input_signature(conn, self._photo_duplicate_input_signature(conn))
        return {"groups": group_count, "items": item_count}

    def dismiss_photo_duplicate_group(
        self,
        group_id: str,
        *,
        reason: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.dismiss_photo_duplicate_group(group_id, reason=reason, conn=local_conn)
        clean_group_id = str(group_id or "").strip()
        if not clean_group_id:
            raise ValueError("groupId is required.")
        self.ensure_photo_duplicate_groups(conn)
        group = self.photo_duplicate_group_by_id(clean_group_id, conn)
        if group is None:
            return {"dismissed": False, "groupId": clean_group_id}
        algorithm = str(group.get("algorithm", "") or "")
        signature = str(group.get("signature", "") or "")
        if not algorithm or not signature:
            return {"dismissed": False, "groupId": clean_group_id}
        dismissed_at = now_iso()
        conn.execute(
            """
            INSERT INTO photo_duplicate_dismissals(algorithm, signature, dismissed_at, reason)
            VALUES(?, ?, ?, ?)
            ON CONFLICT(algorithm, signature) DO UPDATE SET
                dismissed_at=excluded.dismissed_at,
                reason=excluded.reason
            """,
            (algorithm, signature, dismissed_at, str(reason or "")[:500]),
        )
        conn.execute("DELETE FROM photo_duplicate_group_items WHERE group_id = ?", (clean_group_id,))
        conn.execute("DELETE FROM photo_duplicate_groups WHERE group_id = ?", (clean_group_id,))
        return {
            "dismissed": True,
            "groupId": clean_group_id,
            "algorithm": algorithm,
            "signature": signature,
            "itemCount": int(group.get("itemCount", 0) or 0),
            "dismissedAt": dismissed_at,
        }

    def _photo_duplicate_recommendation(self, items: list[dict[str, Any]]) -> dict[str, Any]:
        if not items:
            return {
                "recommendedAssetId": "",
                "recommendedSourcePath": "",
                "recommendationScore": 0.0,
                "recommendationReasons": [],
            }

        def number(value: Any) -> float:
            try:
                return float(value or 0)
            except (TypeError, ValueError):
                return 0.0

        def file_size(item: dict[str, Any]) -> float:
            signature = item.get("fileSignature") if isinstance(item.get("fileSignature"), dict) else {}
            return number(signature.get("size"))

        def pixels(item: dict[str, Any]) -> float:
            return max(0.0, number(item.get("width")) * number(item.get("height")))

        def metadata_score(item: dict[str, Any]) -> float:
            metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            score = 0.0
            if str(metadata.get("title", "") or "").strip():
                score += 1.0
            if str(metadata.get("caption", "") or "").strip():
                score += 1.0
            keywords = metadata.get("keywords") if isinstance(metadata.get("keywords"), list) else []
            if any(str(keyword).strip() for keyword in keywords):
                score += 1.0
            if str(metadata.get("dateOverride", "") or item.get("captureDate", "") or "").strip():
                score += 1.0
            if metadata.get("locationOverride"):
                score += 0.5
            return score

        def time_text(item: dict[str, Any]) -> str:
            metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            return str(metadata.get("dateOverride", "") or item.get("captureDate", "") or item.get("addedAt", "") or "")

        max_pixels = max(pixels(item) for item in items)
        max_size = max(file_size(item) for item in items)
        max_metadata = max(metadata_score(item) for item in items)

        def score(item: dict[str, Any]) -> tuple[float, str]:
            metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            favorite = 1.0 if metadata.get("favorite") else 0.0
            missing_penalty = -1_000_000.0 if str(item.get("missingAt", "") or "").strip() else 0.0
            total = (
                missing_penalty
                + favorite * 500_000.0
                + pixels(item)
                + min(file_size(item), 500_000_000.0) / 128.0
                + metadata_score(item) * 10_000.0
            )
            return (total, time_text(item))

        recommended = max(items, key=score)
        reasons: list[str] = []
        metadata = recommended.get("metadata") if isinstance(recommended.get("metadata"), dict) else {}
        if metadata.get("favorite"):
            reasons.append("Favorite")
        if max_pixels > 0 and pixels(recommended) >= max_pixels:
            reasons.append("Highest resolution")
        if max_size > 0 and file_size(recommended) >= max_size:
            reasons.append("Largest original")
        if max_metadata > 0 and metadata_score(recommended) >= max_metadata:
            reasons.append("Most metadata")
        if not str(recommended.get("missingAt", "") or "").strip():
            reasons.append("Original available")
        if not reasons:
            reasons.append("First in duplicate group")
        return {
            "recommendedAssetId": str(recommended.get("assetId", "") or ""),
            "recommendedSourcePath": str(recommended.get("sourcePath", "") or ""),
            "recommendationScore": round(score(recommended)[0], 3),
            "recommendationReasons": reasons[:4],
        }

    def photo_duplicate_group_by_id(self, group_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_duplicate_group_by_id(group_id, local_conn)
        row = conn.execute(
            """
            SELECT group_id, algorithm, signature, item_count, primary_asset_id, created_at, updated_at
            FROM photo_duplicate_groups
            WHERE group_id = ?
            LIMIT 1
            """,
            (str(group_id or ""),),
        ).fetchone()
        if row is None:
            return None
        item_rows = conn.execute(
            """
            SELECT i.position, i.reason, a.*
            FROM photo_duplicate_group_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            WHERE i.group_id = ?
            ORDER BY i.position ASC, a.source_path ASC
            """,
            (str(row["group_id"] or ""),),
        ).fetchall()
        items: list[dict[str, Any]] = []
        for item_row in item_rows:
            asset = self._photo_asset_row(item_row, conn, {})
            items.append(
                {
                    **asset,
                    "position": int(item_row["position"] or 0),
                    "reason": str(item_row["reason"] or ""),
                    "metadata": {
                        **(asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}),
                        **self.photo_asset_metadata_by_id(str(asset.get("assetId", "")), conn),
                    },
                }
            )
        recommendation = self._photo_duplicate_recommendation(items)
        return {
            "groupId": str(row["group_id"] or ""),
            "algorithm": str(row["algorithm"] or ""),
            "signature": str(row["signature"] or ""),
            "itemCount": int(row["item_count"] or 0),
            "primaryAssetId": str(row["primary_asset_id"] or ""),
            **recommendation,
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
            "items": items,
        }

    def list_photo_duplicate_groups(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_duplicate_groups(local_conn)
        self.ensure_photo_duplicate_groups(conn)
        rows = conn.execute(
            """
            SELECT group_id, algorithm
            FROM photo_duplicate_groups
            ORDER BY CASE algorithm WHEN 'exact_hash' THEN 0 ELSE 1 END, item_count DESC, updated_at DESC, group_id ASC
            """
        ).fetchall()
        return [
            group
            for row in rows
            for group in [self.photo_duplicate_group_by_id(str(row["group_id"] or ""), conn)]
            if group is not None
        ]

    def photo_duplicate_summary(
        self,
        *,
        source_text_filters: Iterable[tuple[str, str]] = (),
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_duplicate_summary(source_text_filters=source_text_filters, conn=local_conn)
        self.ensure_photo_duplicate_groups(conn)
        source_filter_where, source_filter_args = self._photo_source_text_filter_sql_parts(source_text_filters)
        source_where_sql = "WHERE " + " AND ".join(source_filter_where) if source_filter_where else ""
        total_row = conn.execute(
            f"""
            SELECT
                COUNT(DISTINCT g.group_id) AS group_count,
                COUNT(DISTINCT i.asset_id) AS asset_count
            FROM photo_duplicate_groups AS g
            JOIN photo_duplicate_group_items AS i ON i.group_id = g.group_id
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            {source_where_sql}
            """,
            source_filter_args,
        ).fetchone()
        cover_row = conn.execute(
            f"""
            SELECT a.source_path
            FROM photo_duplicate_groups AS g
            JOIN photo_duplicate_group_items AS i ON i.group_id = g.group_id
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            {source_where_sql}
            ORDER BY CASE g.algorithm WHEN 'exact_hash' THEN 0 ELSE 1 END,
                g.item_count DESC,
                g.updated_at DESC,
                i.position ASC,
                a.source_path ASC
            LIMIT 1
            """,
            source_filter_args,
        ).fetchone()
        return {
            "count": int(total_row["asset_count"] if total_row else 0),
            "groupCount": int(total_row["group_count"] if total_row else 0),
            "coverSourcePath": str(cover_row["source_path"] or "") if cover_row else "",
        }

    def photo_duplicate_group_for_asset(self, asset_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_duplicate_group_for_asset(asset_id, local_conn)
        row = conn.execute(
            """
            SELECT i.group_id, g.algorithm
            FROM photo_duplicate_group_items AS i
            JOIN photo_duplicate_groups AS g ON g.group_id = i.group_id
            WHERE asset_id = ?
            ORDER BY CASE g.algorithm WHEN 'exact_hash' THEN 0 ELSE 1 END, g.item_count DESC, g.updated_at DESC
            LIMIT 1
            """,
            (str(asset_id or ""),),
        ).fetchone()
        if row is None:
            return None
        return self.photo_duplicate_group_by_id(str(row["group_id"] or ""), conn)

    def photo_duplicate_groups_for_assets(
        self,
        asset_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
        *,
        ensure_current: bool = True,
    ) -> dict[str, dict[str, Any]]:
        clean_ids = [str(value or "").strip() for value in dict.fromkeys(asset_ids or []) if str(value or "").strip()]
        if not clean_ids:
            return {}
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_duplicate_groups_for_assets(
                    clean_ids,
                    conn=local_conn,
                    ensure_current=ensure_current,
                )
        if ensure_current:
            self.ensure_photo_duplicate_groups(conn)
        chosen_group_by_asset: dict[str, str] = {}
        for start in range(0, len(clean_ids), 800):
            chunk = clean_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT i.asset_id, i.group_id
                FROM photo_duplicate_group_items AS i
                JOIN photo_duplicate_groups AS g ON g.group_id = i.group_id
                WHERE i.asset_id IN ({placeholders})
                ORDER BY i.asset_id ASC,
                    CASE g.algorithm WHEN 'exact_hash' THEN 0 ELSE 1 END,
                    g.item_count DESC,
                    g.updated_at DESC,
                    g.group_id ASC
                """,
                tuple(chunk),
            ).fetchall()
            for row in rows:
                asset_id = str(row["asset_id"] or "")
                group_id = str(row["group_id"] or "")
                if asset_id and group_id:
                    chosen_group_by_asset.setdefault(asset_id, group_id)
        group_ids = list(dict.fromkeys(chosen_group_by_asset.values()))
        if not group_ids:
            return {}
        placeholders = ",".join("?" for _ in group_ids)
        group_rows = conn.execute(
            f"""
            SELECT group_id, algorithm, signature, item_count, primary_asset_id, created_at, updated_at
            FROM photo_duplicate_groups
            WHERE group_id IN ({placeholders})
            """,
            tuple(group_ids),
        ).fetchall()
        item_rows = conn.execute(
            f"""
            SELECT group_id, asset_id, position, reason
            FROM photo_duplicate_group_items
            WHERE group_id IN ({placeholders})
            ORDER BY group_id ASC, position ASC, asset_id ASC
            """,
            tuple(group_ids),
        ).fetchall()
        item_asset_ids = [str(row["asset_id"] or "") for row in item_rows if str(row["asset_id"] or "")]
        assets_by_id = {
            str(asset.get("assetId", "") or ""): asset
            for asset in self.photo_assets_by_ids(item_asset_ids, conn=conn)
            if str(asset.get("assetId", "") or "")
        }
        metadata_by_id = self.photo_asset_metadata_by_ids(item_asset_ids, conn=conn)
        items_by_group: dict[str, list[dict[str, Any]]] = {group_id: [] for group_id in group_ids}
        for row in item_rows:
            group_id = str(row["group_id"] or "")
            asset_id = str(row["asset_id"] or "")
            asset = assets_by_id.get(asset_id)
            if not group_id or not asset:
                continue
            items_by_group.setdefault(group_id, []).append({
                **asset,
                "position": int(row["position"] or 0),
                "reason": str(row["reason"] or ""),
                "metadata": {
                    **(asset.get("metadata") if isinstance(asset.get("metadata"), dict) else {}),
                    **metadata_by_id.get(asset_id, {}),
                },
            })
        groups: dict[str, dict[str, Any]] = {}
        for row in group_rows:
            group_id = str(row["group_id"] or "")
            items = items_by_group.get(group_id, [])
            groups[group_id] = {
                "groupId": group_id,
                "algorithm": str(row["algorithm"] or ""),
                "signature": str(row["signature"] or ""),
                "itemCount": int(row["item_count"] or 0),
                "primaryAssetId": str(row["primary_asset_id"] or ""),
                **self._photo_duplicate_recommendation(items),
                "createdAt": str(row["created_at"] or ""),
                "updatedAt": str(row["updated_at"] or ""),
                "items": items,
            }
        return {
            asset_id: groups[group_id]
            for asset_id, group_id in chosen_group_by_asset.items()
            if group_id in groups
        }

    def merge_photo_duplicate_group(
        self,
        group_id: str,
        *,
        keep_asset_id: str = "",
        deleted_at: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.merge_photo_duplicate_group(group_id, keep_asset_id=keep_asset_id, deleted_at=deleted_at, conn=local_conn)
        self.ensure_photo_duplicate_groups(conn)
        group = self.photo_duplicate_group_by_id(group_id, conn)
        if group is None:
            raise ValueError("Unknown duplicate group id.")
        item_ids = [str(item.get("assetId", "") or "") for item in group.get("items", [])]
        keep_id = str(keep_asset_id or group.get("primaryAssetId", "") or "").strip()
        if keep_id not in item_ids:
            raise ValueError("keepAssetId must belong to the duplicate group.")
        when = str(deleted_at or "") or now_iso()
        removed: list[str] = []
        operation_items: list[dict[str, Any]] = []
        for asset_key in item_ids:
            if asset_key == keep_id:
                continue
            asset = self.photo_asset_by_id(asset_key, conn)
            previous = self._photo_operation_metadata_state(asset_key, conn)
            self.update_photo_asset_metadata(asset_id=asset_key, deleted_at=when, conn=conn)
            removed.append(asset_key)
            if asset:
                operation_items.append(
                    {
                        "assetId": asset_key,
                        "sourcePath": str(asset.get("sourcePath", "") or ""),
                        "previous": previous,
                        "next": {
                            "hidden": bool(previous.get("hidden")),
                            "deletedAt": when,
                        },
                    }
                )
        self._mark_photo_duplicate_groups_stale(conn, reason="duplicate_merge")
        operation = self.record_photo_operation(
            operation_type="duplicate_merge",
            label=f"Merged {len(operation_items)} duplicate photo{'s' if len(operation_items) != 1 else ''}",
            items=operation_items,
            conn=conn,
        )
        return {
            "groupId": str(group.get("groupId", "")),
            "keptAssetId": keep_id,
            "deletedAssetIds": removed,
            "merged": len(removed),
            "deletedAt": when,
            "operation": operation,
        }

    def list_photo_asset_people(self, asset_id: str, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_asset_people(asset_id, local_conn)
        rows = conn.execute(
            """
            SELECT asset_id, candidate_id, person_name, status, score, quality, band, updated_at
            FROM photo_asset_people
            WHERE asset_id = ?
            ORDER BY score DESC, quality DESC, person_name ASC, candidate_id ASC
            """,
            (str(asset_id or ""),),
        ).fetchall()
        return [
            {
                "assetId": str(row["asset_id"] or ""),
                "candidateId": str(row["candidate_id"] or ""),
                "personName": str(row["person_name"] or ""),
                "status": str(row["status"] or "pending"),
                "score": float(row["score"] or 0.0),
                "quality": float(row["quality"] or 0.0),
                "band": str(row["band"] or ""),
                "assetOnly": str(row["candidate_id"] or "").startswith("asset_person_"),
                "updatedAt": str(row["updated_at"] or ""),
            }
            for row in rows
        ]

    def photo_asset_people_by_ids(
        self,
        asset_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, list[dict[str, Any]]]:
        clean_ids: list[str] = []
        seen: set[str] = set()
        for asset_id in asset_ids:
            clean_id = str(asset_id or "")
            if not clean_id or clean_id in seen:
                continue
            seen.add(clean_id)
            clean_ids.append(clean_id)
        if not clean_ids:
            return {}
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_asset_people_by_ids(clean_ids, local_conn)
        people_by_asset_id: dict[str, list[dict[str, Any]]] = {asset_id: [] for asset_id in clean_ids}
        for start in range(0, len(clean_ids), 800):
            chunk = clean_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT asset_id, candidate_id, person_name, status, score, quality, band, updated_at
                FROM photo_asset_people
                WHERE asset_id IN ({placeholders})
                ORDER BY asset_id ASC, score DESC, quality DESC, person_name ASC, candidate_id ASC
                """,
                tuple(chunk),
            ).fetchall()
            for row in rows:
                asset_id = str(row["asset_id"] or "")
                people_by_asset_id.setdefault(asset_id, []).append(
                    {
                        "assetId": asset_id,
                        "candidateId": str(row["candidate_id"] or ""),
                        "personName": str(row["person_name"] or ""),
                        "status": str(row["status"] or "pending"),
                        "score": float(row["score"] or 0.0),
                        "quality": float(row["quality"] or 0.0),
                        "band": str(row["band"] or ""),
                        "assetOnly": str(row["candidate_id"] or "").startswith("asset_person_"),
                        "updatedAt": str(row["updated_at"] or ""),
                    }
                )
        return people_by_asset_id

    def photo_person_presence_count(
        self,
        person_name: str,
        conn: sqlite3.Connection | None = None,
    ) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_person_presence_count(person_name, local_conn)
        person = str(person_name or "").strip()
        if not person:
            return 0
        row = conn.execute(
            "SELECT COUNT(*) AS n FROM photo_asset_people WHERE LOWER(person_name) = LOWER(?)",
            (person,),
        ).fetchone()
        return int(row["n"] or 0) if row else 0

    def photo_relationship_graph(
        self,
        *,
        confident_threshold: float,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, list[dict[str, Any]]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_relationship_graph(
                    confident_threshold=confident_threshold,
                    conn=local_conn,
                )
        threshold = max(0.0, min(1.0, float(confident_threshold)))
        rows = conn.execute(
            """
            WITH raw_valid AS (
                SELECT DISTINCT
                    p.asset_id AS asset_id,
                    TRIM(p.person_name) AS person_name,
                    LOWER(TRIM(p.person_name)) AS person_key
                FROM photo_asset_people AS p
                INNER JOIN photo_assets AS a ON a.asset_id = p.asset_id
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE TRIM(COALESCE(p.person_name, '')) != ''
                    AND COALESCE(a.missing_at, '') = ''
                    AND COALESCE(m.hidden, 0) = 0
                    AND COALESCE(m.deleted_at, '') = ''
                    AND LOWER(COALESCE(p.status, 'pending')) != 'rejected'
                    AND (
                        (
                            LOWER(TRIM(p.person_name)) LIKE 'unmatched cluster%'
                        )
                        OR (
                            LOWER(TRIM(p.person_name)) NOT LIKE 'unmatched cluster%'
                            AND (
                                LOWER(COALESCE(p.status, '')) = 'accepted'
                                OR LOWER(TRIM(COALESCE(p.band, ''))) = 'manual assignment'
                                OR COALESCE(p.score, 0) >= ?
                            )
                        )
                    )
            ),
            valid AS (
                SELECT asset_id, person_key, MIN(person_name) AS person_name
                FROM raw_valid
                GROUP BY asset_id, person_key
            ),
            nodes AS (
                SELECT
                    'node' AS row_kind,
                    person_key AS key_a,
                    '' AS key_b,
                    MIN(person_name) AS person_a,
                    '' AS person_b,
                    COUNT(*) AS item_count
                FROM valid
                GROUP BY person_key
            ),
            edges AS (
                SELECT
                    'edge' AS row_kind,
                    left_person.person_key AS key_a,
                    right_person.person_key AS key_b,
                    MIN(left_person.person_name) AS person_a,
                    MIN(right_person.person_name) AS person_b,
                    COUNT(*) AS item_count
                FROM valid AS left_person
                INNER JOIN valid AS right_person
                    ON right_person.asset_id = left_person.asset_id
                    AND right_person.person_key > left_person.person_key
                GROUP BY left_person.person_key, right_person.person_key
            )
            SELECT row_kind, key_a, key_b, person_a, person_b, item_count FROM nodes
            UNION ALL
            SELECT row_kind, key_a, key_b, person_a, person_b, item_count FROM edges
            ORDER BY row_kind DESC, key_a ASC, key_b ASC
            """,
            (threshold,),
        ).fetchall()
        nodes: list[dict[str, Any]] = []
        edges: list[dict[str, Any]] = []
        for row in rows:
            if str(row["row_kind"] or "") == "node":
                nodes.append({
                    "personName": str(row["person_a"] or ""),
                    "assetCount": int(row["item_count"] or 0),
                })
            else:
                edges.append({
                    "personA": str(row["person_a"] or ""),
                    "personB": str(row["person_b"] or ""),
                    "cooccurrenceCount": int(row["item_count"] or 0),
                })
        return {"nodes": nodes, "edges": edges}

    def photo_relationship_name_review(
        self,
        suggestion_id: str,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_relationship_name_review(suggestion_id, local_conn)
        row = conn.execute(
            """
            SELECT suggestion_id, source_cluster, target_person, evidence_hash, decision,
                   idempotency_key, operation_id, result_json, reviewed_at
            FROM photo_relationship_name_reviews
            WHERE suggestion_id = ?
            LIMIT 1
            """,
            (str(suggestion_id or "").strip(),),
        ).fetchone()
        if row is None:
            return None
        try:
            result = json.loads(str(row["result_json"] or "{}"))
        except (TypeError, ValueError):
            result = {}
        return {
            "suggestionId": str(row["suggestion_id"] or ""),
            "sourceCluster": str(row["source_cluster"] or ""),
            "targetPerson": str(row["target_person"] or ""),
            "evidenceHash": str(row["evidence_hash"] or ""),
            "decision": str(row["decision"] or ""),
            "idempotencyKey": str(row["idempotency_key"] or ""),
            "operationId": str(row["operation_id"] or ""),
            "result": result if isinstance(result, dict) else {},
            "reviewedAt": str(row["reviewed_at"] or ""),
        }

    def photo_relationship_name_review_by_idempotency_key(
        self,
        idempotency_key: str,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_relationship_name_review_by_idempotency_key(idempotency_key, local_conn)
        clean_key = str(idempotency_key or "").strip()[:200]
        if not clean_key:
            return None
        row = conn.execute(
            """
            SELECT suggestion_id
            FROM photo_relationship_name_reviews
            WHERE idempotency_key = ?
            LIMIT 1
            """,
            (clean_key,),
        ).fetchone()
        if row is None:
            return None
        return self.photo_relationship_name_review(str(row["suggestion_id"] or ""), conn)

    def photo_relationship_name_reviewed_ids(
        self,
        *,
        decisions: Iterable[str] = ("dismissed", "applied"),
        conn: sqlite3.Connection | None = None,
    ) -> set[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_relationship_name_reviewed_ids(decisions=decisions, conn=local_conn)
        clean = sorted({str(value or "").strip().lower() for value in decisions if str(value or "").strip()})
        if not clean:
            return set()
        placeholders = ",".join("?" for _ in clean)
        rows = conn.execute(
            f"SELECT suggestion_id FROM photo_relationship_name_reviews WHERE LOWER(decision) IN ({placeholders})",
            tuple(clean),
        ).fetchall()
        return {str(row["suggestion_id"] or "") for row in rows if str(row["suggestion_id"] or "")}

    def delete_photo_relationship_name_reviews_for_people(
        self,
        person_names: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> int:
        clean = sorted({
            " ".join(str(value or "").strip().split()).casefold()
            for value in person_names
            if str(value or "").strip()
        })
        if not clean:
            return 0
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_relationship_name_reviews_for_people(clean, local_conn)
        rows = conn.execute(
            "SELECT suggestion_id, source_cluster, target_person FROM photo_relationship_name_reviews"
        ).fetchall()
        suggestion_ids = [
            str(row["suggestion_id"] or "")
            for row in rows
            if (
                " ".join(str(row["source_cluster"] or "").strip().split()).casefold() in clean
                or " ".join(str(row["target_person"] or "").strip().split()).casefold() in clean
            )
        ]
        deleted = 0
        for start in range(0, len(suggestion_ids), 800):
            chunk = suggestion_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            cursor = conn.execute(
                f"DELETE FROM photo_relationship_name_reviews WHERE suggestion_id IN ({placeholders})",
                tuple(chunk),
            )
            deleted += int(cursor.rowcount or 0)
        return deleted

    def save_photo_relationship_name_review(
        self,
        *,
        suggestion_id: str,
        source_cluster: str,
        target_person: str,
        evidence_hash: str,
        decision: str,
        idempotency_key: str = "",
        operation_id: str = "",
        result: dict[str, Any] | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.save_photo_relationship_name_review(
                    suggestion_id=suggestion_id,
                    source_cluster=source_cluster,
                    target_person=target_person,
                    evidence_hash=evidence_hash,
                    decision=decision,
                    idempotency_key=idempotency_key,
                    operation_id=operation_id,
                    result=result,
                    conn=local_conn,
                )
        suggestion = str(suggestion_id or "").strip()[:120]
        source = " ".join(str(source_cluster or "").strip().split())[:200]
        target = " ".join(str(target_person or "").strip().split())[:200]
        evidence = str(evidence_hash or "").strip().lower()[:64]
        decision_key = str(decision or "").strip().lower()
        idempotency = str(idempotency_key or "").strip()[:200]
        if not suggestion or not source or not target or len(evidence) != 64:
            raise ValueError("A complete relationship suggestion identity is required.")
        if decision_key not in {"dismissed", "applied"}:
            raise ValueError("Relationship suggestion decision must be dismissed or applied.")
        if decision_key == "applied" and not idempotency:
            raise ValueError("Applied relationship suggestions require an idempotency key.")
        reviewed_at = now_iso()
        conn.execute(
            """
            INSERT INTO photo_relationship_name_reviews(
                suggestion_id, source_cluster, target_person, evidence_hash, decision,
                idempotency_key, operation_id, result_json, reviewed_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(suggestion_id) DO UPDATE SET
                source_cluster=excluded.source_cluster,
                target_person=excluded.target_person,
                evidence_hash=excluded.evidence_hash,
                decision=excluded.decision,
                idempotency_key=excluded.idempotency_key,
                operation_id=excluded.operation_id,
                result_json=excluded.result_json,
                reviewed_at=excluded.reviewed_at
            """,
            (
                suggestion,
                source,
                target,
                evidence,
                decision_key,
                idempotency,
                str(operation_id or "").strip()[:120],
                json.dumps(result or {}, sort_keys=True, separators=(",", ":")),
                reviewed_at,
            ),
        )
        saved = self.photo_relationship_name_review(suggestion, conn)
        if saved is None:
            raise sqlite3.DatabaseError("Relationship suggestion review was not saved.")
        return saved

    def _photo_person_profile_row(self, row: sqlite3.Row | dict[str, Any] | None, person_name: str = "") -> dict[str, Any]:
        if row is None:
            return {
                "personName": str(person_name or ""),
                "keyAssetId": "",
                "keyAssetCrop": {},
                "favorite": False,
                "hidden": False,
                "manualOrder": None,
                "createdAt": "",
                "updatedAt": "",
            }
        manual_order = row["manual_order"]
        try:
            key_asset_crop = json.loads(str(row["key_asset_crop_json"] or "{}"))
        except (TypeError, ValueError):
            key_asset_crop = {}
        if not isinstance(key_asset_crop, dict):
            key_asset_crop = {}
        return {
            "personName": str(row["person_name"] or person_name or ""),
            "keyAssetId": str(row["key_asset_id"] or ""),
            "keyAssetCrop": key_asset_crop,
            "favorite": bool(row["favorite"]),
            "hidden": bool(row["hidden"]),
            "manualOrder": int(manual_order) if manual_order is not None else None,
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def _photo_person_key_asset_crop(self, value: Any) -> dict[str, float]:
        if not isinstance(value, dict):
            return {}
        try:
            left = float(value.get("left", value.get("x", 0)) or 0)
            top = float(value.get("top", value.get("y", 0)) or 0)
            width = float(value.get("width", value.get("w", 100)) or 100)
            height = float(value.get("height", value.get("h", 100)) or 100)
        except (TypeError, ValueError):
            return {}
        width = max(1.0, min(100.0, width))
        height = max(1.0, min(100.0, height))
        left = max(0.0, min(100.0 - width, left))
        top = max(0.0, min(100.0 - height, top))
        if left <= 0.001 and top <= 0.001 and width >= 99.999 and height >= 99.999:
            return {}
        return {
            "left": round(left, 3),
            "top": round(top, 3),
            "width": round(width, 3),
            "height": round(height, 3),
        }

    def photo_person_profile(self, person_name: str, conn: sqlite3.Connection | None = None) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_person_profile(person_name, local_conn)
        person = str(person_name or "").strip()
        if not person:
            return self._photo_person_profile_row(None)
        row = conn.execute(
            """
            SELECT person_name, key_asset_id, key_asset_crop_json, favorite, hidden, manual_order, created_at, updated_at
            FROM photo_people_profiles
            WHERE person_name = ?
            LIMIT 1
            """,
            (person,),
        ).fetchone()
        return self._photo_person_profile_row(row, person)

    def list_photo_people_profiles(self, conn: sqlite3.Connection | None = None) -> dict[str, dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_people_profiles(local_conn)
        rows = conn.execute(
            """
            SELECT person_name, key_asset_id, key_asset_crop_json, favorite, hidden, manual_order, created_at, updated_at
            FROM photo_people_profiles
            ORDER BY favorite DESC, hidden ASC, COALESCE(manual_order, 2147483647) ASC, LOWER(person_name) ASC
            """
        ).fetchall()
        return {str(row["person_name"] or ""): self._photo_person_profile_row(row) for row in rows}

    def save_photo_person_profile(
        self,
        *,
        person_name: str,
        key_asset_id: str | None = None,
        key_asset_crop: dict[str, Any] | None = None,
        favorite: bool | None = None,
        hidden: bool | None = None,
        manual_order: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.save_photo_person_profile(
                    person_name=person_name,
                    key_asset_id=key_asset_id,
                    key_asset_crop=key_asset_crop,
                    favorite=favorite,
                    hidden=hidden,
                    manual_order=manual_order,
                    conn=local_conn,
                )
        person = str(person_name or "").strip()
        if not person:
            raise ValueError("personName is required.")
        current = self.photo_person_profile(person, conn)
        next_key_asset_id = str(key_asset_id if key_asset_id is not None else current.get("keyAssetId", "") or "").strip()
        if next_key_asset_id:
            row = conn.execute("SELECT asset_id FROM photo_assets WHERE asset_id = ? LIMIT 1", (next_key_asset_id,)).fetchone()
            if row is None:
                raise ValueError("keyAssetId must identify a known photo asset.")
        next_key_asset_crop = self._photo_person_key_asset_crop(
            key_asset_crop if key_asset_crop is not None else current.get("keyAssetCrop", {})
        )
        if not next_key_asset_id:
            next_key_asset_crop = {}
        next_favorite = bool(favorite if favorite is not None else current.get("favorite", False))
        next_hidden = bool(hidden if hidden is not None else current.get("hidden", False))
        next_order = manual_order if manual_order is not None else current.get("manualOrder")
        if next_order is not None:
            next_order = max(0, min(2_147_483_647, int(next_order)))
        now = now_iso()
        created_at = str(current.get("createdAt", "") or now)
        conn.execute(
            """
            INSERT INTO photo_people_profiles(
                person_name, key_asset_id, key_asset_crop_json, favorite, hidden, manual_order, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(person_name) DO UPDATE SET
                key_asset_id=excluded.key_asset_id,
                key_asset_crop_json=excluded.key_asset_crop_json,
                favorite=excluded.favorite,
                hidden=excluded.hidden,
                manual_order=excluded.manual_order,
                updated_at=excluded.updated_at
            """,
            (
                person,
                next_key_asset_id,
                json.dumps(next_key_asset_crop, sort_keys=True, separators=(",", ":")),
                int(next_favorite),
                int(next_hidden),
                next_order,
                created_at,
                now,
            ),
        )
        return self.photo_person_profile(person, conn)

    def _photo_pet_profile_row(self, row: sqlite3.Row | dict[str, Any] | None, pet_name: str = "") -> dict[str, Any]:
        if row is None:
            return {
                "petName": str(pet_name or ""),
                "petKind": "pet",
                "keyAssetId": "",
                "favorite": False,
                "hidden": False,
                "manualOrder": None,
                "createdAt": "",
                "updatedAt": "",
            }
        manual_order = row["manual_order"]
        pet_kind = str(row["pet_kind"] or "pet").strip().lower() or "pet"
        return {
            "petName": str(row["pet_name"] or pet_name or ""),
            "petKind": pet_kind,
            "keyAssetId": str(row["key_asset_id"] or ""),
            "favorite": bool(row["favorite"]),
            "hidden": bool(row["hidden"]),
            "manualOrder": int(manual_order) if manual_order is not None else None,
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def photo_pet_profile(self, pet_name: str, conn: sqlite3.Connection | None = None) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_pet_profile(pet_name, local_conn)
        pet = str(pet_name or "").strip()
        if not pet:
            return self._photo_pet_profile_row(None)
        row = conn.execute(
            """
            SELECT pet_name, pet_kind, key_asset_id, favorite, hidden, manual_order, created_at, updated_at
            FROM photo_pet_profiles
            WHERE pet_name = ?
            LIMIT 1
            """,
            (pet,),
        ).fetchone()
        return self._photo_pet_profile_row(row, pet)

    def list_photo_pet_profiles(self, conn: sqlite3.Connection | None = None) -> dict[str, dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_pet_profiles(local_conn)
        rows = conn.execute(
            """
            SELECT pet_name, pet_kind, key_asset_id, favorite, hidden, manual_order, created_at, updated_at
            FROM photo_pet_profiles
            ORDER BY favorite DESC, hidden ASC, COALESCE(manual_order, 2147483647) ASC, LOWER(pet_name) ASC
            """
        ).fetchall()
        return {str(row["pet_name"] or ""): self._photo_pet_profile_row(row) for row in rows}

    def save_photo_pet_profile(
        self,
        *,
        pet_name: str,
        pet_kind: str | None = None,
        key_asset_id: str | None = None,
        favorite: bool | None = None,
        hidden: bool | None = None,
        manual_order: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.save_photo_pet_profile(
                    pet_name=pet_name,
                    pet_kind=pet_kind,
                    key_asset_id=key_asset_id,
                    favorite=favorite,
                    hidden=hidden,
                    manual_order=manual_order,
                    conn=local_conn,
                )
        pet = str(pet_name or "").strip()
        if not pet:
            raise ValueError("petName is required.")
        current = self.photo_pet_profile(pet, conn)
        next_kind = str(pet_kind if pet_kind is not None else current.get("petKind", "pet") or "pet").strip().lower() or "pet"
        next_kind = re.sub(r"[^a-z0-9_ -]+", "", next_kind).replace(" ", "_")[:32] or "pet"
        next_key_asset_id = str(key_asset_id if key_asset_id is not None else current.get("keyAssetId", "") or "").strip()
        if next_key_asset_id:
            row = conn.execute("SELECT asset_id FROM photo_assets WHERE asset_id = ? LIMIT 1", (next_key_asset_id,)).fetchone()
            if row is None:
                raise ValueError("keyAssetId must identify a known photo asset.")
        next_favorite = bool(favorite if favorite is not None else current.get("favorite", False))
        next_hidden = bool(hidden if hidden is not None else current.get("hidden", False))
        next_order = manual_order if manual_order is not None else current.get("manualOrder")
        if next_order is not None:
            next_order = max(0, min(2_147_483_647, int(next_order)))
        now = now_iso()
        created_at = str(current.get("createdAt", "") or now)
        conn.execute(
            """
            INSERT INTO photo_pet_profiles(
                pet_name, pet_kind, key_asset_id, favorite, hidden, manual_order, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(pet_name) DO UPDATE SET
                pet_kind=excluded.pet_kind,
                key_asset_id=excluded.key_asset_id,
                favorite=excluded.favorite,
                hidden=excluded.hidden,
                manual_order=excluded.manual_order,
                updated_at=excluded.updated_at
            """,
            (
                pet,
                next_kind,
                next_key_asset_id,
                int(next_favorite),
                int(next_hidden),
                next_order,
                created_at,
                now,
            ),
        )
        return self.photo_pet_profile(pet, conn)

    def rename_photo_pet_profile(
        self,
        old_name: str,
        new_name: str,
        *,
        pet_kind: str | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.rename_photo_pet_profile(old_name, new_name, pet_kind=pet_kind, conn=local_conn)
        old_pet = str(old_name or "").strip()
        new_pet = str(new_name or "").strip()
        if not old_pet or not new_pet:
            raise ValueError("Both current and new pet names are required.")
        if old_pet.casefold() == new_pet.casefold():
            return {
                "profileMoved": False,
                "profileMerged": False,
                "profile": self.photo_pet_profile(new_pet, conn),
            }

        old_profile = self.photo_pet_profile(old_pet, conn)
        target_profile = self.photo_pet_profile(new_pet, conn)
        old_exists = bool(
            old_profile.get("createdAt")
            or old_profile.get("keyAssetId")
            or old_profile.get("favorite")
            or old_profile.get("hidden")
            or old_profile.get("manualOrder") is not None
            or str(old_profile.get("petKind", "") or "").strip().lower() not in {"", "pet"}
        )
        target_exists = bool(
            target_profile.get("createdAt")
            or target_profile.get("keyAssetId")
            or target_profile.get("favorite")
            or target_profile.get("hidden")
            or target_profile.get("manualOrder") is not None
            or str(target_profile.get("petKind", "") or "").strip().lower() not in {"", "pet"}
        )
        if not old_exists:
            return {
                "profileMoved": False,
                "profileMerged": False,
                "profile": self.photo_pet_profile(new_pet, conn),
            }

        requested_kind = str(pet_kind or "").strip().lower()
        target_kind = str(target_profile.get("petKind", "") or "").strip().lower()
        old_kind = str(old_profile.get("petKind", "") or "").strip().lower()
        next_kind = requested_kind or (target_kind if target_kind and target_kind != "pet" else "") or (old_kind if old_kind else "") or target_kind or "pet"
        next_kind = re.sub(r"[^a-z0-9_ -]+", "", next_kind).replace(" ", "_")[:32] or "pet"
        next_key_asset_id = str(target_profile.get("keyAssetId", "") or old_profile.get("keyAssetId", "") or "")
        next_favorite = bool(target_profile.get("favorite", False) or old_profile.get("favorite", False))
        next_hidden = bool(target_profile.get("hidden", False) if target_exists else old_profile.get("hidden", False))
        next_order = target_profile.get("manualOrder") if target_profile.get("manualOrder") is not None else old_profile.get("manualOrder")
        now = now_iso()
        created_at = str(target_profile.get("createdAt", "") or old_profile.get("createdAt", "") or now)
        conn.execute("DELETE FROM photo_pet_profiles WHERE LOWER(pet_name) = LOWER(?)", (old_pet,))
        conn.execute(
            """
            INSERT INTO photo_pet_profiles(
                pet_name, pet_kind, key_asset_id, favorite, hidden, manual_order, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(pet_name) DO UPDATE SET
                pet_kind=excluded.pet_kind,
                key_asset_id=excluded.key_asset_id,
                favorite=excluded.favorite,
                hidden=excluded.hidden,
                manual_order=excluded.manual_order,
                updated_at=excluded.updated_at
            """,
            (
                new_pet,
                next_kind,
                next_key_asset_id,
                int(next_favorite),
                int(next_hidden),
                next_order,
                created_at,
                now,
            ),
        )
        self._bump_photo_smart_album_materialization_revision(conn, reason="rename_photo_pet_profile")
        return {
            "profileMoved": not target_exists,
            "profileMerged": target_exists,
            "profile": self.photo_pet_profile(new_pet, conn),
        }

    def rename_photo_person_profile(
        self,
        old_name: str,
        new_name: str,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.rename_photo_person_profile(old_name, new_name, local_conn)
        old_person = str(old_name or "").strip()
        new_person = str(new_name or "").strip()
        if not old_person or not new_person:
            raise ValueError("Both current and new person names are required.")
        if old_person.casefold() == new_person.casefold():
            return {"peopleRows": 0, "groupRows": 0, "profileMoved": False, "profileMerged": False}

        now = now_iso()
        affected_asset_ids = [
            str(row["asset_id"] or "")
            for row in conn.execute(
                """
                SELECT DISTINCT asset_id
                FROM photo_asset_people
                WHERE LOWER(person_name) = LOWER(?)
                """,
                (old_person,),
            ).fetchall()
            if str(row["asset_id"] or "")
        ]
        updated_people = conn.execute(
            "UPDATE photo_asset_people SET person_name = ?, updated_at = ? WHERE LOWER(person_name) = LOWER(?)",
            (new_person, now, old_person),
        ).rowcount
        for asset_id in affected_asset_ids:
            self._index_photo_asset(asset_id, conn)

        def rewrite_people(values: Iterable[str]) -> tuple[list[str], bool]:
            rewritten: list[str] = []
            seen: set[str] = set()
            changed = False
            for value in values:
                person = str(value or "").strip()
                if not person:
                    continue
                next_person = new_person if person.casefold() == old_person.casefold() else person
                changed = changed or next_person != person
                key = next_person.casefold()
                if key in seen:
                    changed = True
                    continue
                seen.add(key)
                rewritten.append(next_person)
            return rewritten, changed

        def default_group_name(people: Iterable[str], pets: Iterable[str]) -> str:
            names = [
                str(value or "").strip()
                for value in [*list(people), *list(pets)]
                if str(value or "").strip()
            ]
            if len(names) <= 2:
                return " & ".join(names)
            return f"{', '.join(names[:-1])} & {names[-1]}"

        group_rows = 0
        for group in self.list_photo_people_groups(conn):
            member_people, changed_members = rewrite_people(group.get("memberPeople", []))
            exclude_people, changed_excluded = rewrite_people(group.get("excludePeople", []))
            if not changed_members and not changed_excluded:
                continue
            group_id = str(group.get("groupId", "") or "")
            member_pets = group.get("memberPets", [])
            if len(member_people) + len(member_pets) < 2:
                self.delete_photo_people_group(group_id, conn=conn)
                group_rows += 1
                continue
            old_default_name = default_group_name(group.get("memberPeople", []), member_pets)
            next_name = str(group.get("name", "") or "")
            if next_name.strip() == old_default_name:
                next_name = default_group_name(member_people, member_pets)
            self.upsert_photo_people_group(
                group_id=group_id,
                name=next_name,
                member_people=member_people,
                exclude_people=exclude_people,
                member_pets=member_pets,
                exclude_pets=group.get("excludePets", []),
                key_asset_id=str(group.get("keyAssetId", "") or ""),
                favorite=bool(group.get("favorite")),
                hidden=bool(group.get("hidden")),
                manual_order=group.get("manualOrder"),
                conn=conn,
            )
            group_rows += 1

        old_profile = self.photo_person_profile(old_person, conn)
        target_profile = self.photo_person_profile(new_person, conn)
        old_exists = bool(old_profile.get("createdAt") or old_profile.get("keyAssetId") or old_profile.get("favorite") or old_profile.get("hidden") or old_profile.get("manualOrder") is not None)
        target_exists = bool(target_profile.get("createdAt") or target_profile.get("keyAssetId") or target_profile.get("favorite") or target_profile.get("hidden") or target_profile.get("manualOrder") is not None)
        if not old_exists:
            if updated_people or group_rows:
                self._bump_photo_smart_album_materialization_revision(conn, reason="rename_photo_person_rows")
            return {
                "peopleRows": int(updated_people or 0),
                "groupRows": group_rows,
                "profileMoved": False,
                "profileMerged": False,
            }

        target_key_asset_id = str(target_profile.get("keyAssetId", "") or "")
        old_key_asset_id = str(old_profile.get("keyAssetId", "") or "")
        next_key_asset_id = str(target_key_asset_id or old_key_asset_id or "")
        next_key_asset_crop = self._photo_person_key_asset_crop(
            target_profile.get("keyAssetCrop", {}) if target_key_asset_id else old_profile.get("keyAssetCrop", {})
        )
        next_favorite = bool(target_profile.get("favorite", False) or old_profile.get("favorite", False))
        next_hidden = bool(target_profile.get("hidden", False) if target_exists else old_profile.get("hidden", False))
        next_order = target_profile.get("manualOrder") if target_profile.get("manualOrder") is not None else old_profile.get("manualOrder")
        created_at = str(target_profile.get("createdAt", "") or old_profile.get("createdAt", "") or now)
        conn.execute("DELETE FROM photo_people_profiles WHERE LOWER(person_name) = LOWER(?)", (old_person,))
        conn.execute(
            """
            INSERT INTO photo_people_profiles(
                person_name, key_asset_id, key_asset_crop_json, favorite, hidden, manual_order, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(person_name) DO UPDATE SET
                key_asset_id=excluded.key_asset_id,
                key_asset_crop_json=excluded.key_asset_crop_json,
                favorite=excluded.favorite,
                hidden=excluded.hidden,
                manual_order=excluded.manual_order,
                updated_at=excluded.updated_at
            """,
            (
                new_person,
                next_key_asset_id,
                json.dumps(next_key_asset_crop, sort_keys=True, separators=(",", ":")),
                int(next_favorite),
                int(next_hidden),
                next_order,
                created_at,
                now,
            ),
        )
        self._bump_photo_smart_album_materialization_revision(conn, reason="rename_photo_person_profile")
        return {
            "peopleRows": int(updated_people or 0),
            "groupRows": group_rows,
            "profileMoved": not target_exists,
            "profileMerged": target_exists,
        }

    def _photo_people_group_people(self, value: Any) -> list[str]:
        try:
            payload = json.loads(str(value or "[]"))
        except json.JSONDecodeError:
            payload = []
        if not isinstance(payload, list):
            return []
        people: list[str] = []
        seen: set[str] = set()
        for item in payload:
            person = str(item or "").strip()
            key = person.casefold()
            if person and key not in seen:
                seen.add(key)
                people.append(person)
        return people

    def _photo_people_group_row(self, row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
        return {
            "groupId": str(row["group_id"] or ""),
            "name": str(row["name"] or ""),
            "memberPeople": self._photo_people_group_people(row["member_people_json"]),
            "excludePeople": self._photo_people_group_people(row["excluded_people_json"]),
            "memberPets": self._photo_people_group_people(row["member_pets_json"]),
            "excludePets": self._photo_people_group_people(row["excluded_pets_json"]),
            "keyAssetId": str(row["key_asset_id"] or ""),
            "favorite": bool(row["favorite"]),
            "hidden": bool(row["hidden"]),
            "manualOrder": int(row["manual_order"]) if row["manual_order"] is not None else None,
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def list_photo_people_groups(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_people_groups(local_conn)
        rows = conn.execute(
            """
            SELECT group_id, name, member_people_json, excluded_people_json,
                member_pets_json, excluded_pets_json, key_asset_id,
                favorite, hidden, manual_order, created_at, updated_at
            FROM photo_people_groups
            ORDER BY favorite DESC, hidden ASC, COALESCE(manual_order, 2147483647) ASC, LOWER(name) ASC, group_id ASC
            """
        ).fetchall()
        return [self._photo_people_group_row(row) for row in rows]

    def photo_people_group_by_id(self, group_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_people_group_by_id(group_id, local_conn)
        row = conn.execute(
            """
            SELECT group_id, name, member_people_json, excluded_people_json,
                member_pets_json, excluded_pets_json, key_asset_id,
                favorite, hidden, manual_order, created_at, updated_at
            FROM photo_people_groups
            WHERE group_id = ?
            LIMIT 1
            """,
            (str(group_id or "").strip(),),
        ).fetchone()
        return self._photo_people_group_row(row) if row else None

    def upsert_photo_people_group(
        self,
        *,
        group_id: str,
        name: str,
        member_people: Iterable[str],
        exclude_people: Iterable[str] = (),
        member_pets: Iterable[str] = (),
        exclude_pets: Iterable[str] = (),
        key_asset_id: str | None = None,
        favorite: bool | None = None,
        hidden: bool | None = None,
        manual_order: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.upsert_photo_people_group(
                    group_id=group_id,
                    name=name,
                    member_people=member_people,
                    exclude_people=exclude_people,
                    member_pets=member_pets,
                    exclude_pets=exclude_pets,
                    key_asset_id=key_asset_id,
                    favorite=favorite,
                    hidden=hidden,
                    manual_order=manual_order,
                    conn=local_conn,
                )
        clean_group_id = str(group_id or "").strip()
        clean_name = str(name or "").strip()
        if not clean_group_id:
            raise ValueError("groupId is required.")
        if not clean_name:
            raise ValueError("Group name is required.")
        members = self._photo_people_group_people(json.dumps(list(member_people or [])))
        member_pets_clean = self._photo_people_group_people(json.dumps(list(member_pets or [])))
        if len(members) + len(member_pets_clean) < 2:
            raise ValueError("People and pets group requires at least two members.")
        member_keys = {person.casefold() for person in members}
        member_pet_keys = {pet.casefold() for pet in member_pets_clean}
        excluded = [person for person in self._photo_people_group_people(json.dumps(list(exclude_people or []))) if person.casefold() not in member_keys]
        excluded_pets = [pet for pet in self._photo_people_group_people(json.dumps(list(exclude_pets or []))) if pet.casefold() not in member_pet_keys]
        existing = self.photo_people_group_by_id(clean_group_id, conn)
        next_key_asset_id = str(key_asset_id if key_asset_id is not None else (existing or {}).get("keyAssetId", "") or "").strip()
        if next_key_asset_id:
            row = conn.execute("SELECT asset_id FROM photo_assets WHERE asset_id = ? LIMIT 1", (next_key_asset_id,)).fetchone()
            if row is None:
                raise ValueError("keyAssetId must identify a known photo asset.")
        next_favorite = bool(favorite if favorite is not None else (existing or {}).get("favorite", False))
        next_hidden = bool(hidden if hidden is not None else (existing or {}).get("hidden", False))
        next_order = manual_order if manual_order is not None else (existing or {}).get("manualOrder")
        if next_order is not None:
            next_order = max(0, min(2_147_483_647, int(next_order)))
        now = now_iso()
        created_at = str((existing or {}).get("createdAt", "") or now)
        conn.execute(
            """
            INSERT INTO photo_people_groups(
                group_id, name, member_people_json, excluded_people_json,
                member_pets_json, excluded_pets_json, key_asset_id,
                favorite, hidden, manual_order, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                name=excluded.name,
                member_people_json=excluded.member_people_json,
                excluded_people_json=excluded.excluded_people_json,
                member_pets_json=excluded.member_pets_json,
                excluded_pets_json=excluded.excluded_pets_json,
                key_asset_id=excluded.key_asset_id,
                favorite=excluded.favorite,
                hidden=excluded.hidden,
                manual_order=excluded.manual_order,
                updated_at=excluded.updated_at
            """,
            (
                clean_group_id,
                clean_name,
                json.dumps(members),
                json.dumps(excluded),
                json.dumps(member_pets_clean),
                json.dumps(excluded_pets),
                next_key_asset_id,
                int(next_favorite),
                int(next_hidden),
                next_order,
                created_at,
                now,
            ),
        )
        saved = self.photo_people_group_by_id(clean_group_id, conn)
        if saved is None:
            raise sqlite3.DatabaseError("photo people group was not saved")
        return saved

    def delete_photo_people_group(self, group_id: str, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_people_group(group_id, local_conn)
        cur = conn.execute("DELETE FROM photo_people_groups WHERE group_id = ?", (str(group_id or "").strip(),))
        return int(cur.rowcount or 0)

    def list_photo_keywords(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_keywords(local_conn)
        rows = conn.execute(
            """
            SELECT k.keyword_id, k.name, k.shortcut, k.created_at, k.updated_at,
                COUNT(ak.asset_id) AS asset_count
            FROM photo_keywords AS k
            LEFT JOIN photo_asset_keywords AS ak ON ak.keyword_id = k.keyword_id
            GROUP BY k.keyword_id, k.name, k.shortcut, k.created_at, k.updated_at
            ORDER BY LOWER(k.name) ASC, k.name ASC
            """
        ).fetchall()
        return [
            {
                "keywordId": str(row["keyword_id"] or ""),
                "name": str(row["name"] or ""),
                "shortcut": str(row["shortcut"] or ""),
                "count": int(row["asset_count"] or 0),
                "createdAt": str(row["created_at"] or ""),
                "updatedAt": str(row["updated_at"] or ""),
            }
            for row in rows
        ]

    def photo_keyword_by_id(self, keyword_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_keyword_by_id(keyword_id, local_conn)
        row = conn.execute(
            """
            SELECT k.keyword_id, k.name, k.shortcut, k.created_at, k.updated_at,
                COUNT(ak.asset_id) AS asset_count
            FROM photo_keywords AS k
            LEFT JOIN photo_asset_keywords AS ak ON ak.keyword_id = k.keyword_id
            WHERE k.keyword_id = ?
            GROUP BY k.keyword_id, k.name, k.shortcut, k.created_at, k.updated_at
            LIMIT 1
            """,
            (str(keyword_id or ""),),
        ).fetchone()
        if row is None:
            return None
        return {
            "keywordId": str(row["keyword_id"] or ""),
            "name": str(row["name"] or ""),
            "shortcut": str(row["shortcut"] or ""),
            "count": int(row["asset_count"] or 0),
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def save_photo_keyword(
        self,
        *,
        keyword_id: str = "",
        name: str = "",
        shortcut: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.save_photo_keyword(keyword_id=keyword_id, name=name, shortcut=shortcut, conn=local_conn)
        cleaned = self._clean_photo_keywords([name])
        if not cleaned:
            raise ValueError("Keyword name is required.")
        next_name = cleaned[0]
        next_shortcut = re.sub(r"\s+", " ", str(shortcut or "").strip())[:24]
        next_id = self._photo_keyword_id(next_name)
        old_id = str(keyword_id or "").strip()
        now = now_iso()
        affected_asset_ids: set[str] = set()
        if old_id:
            old_row = conn.execute(
                "SELECT keyword_id, name, shortcut, created_at FROM photo_keywords WHERE keyword_id = ? LIMIT 1",
                (old_id,),
            ).fetchone()
            if old_row is None:
                raise ValueError("Unknown photo keyword id.")
            old_name = self._clean_photo_keywords([str(old_row["name"] or "")])
            if old_id != next_id and old_name and old_name[0].casefold() == next_name.casefold():
                next_id = old_id
            affected_asset_ids.update(
                str(row["asset_id"] or "")
                for row in conn.execute("SELECT asset_id FROM photo_asset_keywords WHERE keyword_id = ?", (old_id,)).fetchall()
                if str(row["asset_id"] or "")
            )
            if old_id != next_id:
                existing_row = conn.execute(
                    "SELECT keyword_id FROM photo_keywords WHERE keyword_id = ? LIMIT 1",
                    (next_id,),
                ).fetchone()
                if existing_row is None:
                    conn.execute(
                        """
                        INSERT INTO photo_keywords(keyword_id, name, shortcut, created_at, updated_at)
                        VALUES(?, ?, ?, ?, ?)
                        """,
                        (next_id, next_name, next_shortcut, str(old_row["created_at"] or now), now),
                    )
                    conn.execute(
                        "UPDATE photo_asset_keywords SET keyword_id = ? WHERE keyword_id = ?",
                        (next_id, old_id),
                    )
                    conn.execute("DELETE FROM photo_keywords WHERE keyword_id = ?", (old_id,))
                else:
                    conn.execute(
                        """
                        UPDATE photo_keywords
                        SET name = ?, shortcut = ?, updated_at = ?
                        WHERE keyword_id = ?
                        """,
                        (next_name, next_shortcut, now, next_id),
                    )
                    for row in conn.execute("SELECT asset_id, assigned_at FROM photo_asset_keywords WHERE keyword_id = ?", (old_id,)).fetchall():
                        asset_key = str(row["asset_id"] or "")
                        if not asset_key:
                            continue
                        conn.execute(
                            """
                            INSERT OR IGNORE INTO photo_asset_keywords(asset_id, keyword_id, assigned_at)
                            VALUES(?, ?, ?)
                            """,
                            (asset_key, next_id, str(row["assigned_at"] or now)),
                        )
                    conn.execute("DELETE FROM photo_asset_keywords WHERE keyword_id = ?", (old_id,))
                    conn.execute("DELETE FROM photo_keywords WHERE keyword_id = ?", (old_id,))
            else:
                conn.execute(
                    """
                    UPDATE photo_keywords
                    SET name = ?, shortcut = ?, updated_at = ?
                    WHERE keyword_id = ?
                    """,
                    (next_name, next_shortcut, now, next_id),
                )
        else:
            conn.execute(
                """
                INSERT INTO photo_keywords(keyword_id, name, shortcut, created_at, updated_at)
                VALUES(?, ?, ?, ?, ?)
                ON CONFLICT(keyword_id) DO UPDATE SET
                    name=excluded.name,
                    shortcut=excluded.shortcut,
                    updated_at=excluded.updated_at
                """,
                (next_id, next_name, next_shortcut, now, now),
            )
        for asset_key in affected_asset_ids:
            self._index_photo_asset(asset_key, conn)
        row = self.photo_keyword_by_id(next_id, conn)
        if row is None:
            raise ValueError("Keyword could not be saved.")
        return row

    def delete_photo_keyword(self, keyword_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_keyword(keyword_id, local_conn)
        key = str(keyword_id or "").strip()
        if not key:
            raise ValueError("keywordId is required.")
        keyword = self.photo_keyword_by_id(key, conn)
        if keyword is None:
            raise ValueError("Unknown photo keyword id.")
        affected_asset_ids = [
            str(row["asset_id"] or "")
            for row in conn.execute("SELECT asset_id FROM photo_asset_keywords WHERE keyword_id = ?", (key,)).fetchall()
            if str(row["asset_id"] or "")
        ]
        conn.execute("DELETE FROM photo_asset_keywords WHERE keyword_id = ?", (key,))
        conn.execute("DELETE FROM photo_keywords WHERE keyword_id = ?", (key,))
        for asset_key in affected_asset_ids:
            self._index_photo_asset(asset_key, conn)
        return {
            "keywordId": key,
            "name": str(keyword.get("name", "")),
            "removedAssignments": len(affected_asset_ids),
            "deleted": True,
        }

    def list_photo_asset_keywords(self, asset_id: str, conn: sqlite3.Connection | None = None) -> list[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_asset_keywords(asset_id, local_conn)
        rows = conn.execute(
            """
            SELECT k.name
            FROM photo_asset_keywords AS ak
            JOIN photo_keywords AS k ON k.keyword_id = ak.keyword_id
            WHERE ak.asset_id = ?
            ORDER BY LOWER(k.name) ASC, k.name ASC
            """,
            (str(asset_id or ""),),
        ).fetchall()
        return [str(row["name"] or "") for row in rows if str(row["name"] or "")]

    def set_photo_asset_keywords(
        self,
        asset_id: str,
        keywords: Any,
        conn: sqlite3.Connection | None = None,
        *,
        refresh_index: bool = True,
    ) -> list[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.set_photo_asset_keywords(asset_id, keywords, local_conn, refresh_index=refresh_index)
        asset_key = str(asset_id or "").strip()
        if not asset_key:
            return []
        row = conn.execute("SELECT asset_id FROM photo_assets WHERE asset_id = ? LIMIT 1", (asset_key,)).fetchone()
        if row is None:
            raise ValueError("Unknown photo asset id.")
        cleaned = self._clean_photo_keywords(keywords)
        now = now_iso()
        conn.execute("DELETE FROM photo_asset_keywords WHERE asset_id = ?", (asset_key,))
        for name in cleaned:
            keyword_id = self._photo_keyword_id(name)
            conn.execute(
                """
                INSERT INTO photo_keywords(keyword_id, name, shortcut, created_at, updated_at)
                VALUES(?, ?, '', ?, ?)
                ON CONFLICT(keyword_id) DO UPDATE SET
                    name=excluded.name,
                    updated_at=excluded.updated_at
                """,
                (keyword_id, name, now, now),
            )
            conn.execute(
                """
                INSERT OR REPLACE INTO photo_asset_keywords(asset_id, keyword_id, assigned_at)
                VALUES(?, ?, ?)
                """,
                (asset_key, keyword_id, now),
            )
        if refresh_index:
            self._index_photo_asset(asset_key, conn)
        return cleaned

    def update_photo_asset_metadata(
        self,
        *,
        source_path: str = "",
        asset_id: str = "",
        title: str | None = None,
        caption: str | None = None,
        favorite: bool | None = None,
        rating: int | None = None,
        rating_explicit: bool | None = None,
        color_label: str | None = None,
        pick_status: str | None = None,
        hidden: bool | None = None,
        deleted_at: str | None = None,
        clear_deleted: bool = False,
        date_override: str | None = None,
        capture_date: str | None = None,
        location_override: dict[str, Any] | None = None,
        location_hidden: bool | None = None,
        edited: bool | None = None,
        keywords: Any = None,
        conn: sqlite3.Connection | None = None,
        refresh_index: bool = True,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.update_photo_asset_metadata(
                    source_path=source_path,
                    asset_id=asset_id,
                    title=title,
                    caption=caption,
                    favorite=favorite,
                    rating=rating,
                    rating_explicit=rating_explicit,
                    color_label=color_label,
                    pick_status=pick_status,
                    hidden=hidden,
                    deleted_at=deleted_at,
                    clear_deleted=clear_deleted,
                    date_override=date_override,
                    capture_date=capture_date,
                    location_override=location_override,
                    location_hidden=location_hidden,
                    edited=edited,
                    keywords=keywords,
                    conn=local_conn,
                    refresh_index=refresh_index,
                )
        asset_key = str(asset_id or "").strip()
        asset: dict[str, Any] | None = None
        if asset_key:
            row = conn.execute("SELECT * FROM photo_assets WHERE asset_id = ? LIMIT 1", (asset_key,)).fetchone()
            asset = self._photo_asset_row(row, conn, {}) if row else None
        if asset is None and source_path:
            asset = self.photo_asset_by_path(source_path, conn)
        if asset is None:
            asset_key = self._upsert_photo_asset(conn, source_path=str(source_path or ""), metadata={"source": "metadata_update"})
            asset = self.photo_asset_by_path(source_path, conn)
        if not asset:
            raise ValueError("A sourcePath or assetId is required.")
        asset_key = str(asset["assetId"])
        current = self.photo_asset_metadata_by_id(asset_key, conn)
        now = now_iso()
        next_title = str(title if title is not None else current.get("title", ""))[:300]
        next_caption = str(caption if caption is not None else current.get("caption", ""))[:4000]
        raw_next_rating = rating if rating is not None else current.get("rating", 0)
        if isinstance(raw_next_rating, bool):
            raise ValueError("rating must be an integer from 0 to 5.")
        if isinstance(raw_next_rating, int):
            next_rating = raw_next_rating
        elif isinstance(raw_next_rating, str) and re.fullmatch(r"[0-5]", raw_next_rating.strip()):
            next_rating = int(raw_next_rating.strip())
        else:
            raise ValueError("rating must be an integer from 0 to 5.")
        if next_rating < 0 or next_rating > 5:
            raise ValueError("rating must be an integer from 0 to 5.")
        next_rating_explicit = (
            bool(rating_explicit)
            if rating_explicit is not None
            else (True if rating is not None else bool(current.get("ratingExplicit")))
        )
        next_color_label = self._normalize_photo_color_label(
            color_label if color_label is not None else current.get("colorLabel", "")
        )
        next_pick_status = self._normalize_photo_pick_status(
            pick_status if pick_status is not None else current.get("pickStatus", "")
        )
        next_location = location_override if isinstance(location_override, dict) else current.get("locationOverride", {})
        if not isinstance(next_location, dict):
            next_location = {}
        next_date_override = str(date_override if date_override is not None else current.get("dateOverride", "") or "")
        if next_date_override and not re.match(r"^\d{4}-\d{2}-\d{2}([T ].*)?$", next_date_override):
            raise ValueError("dateOverride must be empty or an ISO-like date.")
        next_capture_date = str(capture_date if capture_date is not None else asset.get("captureDate", "") or "")
        if next_capture_date and not re.match(r"^\d{4}-\d{2}-\d{2}([T ].*)?$", next_capture_date):
            raise ValueError("captureDate must be empty or an ISO-like date.")
        if capture_date is not None:
            previous_capture_date = str(asset.get("captureDate", "") or "")
            asset_metadata = asset.get("metadata", {}) if isinstance(asset.get("metadata"), dict) else {}
            next_asset_metadata = dict(asset_metadata)
            original_capture_date = str(next_asset_metadata.get("catalogCaptureDateOriginal", previous_capture_date) or "")
            next_asset_metadata["catalogCaptureDateOriginal"] = original_capture_date
            if next_capture_date != original_capture_date:
                next_asset_metadata["catalogCaptureDateEdited"] = True
                next_asset_metadata["catalogCaptureDateEditedAt"] = now
            else:
                next_asset_metadata.pop("catalogCaptureDateEdited", None)
                next_asset_metadata.pop("catalogCaptureDateEditedAt", None)
            conn.execute(
                """
                UPDATE photo_assets
                SET capture_date = ?,
                    metadata_json = ?,
                    updated_at = ?
                WHERE asset_id = ?
                """,
                (
                    next_capture_date,
                    self._clean_json_dict(next_asset_metadata),
                    now,
                    asset_key,
                ),
            )
            asset = self.photo_asset_by_id(asset_key, conn) or asset
            self.replace_photo_object_tags_from_metadata(asset_key, next_asset_metadata, conn, refresh_index=False)
        next_deleted_at = None if clear_deleted else (deleted_at if deleted_at is not None else (current.get("deletedAt", "") or None))
        conn.execute(
            """
            INSERT INTO photo_asset_metadata(
                asset_id, title, caption, favorite, rating, rating_explicit, color_label, pick_status, hidden, deleted_at, date_override,
                location_override_json, location_hidden, edited, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(asset_id) DO UPDATE SET
                title=excluded.title,
                caption=excluded.caption,
                favorite=excluded.favorite,
                rating=excluded.rating,
                rating_explicit=excluded.rating_explicit,
                color_label=excluded.color_label,
                pick_status=excluded.pick_status,
                hidden=excluded.hidden,
                deleted_at=excluded.deleted_at,
                date_override=excluded.date_override,
                location_override_json=excluded.location_override_json,
                location_hidden=excluded.location_hidden,
                edited=excluded.edited,
                updated_at=excluded.updated_at
            """,
            (
                asset_key,
                next_title,
                next_caption,
                int(bool(favorite if favorite is not None else current.get("favorite", False))),
                next_rating,
                int(next_rating_explicit),
                next_color_label,
                next_pick_status,
                int(bool(hidden if hidden is not None else current.get("hidden", False))),
                next_deleted_at,
                next_date_override or None,
                self._clean_json_dict(next_location),
                int(bool(location_hidden if location_hidden is not None else current.get("locationHidden", False))),
                int(bool(edited if edited is not None else current.get("edited", False))),
                now,
            ),
        )
        if keywords is not None:
            next_keywords = self.set_photo_asset_keywords(asset_key, keywords, conn, refresh_index=False)
        else:
            next_keywords = self.list_photo_asset_keywords(asset_key, conn)
        updated_metadata = self.photo_asset_metadata_by_id(asset_key, conn)
        updated_asset = self.photo_asset_by_id(asset_key, conn)
        updated_asset_metadata = updated_asset.get("metadata", {}) if updated_asset and isinstance(updated_asset.get("metadata"), dict) else {}
        xmp_metadata = updated_asset_metadata.get("xmp") if isinstance(updated_asset_metadata.get("xmp"), dict) else {}
        if xmp_metadata:
            self._refresh_photo_xmp_conflicts(asset_key, xmp_metadata, {**updated_metadata, "keywords": next_keywords}, conn)
        if refresh_index:
            self._index_photo_asset(asset_key, conn)
        self._bump_photo_smart_album_materialization_revision(conn, reason="photo_asset_metadata")
        return {
            **updated_metadata,
            "keywords": next_keywords,
            "assetId": asset_key,
            "sourcePath": str(asset["sourcePath"]),
            "captureDate": str(updated_asset.get("captureDate", "") or "") if updated_asset else next_capture_date,
        }

    def permanently_delete_photo_assets(
        self,
        *,
        source_paths: Iterable[str] | None = None,
        asset_ids: Iterable[str] | None = None,
        deleted_before: str = "",
        require_deleted: bool = True,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.permanently_delete_photo_assets(
                    source_paths=source_paths,
                    asset_ids=asset_ids,
                    deleted_before=deleted_before,
                    require_deleted=require_deleted,
                    conn=local_conn,
                )
        source_values = [str(value or "").strip() for value in (source_paths or []) if str(value or "").strip()]
        asset_values = [str(value or "").strip() for value in (asset_ids or []) if str(value or "").strip()]
        cutoff = str(deleted_before or "").strip()
        if not source_values and not asset_values and not cutoff:
            raise ValueError("Permanent delete requires sourcePaths, assetIds, or deletedBefore.")

        scope_clauses: list[str] = []
        guard_clauses: list[str] = []
        args: list[Any] = []
        if source_values:
            scope_clauses.append(f"a.source_path IN ({','.join('?' for _ in source_values)})")
            args.extend(source_values)
        if asset_values:
            scope_clauses.append(f"a.asset_id IN ({','.join('?' for _ in asset_values)})")
            args.extend(asset_values)
        if cutoff:
            guard_clauses.append("m.deleted_at IS NOT NULL AND m.deleted_at != '' AND m.deleted_at <= ?")
            args.append(cutoff)
        if require_deleted:
            guard_clauses.append("m.deleted_at IS NOT NULL AND m.deleted_at != ''")
        where_parts: list[str] = []
        if scope_clauses:
            where_parts.append("(" + " OR ".join(f"({clause})" for clause in scope_clauses) + ")")
        where_parts.extend(f"({clause})" for clause in guard_clauses)
        where = " AND ".join(where_parts) if where_parts else "0"
        rows = conn.execute(
            f"""
            SELECT a.asset_id, a.source_path, a.source_kind, m.deleted_at
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE {where}
            ORDER BY a.source_path ASC
            """,
            args,
        ).fetchall()

        seen_assets: set[str] = set()
        targets: list[dict[str, str]] = []
        for row in rows:
            asset_key = str(row["asset_id"] or "")
            source = str(row["source_path"] or "")
            deleted_at = str(row["deleted_at"] or "")
            if not asset_key or asset_key in seen_assets:
                continue
            if require_deleted and not deleted_at:
                continue
            seen_assets.add(asset_key)
            targets.append(
                {
                    "assetId": asset_key,
                    "sourcePath": source,
                    "sourceKind": str(row["source_kind"] or ""),
                    "deletedAt": deleted_at,
                }
            )

        snapshots = [
            snapshot for target in targets
            for snapshot in [self._photo_asset_catalog_snapshot(target["assetId"], conn)]
            if snapshot is not None
        ]
        managed_originals_trashed: list[dict[str, Any]] = []
        managed_original_trash_failures: list[dict[str, str]] = []
        candidate_ids: set[str] = set()
        scan_file_rows = 0
        candidate_rows = 0
        operation: dict[str, Any] | None = None
        trash_run_root = self._photo_managed_original_trash_root() / f"catalog-delete-{uuid.uuid4().hex}"
        savepoint = f"photo_permanent_delete_{uuid.uuid4().hex}"
        conn.execute(f"SAVEPOINT {savepoint}")
        try:
            for snapshot in snapshots:
                plan = self._photo_catalog_managed_trash_plan(snapshot, trash_run_root, conn)
                if plan is None:
                    continue
                try:
                    shutil.move(str(plan["sourcePath"]), str(plan["trashPath"]))
                except OSError as exc:
                    managed_original_trash_failures.append(
                        {
                            "assetId": str(plan.get("assetId", "") or ""),
                            "sourcePath": str(plan.get("sourcePath", "") or ""),
                            "reason": str(exc),
                        }
                    )
                    continue
                snapshot["managedOriginalTrash"] = plan
                managed_originals_trashed.append(plan)

            candidate_cleanup = self.delete_review_candidates_for_source_paths(
                (target["sourcePath"] for target in targets),
                conn,
            )
            candidate_rows += int(candidate_cleanup.get("deleted", 0) or 0)
            candidate_ids.update(str(candidate_id) for candidate_id in candidate_cleanup.get("candidateIds", []) if str(candidate_id))

            for target in targets:
                source = target["sourcePath"]
                asset_key = target["assetId"]
                scan_file_rows += int(conn.execute("DELETE FROM scan_files WHERE path = ?", (source,)).rowcount or 0)
                conn.execute("DELETE FROM photo_search_fts WHERE asset_id = ?", (asset_key,))
                conn.execute("DELETE FROM photo_ocr_blocks WHERE asset_id = ?", (asset_key,))
                conn.execute("DELETE FROM photo_object_tags WHERE asset_id = ?", (asset_key,))
                conn.execute("DELETE FROM photo_assets WHERE asset_id = ?", (asset_key,))

            operation = self.record_photo_catalog_delete_operation(
                operation_type="catalog_permanent_delete",
                label=f"Permanently deleted {len(snapshots)} photo{'s' if len(snapshots) != 1 else ''} from catalog",
                snapshots=snapshots,
                conn=conn,
            ) if snapshots else None
            conn.execute(f"RELEASE {savepoint}")
        except Exception:
            try:
                conn.execute(f"ROLLBACK TO {savepoint}")
            except sqlite3.DatabaseError:
                pass
            try:
                conn.execute(f"RELEASE {savepoint}")
            except sqlite3.DatabaseError:
                pass
            for snapshot in reversed(snapshots):
                self._restore_photo_managed_original_from_trash(snapshot)
            try:
                if trash_run_root.exists():
                    shutil.rmtree(trash_run_root)
            except OSError:
                pass
            raise
        return {
            "selected": len(targets),
            "deletedAssets": len(targets),
            "deletedScanFiles": scan_file_rows,
            "deletedCandidates": candidate_rows,
            "deletedFiles": len(managed_originals_trashed),
            "managedOriginalsTrashed": len(managed_originals_trashed),
            "managedOriginalTrashFailures": managed_original_trash_failures,
            "managedOriginalTrashPaths": [str(item.get("trashPath", "") or "") for item in managed_originals_trashed],
            "sourcePaths": [target["sourcePath"] for target in targets],
            "assetIds": [target["assetId"] for target in targets],
            "candidateIds": sorted(candidate_ids),
            "deletedBefore": cutoff,
            "originalMediaDeleted": bool(managed_originals_trashed),
            "operation": operation or {},
        }

    def _photo_search_match_query(self, query: str) -> str:
        terms = re.findall(r"[A-Za-z0-9_]+", str(query or "").casefold())
        return " ".join(f"{term}*" for term in terms[:12])

    def search_photo_asset_ids(
        self,
        query: str,
        *,
        offset: int = 0,
        limit: int = 100,
        media_kind: str = "",
        source_text_filters: Iterable[tuple[str, str]] = (),
        conn: sqlite3.Connection | None = None,
    ) -> list[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.search_photo_asset_ids(
                    query,
                    offset=offset,
                    limit=limit,
                    media_kind=media_kind,
                    source_text_filters=source_text_filters,
                    conn=local_conn,
                )
        match_query = self._photo_search_match_query(query)
        if not match_query:
            page = self.list_photo_asset_page(
                offset=offset,
                limit=limit,
                media_kind=media_kind,
                source_text_filters=source_text_filters,
                conn=conn,
            )
            return [str(row.get("assetId", "") or "") for row in page.get("assets", [])]
        kind = str(media_kind or "").strip().lower()
        where_kind = "AND a.media_kind = ?" if kind else ""
        args: list[Any] = [match_query]
        if kind:
            args.append(kind)
        source_filter_where, source_filter_args = self._photo_source_text_filter_sql_parts(source_text_filters)
        source_where_sql = " AND " + " AND ".join(source_filter_where) if source_filter_where else ""
        args.extend(source_filter_args)
        rows = conn.execute(
            f"""
            SELECT f.asset_id
            FROM photo_search_fts AS f
            JOIN photo_assets AS a ON a.asset_id = f.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE photo_search_fts MATCH ?
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
                {where_kind}
                {source_where_sql}
            ORDER BY rank
            LIMIT ? OFFSET ?
            """,
            [*args, max(1, int(limit)), max(0, int(offset))],
        ).fetchall()
        return [str(row["asset_id"] or "") for row in rows if str(row["asset_id"] or "")]

    def search_photo_assets(
        self,
        query: str,
        *,
        offset: int = 0,
        limit: int = 100,
        media_kind: str = "",
        source_text_filters: Iterable[tuple[str, str]] = (),
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.search_photo_assets(
                    query,
                    offset=offset,
                    limit=limit,
                    media_kind=media_kind,
                    source_text_filters=source_text_filters,
                    conn=local_conn,
                )
        match_query = self._photo_search_match_query(query)
        if not match_query:
            page = self.list_photo_asset_page(
                offset=offset,
                limit=limit,
                media_kind=media_kind,
                source_text_filters=source_text_filters,
                conn=conn,
            )
            return {
                "total": int(page.get("total", 0) or 0),
                "assetIds": [str(row.get("assetId", "") or "") for row in page.get("assets", [])],
            }
        kind = str(media_kind or "").strip().lower()
        where_kind = "AND a.media_kind = ?" if kind else ""
        args: list[Any] = [match_query]
        if kind:
            args.append(kind)
        source_filter_where, source_filter_args = self._photo_source_text_filter_sql_parts(source_text_filters)
        source_where_sql = " AND " + " AND ".join(source_filter_where) if source_filter_where else ""
        args.extend(source_filter_args)
        total_row = conn.execute(
            f"""
            SELECT COUNT(*) AS n
            FROM photo_search_fts AS f
            JOIN photo_assets AS a ON a.asset_id = f.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE photo_search_fts MATCH ?
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
                {where_kind}
                {source_where_sql}
            """,
            args,
        ).fetchone()
        asset_ids = self.search_photo_asset_ids(
            query,
            offset=offset,
            limit=limit,
            media_kind=media_kind,
            source_text_filters=source_text_filters,
            conn=conn,
        )
        return {"total": int(total_row["n"] if total_row else 0), "assetIds": asset_ids}

    def search_photo_asset_facets(
        self,
        query: str,
        *,
        exclude_asset_ids: Iterable[str] = (),
        offset: int = 0,
        limit: int = 100,
        source_text_filters: Iterable[tuple[str, str]] = (),
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.search_photo_asset_facets(
                    query,
                    exclude_asset_ids=exclude_asset_ids,
                    offset=offset,
                    limit=limit,
                    source_text_filters=source_text_filters,
                    conn=local_conn,
                )
        needle = str(query or "").strip().casefold()
        if not needle:
            return {"total": 0, "assetIds": []}
        like = f"%{needle}%"
        excludes = [str(asset_id or "").strip() for asset_id in exclude_asset_ids if str(asset_id or "").strip()]
        exclude_sql = f"AND a.asset_id NOT IN ({','.join('?' for _ in excludes)})" if excludes else ""
        source_filter_where, source_filter_args = self._photo_source_text_filter_sql_parts(source_text_filters)
        source_where_sql = " AND " + " AND ".join(source_filter_where) if source_filter_where else ""
        where = f"""
            COALESCE(m.hidden, 0) = 0
            AND m.deleted_at IS NULL
            AND (
                LOWER(COALESCE(a.capture_date, '')) LIKE ?
                OR LOWER(COALESCE(a.added_at, '')) LIKE ?
                OR LOWER(COALESCE(a.media_kind, '')) LIKE ?
                OR LOWER(REPLACE(COALESCE(a.media_kind, ''), '_', ' ')) LIKE ?
                OR LOWER(COALESCE(a.mime_type, '')) LIKE ?
                OR LOWER(COALESCE(m.date_override, '')) LIKE ?
                OR LOWER(COALESCE(m.location_override_json, '')) LIKE ?
            )
            {exclude_sql}
            {source_where_sql}
        """
        args: list[Any] = [like, like, like, like, like, like, like, *excludes, *source_filter_args]
        total_row = conn.execute(
            f"""
            SELECT COUNT(*) AS n
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE {where}
            """,
            args,
        ).fetchone()
        rows = conn.execute(
            f"""
            SELECT a.asset_id
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE {where}
            ORDER BY COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), NULLIF(a.added_at, '')) DESC,
                a.source_path ASC
            LIMIT ? OFFSET ?
            """,
            [*args, max(1, int(limit)), max(0, int(offset))],
        ).fetchall()
        return {
            "total": int(total_row["n"] if total_row else 0),
            "assetIds": [str(row["asset_id"] or "") for row in rows if str(row["asset_id"] or "")],
        }

    def search_photo_source_folders(
        self,
        query: str,
        *,
        limit: int = 24,
        source_text_filters: Iterable[tuple[str, str]] = (),
        conn: sqlite3.Connection | None = None,
    ) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.search_photo_source_folders(
                    query,
                    limit=limit,
                    source_text_filters=source_text_filters,
                    conn=local_conn,
                )
        needle = str(query or "").strip().casefold()
        if len(needle) < 2:
            return []
        normalized_needle = needle.replace("\\", "/")
        like = f"%{needle}%"
        normalized_like = f"%{normalized_needle}%"
        source_filter_where, source_filter_args = self._photo_source_text_filter_sql_parts(source_text_filters)
        source_where_sql = " AND " + " AND ".join(source_filter_where) if source_filter_where else ""
        rows = conn.execute(
            f"""
            SELECT a.asset_id, a.source_path
            FROM photo_assets AS a
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
                AND (
                    LOWER(a.source_path) LIKE ?
                    OR REPLACE(LOWER(a.source_path), '\\', '/') LIKE ?
                )
                {source_where_sql}
            ORDER BY COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), NULLIF(a.added_at, '')) DESC,
                a.source_path ASC
            LIMIT ?
            """,
            [like, normalized_like, *source_filter_args, max(1000, max(1, int(limit)) * 200)],
        ).fetchall()
        grouped: dict[str, dict[str, Any]] = {}
        for row in rows:
            source_path = str(row["source_path"] or "").rstrip("/\\")
            separator_index = max(source_path.rfind("/"), source_path.rfind("\\"))
            if separator_index <= 0:
                continue
            folder_path = source_path[:separator_index].rstrip("/\\")
            if not folder_path:
                continue
            folder_key = folder_path.replace("\\", "/").rstrip("/").casefold()
            if needle not in folder_path.casefold() and normalized_needle not in folder_key:
                continue
            folder_name = folder_path[max(folder_path.rfind("/"), folder_path.rfind("\\")) + 1:] or folder_path
            group = grouped.get(folder_key)
            if group is None:
                group = {
                    "folderPath": folder_path,
                    "name": folder_name,
                    "count": 0,
                    "coverSourcePath": source_path,
                    "_assetIds": set(),
                }
                grouped[folder_key] = group
            asset_id = str(row["asset_id"] or "")
            if asset_id and asset_id not in group["_assetIds"]:
                group["_assetIds"].add(asset_id)
                group["count"] = int(group.get("count", 0) or 0) + 1
        results = sorted(
            grouped.values(),
            key=lambda item: (-int(item.get("count", 0) or 0), str(item.get("name", "") or "").casefold(), str(item.get("folderPath", "") or "").casefold()),
        )
        cleaned: list[dict[str, Any]] = []
        for item in results[:max(1, int(limit))]:
            cleaned.append({
                "folderPath": str(item.get("folderPath", "") or ""),
                "name": str(item.get("name", "") or ""),
                "count": int(item.get("count", 0) or 0),
                "coverSourcePath": str(item.get("coverSourcePath", "") or ""),
            })
        return cleaned

    def search_photo_date_buckets(
        self,
        query: str,
        *,
        limit: int = 100,
        conn: sqlite3.Connection | None = None,
    ) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.search_photo_date_buckets(query, limit=limit, conn=local_conn)
        needle = str(query or "").strip().casefold()
        if not needle:
            return []
        rows = conn.execute(
            """
            WITH visible_dates AS (
                SELECT
                    a.asset_id AS asset_id,
                    a.source_path AS source_path,
                    SUBSTR(COALESCE(NULLIF(m.date_override, ''), NULLIF(a.capture_date, ''), NULLIF(a.added_at, '')), 1, 10) AS date_text
                FROM photo_assets AS a
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE COALESCE(m.hidden, 0) = 0
                    AND m.deleted_at IS NULL
            )
            SELECT date_text, COUNT(*) AS n, MIN(source_path) AS cover_source_path
            FROM visible_dates
            WHERE date_text GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
            GROUP BY date_text
            ORDER BY date_text DESC
            """,
        ).fetchall()
        buckets: dict[tuple[str, str], dict[str, Any]] = {}
        mode_order = {"years": 0, "months": 1, "days": 2}
        for row in rows:
            date_text = str(row["date_text"] or "")
            count = int(row["n"] or 0)
            cover_source = str(row["cover_source_path"] or "")
            for mode, key in (("years", date_text[:4]), ("months", date_text[:7]), ("days", date_text)):
                label = ""
                if mode == "years":
                    label = key
                elif mode == "months":
                    try:
                        label = datetime.strptime(key, "%Y-%m").strftime("%B %Y")
                    except ValueError:
                        label = key
                else:
                    try:
                        parsed_date = datetime.strptime(key, "%Y-%m-%d")
                        label = f"{parsed_date.strftime('%B')} {parsed_date.day}, {parsed_date.year}"
                    except ValueError:
                        label = key
                if needle not in key.casefold() and needle not in label.casefold():
                    continue
                bucket_key = (mode, key)
                bucket = buckets.setdefault(
                    bucket_key,
                    {
                        "id": f"date:{mode}:{key}",
                        "kind": "date",
                        "title": label,
                        "subtitle": "",
                        "dateBucketMode": mode,
                        "dateBucketKey": key,
                        "count": 0,
                        "coverSourcePath": cover_source,
                    },
                )
                bucket["count"] += count
                if not bucket.get("coverSourcePath"):
                    bucket["coverSourcePath"] = cover_source
        output = sorted(
            buckets.values(),
            key=lambda item: (mode_order.get(str(item.get("dateBucketMode", "") or ""), 9), str(item.get("dateBucketKey", "") or "")),
            reverse=True,
        )
        return output[:max(1, int(limit))]

    def backfill_photo_assets_from_scan_media(
        self,
        conn: sqlite3.Connection | None = None,
        *,
        missing_only: bool = False,
    ) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.backfill_photo_assets_from_scan_media(local_conn, missing_only=missing_only)
        missing_join = "LEFT JOIN photo_assets AS pa ON pa.source_path = latest.path" if missing_only else ""
        missing_where = "WHERE pa.asset_id IS NULL" if missing_only else ""
        rows = conn.execute(
            f"""
            WITH latest AS (
                SELECT path, MAX(processed_at) AS processed_at, status, phase, candidate_id,
                    size, mtime_ns, content_hash, run_id, path_key
                FROM scan_files
                WHERE {self._SCAN_MEDIA_WHERE}
                GROUP BY path
            )
            SELECT latest.path, latest.processed_at, latest.status, latest.phase, latest.candidate_id,
                latest.size, latest.mtime_ns, latest.content_hash, latest.run_id, latest.path_key
            FROM latest
            {missing_join}
            {missing_where}
            ORDER BY latest.processed_at DESC, latest.path ASC
            """
        )
        count = 0
        for row in rows:
            source_path = str(row["path"] or "")
            if not source_path:
                continue
            self._upsert_photo_asset(
                conn,
                source_path=source_path,
                file_signature={
                    "path": source_path,
                    "pathKey": str(row["path_key"] or ""),
                    "size": int(row["size"] or 0),
                    "mtimeNs": int(row["mtime_ns"] or 0),
                },
                content_hash=str(row["content_hash"] or ""),
                media_kind=self._photo_asset_media_kind(source_path),
                added_at=str(row["processed_at"] or ""),
                source_scan_run=str(row["run_id"] or ""),
                metadata={
                    "source": "scan_files",
                    "scanStatus": str(row["status"] or ""),
                    "scanPhase": str(row["phase"] or ""),
                    "candidateId": str(row["candidate_id"] or ""),
                },
            )
            count += 1
        return count

    def backfill_photo_assets_from_review_candidates(
        self,
        conn: sqlite3.Connection | None = None,
        *,
        missing_only: bool = False,
    ) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.backfill_photo_assets_from_review_candidates(local_conn, missing_only=missing_only)
        where_clause = """
            WHERE NOT EXISTS (
                SELECT 1
                FROM photo_asset_people
                WHERE photo_asset_people.candidate_id = review_candidates.candidate_id
                LIMIT 1
            )
            AND payload_json NOT LIKE '%"photoAssetBackfillDisabled":true%'
        """ if missing_only else ""
        rows = conn.execute(
            f"""
            SELECT candidate_id, source_path, person_name, best_ref_id, best_ref_path,
                score, band, quality, model_name, status, note, risk_flags,
                close_runner_up, single_reference_match, media_kind, media_source_path,
                media_path, folder_path, video_timestamp_ms, video_frame_index,
                video_duration_ms, source_hash, created_at, payload_json
            FROM review_candidates
            {where_clause}
            ORDER BY created_at ASC, candidate_id ASC
            """
        )
        params: list[tuple[Any, ...]] = []
        count = 0
        for row in rows:
            params.append(
                (
                    row["candidate_id"],
                    row["source_path"],
                    row["person_name"],
                    str(row["person_name"] or "").casefold(),
                    row["best_ref_id"],
                    row["best_ref_path"],
                    row["score"],
                    row["band"],
                    row["quality"],
                    row["model_name"],
                    row["status"],
                    row["note"],
                    row["risk_flags"],
                    row["close_runner_up"],
                    row["single_reference_match"],
                    row["media_kind"],
                    row["media_source_path"],
                    row["media_path"],
                    row["folder_path"],
                    row["video_timestamp_ms"],
                    row["video_frame_index"],
                    row["video_duration_ms"],
                    row["source_hash"],
                    row["created_at"],
                    row["payload_json"],
                )
            )
            if len(params) >= 1000:
                count += self._upsert_photo_assets_from_candidate_params(params, conn)
                params.clear()
        if params:
            count += self._upsert_photo_assets_from_candidate_params(params, conn)
        return count

    def _album_folder_row(self, row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
        keys = set(row.keys())
        return {
            "folderId": str(row["folder_id"] or ""),
            "name": str(row["name"] or ""),
            "parentFolderId": str(row["parent_folder_id"] or ""),
            "position": int(row["position"] or 0),
            "albumCount": int(row["album_count"] or 0) if "album_count" in keys else 0,
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def list_photo_album_folders(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_album_folders(local_conn)
        rows = conn.execute(
            """
            SELECT f.folder_id, f.name, f.parent_folder_id, f.position, f.created_at, f.updated_at,
                COUNT(a.album_id) AS album_count
            FROM photo_album_folders AS f
            LEFT JOIN photo_albums AS a ON a.folder_id = f.folder_id
            GROUP BY f.folder_id
            ORDER BY f.parent_folder_id IS NOT NULL, f.parent_folder_id ASC,
                f.position ASC, f.name ASC, f.folder_id ASC
            """
        ).fetchall()
        return [self._album_folder_row(row) for row in rows]

    def photo_album_folder_by_id(self, folder_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_album_folder_by_id(folder_id, local_conn)
        row = conn.execute(
            """
            SELECT f.folder_id, f.name, f.parent_folder_id, f.position, f.created_at, f.updated_at,
                COUNT(a.album_id) AS album_count
            FROM photo_album_folders AS f
            LEFT JOIN photo_albums AS a ON a.folder_id = f.folder_id
            WHERE f.folder_id = ?
            GROUP BY f.folder_id
            LIMIT 1
            """,
            (str(folder_id or ""),),
        ).fetchone()
        return self._album_folder_row(row) if row else None

    def _next_photo_album_container_position(self, parent_folder_id: str, conn: sqlite3.Connection) -> int:
        folder_row = conn.execute(
            """
            SELECT COALESCE(MAX(position), -1) AS max_position
            FROM photo_album_folders
            WHERE COALESCE(parent_folder_id, '') = ?
            """,
            (str(parent_folder_id or ""),),
        ).fetchone()
        album_row = conn.execute(
            """
            SELECT COALESCE(MAX(folder_position), -1) AS max_position
            FROM photo_albums
            WHERE folder_id = ?
            """,
            (str(parent_folder_id or ""),),
        ).fetchone()
        folder_position = int(folder_row["max_position"] if folder_row else -1)
        album_position = int(album_row["max_position"] if album_row else -1)
        return max(folder_position, album_position) + 1

    def _validate_photo_album_folder_parent(self, folder_id: str, parent_folder_id: str, conn: sqlite3.Connection) -> None:
        folder_id = str(folder_id or "")
        parent_folder_id = str(parent_folder_id or "")
        if not parent_folder_id:
            return
        if parent_folder_id == folder_id:
            raise ValueError("Album folder cannot be its own parent.")
        parent = self.photo_album_folder_by_id(parent_folder_id, conn)
        if parent is None:
            raise ValueError("Unknown album folder parent id.")
        seen: set[str] = set()
        current = str(parent.get("parentFolderId", "") or "")
        while current:
            if current == folder_id:
                raise ValueError("Album folder parent would create a cycle.")
            if current in seen:
                raise ValueError("Album folder hierarchy contains a cycle.")
            seen.add(current)
            row = self.photo_album_folder_by_id(current, conn)
            if row is None:
                break
            current = str(row.get("parentFolderId", "") or "")

    def upsert_photo_album_folder(
        self,
        *,
        folder_id: str,
        name: str,
        parent_folder_id: str = "",
        position: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.upsert_photo_album_folder(
                    folder_id=folder_id,
                    name=name,
                    parent_folder_id=parent_folder_id,
                    position=position,
                    conn=local_conn,
                )
        folder_id = str(folder_id or "").strip()
        folder_name = str(name or "").strip()
        if not folder_id:
            raise ValueError("Album folder id is required.")
        if not folder_name:
            raise ValueError("Album folder name is required.")
        parent_id = str(parent_folder_id or "").strip()
        self._validate_photo_album_folder_parent(folder_id, parent_id, conn)
        existing = self.photo_album_folder_by_id(folder_id, conn)
        now = now_iso()
        created_at = existing["createdAt"] if existing else now
        if position is None:
            existing_parent_id = str(existing.get("parentFolderId", "") or "") if existing else ""
            next_position = (
                int(existing["position"])
                if existing and existing_parent_id == parent_id
                else self._next_photo_album_container_position(parent_id, conn)
            )
        else:
            next_position = int(position)
        conn.execute(
            """
            INSERT INTO photo_album_folders(folder_id, name, parent_folder_id, position, created_at, updated_at)
            VALUES(?, ?, ?, ?, ?, ?)
            ON CONFLICT(folder_id) DO UPDATE SET
                name=excluded.name,
                parent_folder_id=excluded.parent_folder_id,
                position=excluded.position,
                updated_at=excluded.updated_at
            """,
            (folder_id, folder_name, parent_id or None, next_position, str(created_at or now), now),
        )
        folder = self.photo_album_folder_by_id(folder_id, conn)
        if folder is None:
            raise sqlite3.DatabaseError("photo album folder was not saved")
        return folder

    def delete_photo_album_folder(self, folder_id: str, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_album_folder(folder_id, local_conn)
        clean_folder_id = str(folder_id or "").strip()
        if not clean_folder_id:
            return 0
        now = now_iso()
        conn.execute(
            "UPDATE photo_albums SET folder_id = '', updated_at = ? WHERE folder_id = ?",
            (now, clean_folder_id),
        )
        conn.execute(
            "UPDATE photo_album_folders SET parent_folder_id = NULL, updated_at = ? WHERE parent_folder_id = ?",
            (now, clean_folder_id),
        )
        cur = conn.execute("DELETE FROM photo_album_folders WHERE folder_id = ?", (clean_folder_id,))
        return int(cur.rowcount or 0)

    def reorder_photo_album_folder_children(
        self,
        parent_folder_id: str,
        items: Iterable[dict[str, Any]],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.reorder_photo_album_folder_children(parent_folder_id, items, local_conn)
        parent_id = str(parent_folder_id or "").strip()
        if parent_id and self.photo_album_folder_by_id(parent_id, conn) is None:
            raise ValueError("Unknown album folder parent id.")
        cleaned: list[tuple[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for item in items:
            if not isinstance(item, dict):
                continue
            kind = str(item.get("kind", "") or "").strip()
            item_id = str(item.get("id", item.get("itemId", "")) or "").strip()
            if kind in {"albumFolder", "folder"}:
                key = ("folder", item_id)
            elif kind == "album":
                key = ("album", item_id)
            else:
                continue
            if not item_id or key in seen:
                continue
            seen.add(key)
            cleaned.append(key)
        if not cleaned:
            return {"parentFolderId": parent_id, "updated": 0, "requested": 0}

        updated = 0
        now = now_iso()
        for position, (kind, item_id) in enumerate(cleaned):
            if kind == "folder":
                folder = self.photo_album_folder_by_id(item_id, conn)
                if folder is None:
                    raise ValueError("Unknown album folder id.")
                if str(folder.get("parentFolderId", "") or "") != parent_id:
                    raise ValueError("Album folder is not a child of the requested parent.")
                cur = conn.execute(
                    "UPDATE photo_album_folders SET position = ?, updated_at = ? WHERE folder_id = ?",
                    (position, now, item_id),
                )
            else:
                album = self.photo_album_by_id(item_id, conn)
                if album is None:
                    raise ValueError("Unknown photo album id.")
                if str(album.get("folderId", "") or "") != parent_id:
                    raise ValueError("Photo album is not a child of the requested parent.")
                cur = conn.execute(
                    "UPDATE photo_albums SET folder_position = ?, updated_at = ? WHERE album_id = ?",
                    (position, now, item_id),
                )
            updated += int(cur.rowcount or 0)
        return {
            "parentFolderId": parent_id,
            "updated": updated,
            "requested": len(cleaned),
            "items": [{"kind": kind, "id": item_id, "position": index} for index, (kind, item_id) in enumerate(cleaned)],
        }

    def move_photo_album_to_folder(
        self,
        album_id: str,
        folder_id: str,
        position: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.move_photo_album_to_folder(album_id, folder_id, position, local_conn)
        clean_album_id = str(album_id or "").strip()
        clean_folder_id = str(folder_id or "").strip()
        album = self.photo_album_by_id(clean_album_id, conn)
        if album is None:
            raise ValueError("Unknown photo album id.")
        if clean_folder_id and self.photo_album_folder_by_id(clean_folder_id, conn) is None:
            raise ValueError("Unknown album folder id.")
        existing_folder_id = str(album.get("folderId", "") or "")
        next_position = (
            int(position)
            if position is not None
            else int(album.get("folderPosition", 0) or 0)
            if existing_folder_id == clean_folder_id
            else self._next_photo_album_container_position(clean_folder_id, conn)
        )
        conn.execute(
            "UPDATE photo_albums SET folder_id = ?, folder_position = ?, updated_at = ? WHERE album_id = ?",
            (clean_folder_id, next_position, now_iso(), clean_album_id),
        )
        moved = self.photo_album_by_id(clean_album_id, conn)
        if moved is None:
            raise sqlite3.DatabaseError("photo album was not moved")
        return moved

    def _album_row(self, row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
        def parse_people(value: Any) -> list[str]:
            try:
                payload = json.loads(str(value or "[]"))
            except json.JSONDecodeError:
                payload = []
            if not isinstance(payload, list):
                return []
            seen: set[str] = set()
            people: list[str] = []
            for item in payload:
                person = str(item or "").strip()
                key = person.casefold()
                if person and key not in seen:
                    seen.add(key)
                    people.append(person)
            return people

        try:
            rules = json.loads(str(row["rules_json"] or "{}"))
        except (KeyError, json.JSONDecodeError):
            rules = {}
        if not isinstance(rules, dict):
            rules = {}

        return {
            "albumId": str(row["album_id"] or ""),
            "name": str(row["name"] or ""),
            "albumKind": str(row["album_kind"] or "smart") if "album_kind" in row.keys() else "smart",
            "description": str(row["description"] or "") if "description" in row.keys() else "",
            "folderId": str(row["folder_id"] or "") if "folder_id" in row.keys() else "",
            "folderPosition": int(row["folder_position"] or 0) if "folder_position" in row.keys() else 0,
            "includePeople": parse_people(row["include_people_json"]),
            "excludePeople": parse_people(row["exclude_people_json"]),
            "rules": rules,
            "coverSourcePath": str(row["cover_source_path"] or ""),
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def list_photo_albums(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_albums(local_conn)
        rows = conn.execute(
            """
            SELECT album_id, name, album_kind, description, include_people_json, exclude_people_json,
                folder_id, folder_position, rules_json, cover_source_path, created_at, updated_at
            FROM photo_albums
            ORDER BY folder_id ASC, folder_position ASC, updated_at DESC, name ASC, album_id ASC
            """
        ).fetchall()
        return [self._album_row(row) for row in rows]

    def photo_album_by_id(self, album_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_album_by_id(album_id, local_conn)
        row = conn.execute(
            """
            SELECT album_id, name, album_kind, description, include_people_json, exclude_people_json,
                folder_id, folder_position, rules_json, cover_source_path, created_at, updated_at
            FROM photo_albums
            WHERE album_id = ?
            LIMIT 1
            """,
            (str(album_id or ""),),
        ).fetchone()
        return self._album_row(row) if row else None

    def upsert_photo_album(
        self,
        *,
        album_id: str,
        name: str,
        include_people: Iterable[str],
        exclude_people: Iterable[str],
        album_kind: str = "smart",
        description: str = "",
        rules: dict[str, Any] | None = None,
        cover_source_path: str = "",
        folder_id: str = "",
        folder_position: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.upsert_photo_album(
                    album_id=album_id,
                    name=name,
                    album_kind=album_kind,
                    description=description,
                    include_people=include_people,
                    exclude_people=exclude_people,
                    rules=rules,
                    cover_source_path=cover_source_path,
                    folder_id=folder_id,
                    folder_position=folder_position,
                    conn=local_conn,
                )
        now = now_iso()
        existing = self.photo_album_by_id(album_id, conn)
        created_at = existing["createdAt"] if existing else now
        kind = str(album_kind or "smart").strip().lower()
        if kind not in {"smart", "manual"}:
            kind = "smart"
        clean_folder_id = str(folder_id or "").strip()
        if clean_folder_id and self.photo_album_folder_by_id(clean_folder_id, conn) is None:
            raise ValueError("Unknown album folder id.")
        existing_folder_id = str(existing.get("folderId", "") or "") if existing else ""
        if folder_position is None:
            next_folder_position = (
                int(existing.get("folderPosition", 0) or 0)
                if existing and existing_folder_id == clean_folder_id
                else self._next_photo_album_container_position(clean_folder_id, conn)
            )
        else:
            next_folder_position = int(folder_position)
        conn.execute(
            """
            INSERT INTO photo_albums(
                album_id, name, album_kind, description, include_people_json, exclude_people_json,
                folder_id, folder_position, rules_json, cover_source_path, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(album_id) DO UPDATE SET
                name=excluded.name,
                album_kind=excluded.album_kind,
                description=excluded.description,
                include_people_json=excluded.include_people_json,
                exclude_people_json=excluded.exclude_people_json,
                folder_id=excluded.folder_id,
                folder_position=excluded.folder_position,
                rules_json=excluded.rules_json,
                cover_source_path=excluded.cover_source_path,
                updated_at=excluded.updated_at
            """,
            (
                str(album_id),
                str(name),
                kind,
                str(description or ""),
                json.dumps(list(include_people), separators=(",", ":")),
                json.dumps(list(exclude_people), separators=(",", ":")),
                clean_folder_id,
                next_folder_position,
                json.dumps(rules or {}, separators=(",", ":"), sort_keys=True),
                str(cover_source_path or ""),
                str(created_at or now),
                now,
            ),
        )
        album = self.photo_album_by_id(album_id, conn)
        if album is None:
            raise sqlite3.DatabaseError("photo album was not saved")
        return album

    def delete_photo_album(self, album_id: str, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_album(album_id, local_conn)
        cur = conn.execute("DELETE FROM photo_albums WHERE album_id = ?", (str(album_id or ""),))
        return int(cur.rowcount or 0)

    def _photo_saved_filter_row(self, row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
        def parse_json_object(value: Any) -> dict[str, Any]:
            try:
                payload = json.loads(str(value or "{}"))
            except json.JSONDecodeError:
                payload = {}
            return payload if isinstance(payload, dict) else {}

        return {
            "filterId": str(row["filter_id"] or ""),
            "name": str(row["name"] or ""),
            "description": str(row["description"] or ""),
            "filters": parse_json_object(row["filters_json"]),
            "rules": parse_json_object(row["rules_json"]),
            "pinned": bool(int(row["pinned"] or 0)),
            "position": int(row["position"] or 0),
            "createdAt": str(row["created_at"] or ""),
            "updatedAt": str(row["updated_at"] or ""),
        }

    def list_photo_saved_filters(self, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_saved_filters(local_conn)
        rows = conn.execute(
            """
            SELECT filter_id, name, description, filters_json, rules_json, pinned, position, created_at, updated_at
            FROM photo_saved_filters
            ORDER BY pinned DESC, position ASC, updated_at DESC, name ASC, filter_id ASC
            """
        ).fetchall()
        return [self._photo_saved_filter_row(row) for row in rows]

    def photo_saved_filter_by_id(self, filter_id: str, conn: sqlite3.Connection | None = None) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_saved_filter_by_id(filter_id, local_conn)
        row = conn.execute(
            """
            SELECT filter_id, name, description, filters_json, rules_json, pinned, position, created_at, updated_at
            FROM photo_saved_filters
            WHERE filter_id = ?
            LIMIT 1
            """,
            (str(filter_id or ""),),
        ).fetchone()
        return self._photo_saved_filter_row(row) if row else None

    def _next_photo_saved_filter_position(self, conn: sqlite3.Connection) -> int:
        row = conn.execute("SELECT COALESCE(MAX(position), -1) + 1 AS next_position FROM photo_saved_filters").fetchone()
        return int(row["next_position"] if row else 0)

    def upsert_photo_saved_filter(
        self,
        *,
        filter_id: str,
        name: str,
        description: str = "",
        filters: dict[str, Any] | None = None,
        rules: dict[str, Any] | None = None,
        pinned: bool | None = None,
        position: int | None = None,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.upsert_photo_saved_filter(
                    filter_id=filter_id,
                    name=name,
                    description=description,
                    filters=filters,
                    rules=rules,
                    pinned=pinned,
                    position=position,
                    conn=local_conn,
                )
        clean_id = str(filter_id or "").strip()
        if not clean_id:
            raise ValueError("Saved filter id is required.")
        clean_name = str(name or "").strip()[:120]
        if not clean_name:
            raise ValueError("Saved filter name is required.")
        existing = self.photo_saved_filter_by_id(clean_id, conn)
        now = now_iso()
        created_at = existing["createdAt"] if existing else now
        next_pinned = bool(pinned) if pinned is not None else bool(existing.get("pinned", False) if existing else False)
        next_position = int(position) if position is not None else (int(existing.get("position", 0) or 0) if existing else self._next_photo_saved_filter_position(conn))
        conn.execute(
            """
            INSERT INTO photo_saved_filters(
                filter_id, name, description, filters_json, rules_json, pinned, position, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(filter_id) DO UPDATE SET
                name=excluded.name,
                description=excluded.description,
                filters_json=excluded.filters_json,
                rules_json=excluded.rules_json,
                pinned=excluded.pinned,
                position=excluded.position,
                updated_at=excluded.updated_at
            """,
            (
                clean_id,
                clean_name,
                str(description or "")[:500],
                json.dumps(filters or {}, separators=(",", ":"), sort_keys=True),
                json.dumps(rules or {}, separators=(",", ":"), sort_keys=True),
                1 if next_pinned else 0,
                next_position,
                str(created_at or now),
                now,
            ),
        )
        saved = self.photo_saved_filter_by_id(clean_id, conn)
        if saved is None:
            raise sqlite3.DatabaseError("photo saved filter was not saved")
        return saved

    def delete_photo_saved_filter(self, filter_id: str, conn: sqlite3.Connection | None = None) -> int:
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_photo_saved_filter(filter_id, local_conn)
        cur = conn.execute("DELETE FROM photo_saved_filters WHERE filter_id = ?", (str(filter_id or ""),))
        return int(cur.rowcount or 0)

    def _require_manual_album(self, album_id: str, conn: sqlite3.Connection) -> dict[str, Any]:
        album = self.photo_album_by_id(album_id, conn)
        if album is None:
            raise ValueError("Unknown photo album id.")
        if str(album.get("albumKind", "smart")) != "manual":
            raise ValueError("Photo album item membership is only available for manual albums.")
        return album

    def _clean_album_source_paths(self, source_paths: Iterable[Any]) -> tuple[list[str], int]:
        seen: set[str] = set()
        paths: list[str] = []
        duplicates = 0
        for value in source_paths:
            source = str(value or "").strip()
            if not source:
                continue
            if source in seen:
                duplicates += 1
                continue
            seen.add(source)
            paths.append(source)
        return paths, duplicates

    def add_photo_album_items(
        self,
        album_id: str,
        source_paths: Iterable[Any],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.add_photo_album_items(album_id, source_paths, local_conn)
        album = self._require_manual_album(album_id, conn)
        previous = self._photo_album_items_snapshot(str(album["albumId"]), conn)
        paths, duplicate_inputs = self._clean_album_source_paths(source_paths)
        row = conn.execute(
            "SELECT COALESCE(MAX(position), -1) AS max_position FROM photo_album_items WHERE album_id = ?",
            (str(album["albumId"]),),
        ).fetchone()
        position = int(row["max_position"] if row else -1)
        added = 0
        duplicates = duplicate_inputs
        missing = 0
        now = now_iso()
        for source in paths:
            asset = self.photo_asset_by_path(source, conn)
            asset_id = str(asset["assetId"]) if asset else self._upsert_photo_asset(
                conn,
                source_path=source,
                metadata={"source": "manual_album"},
            )
            if not asset_id:
                missing += 1
                continue
            exists = conn.execute(
                "SELECT 1 FROM photo_album_items WHERE album_id = ? AND asset_id = ? LIMIT 1",
                (str(album["albumId"]), asset_id),
            ).fetchone()
            if exists:
                duplicates += 1
                continue
            position += 1
            conn.execute(
                """
                INSERT INTO photo_album_items(album_id, asset_id, position, added_at)
                VALUES(?, ?, ?, ?)
                """,
                (str(album["albumId"]), asset_id, position, now),
            )
            added += 1
        if added:
            conn.execute(
                "UPDATE photo_albums SET updated_at = ? WHERE album_id = ?",
                (now, str(album["albumId"])),
            )
        item_count = conn.execute(
            "SELECT COUNT(*) AS n FROM photo_album_items WHERE album_id = ?",
            (str(album["albumId"]),),
        ).fetchone()
        operation = self.record_photo_album_items_operation(
            operation_type="album_items_add",
            label=f"Add to {str(album.get('name', '') or 'album')}",
            album_id=str(album["albumId"]),
            previous=previous,
            affected_count=added,
            conn=conn,
        ) if added else None
        return {
            "albumId": str(album["albumId"]),
            "added": added,
            "duplicates": duplicates,
            "missing": missing,
            "requested": len(paths) + duplicate_inputs,
            "itemCount": int(item_count["n"] if item_count else 0),
            "operation": operation,
        }

    def remove_photo_album_items(
        self,
        album_id: str,
        source_paths: Iterable[Any],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.remove_photo_album_items(album_id, source_paths, local_conn)
        album = self._require_manual_album(album_id, conn)
        previous = self._photo_album_items_snapshot(str(album["albumId"]), conn)
        paths, duplicate_inputs = self._clean_album_source_paths(source_paths)
        removed = 0
        missing = duplicate_inputs
        for source in paths:
            asset = self.photo_asset_by_path(source, conn)
            if not asset:
                missing += 1
                continue
            cur = conn.execute(
                "DELETE FROM photo_album_items WHERE album_id = ? AND asset_id = ?",
                (str(album["albumId"]), str(asset["assetId"])),
            )
            if int(cur.rowcount or 0):
                removed += int(cur.rowcount or 0)
            else:
                missing += 1
        if removed:
            conn.execute(
                "UPDATE photo_albums SET updated_at = ? WHERE album_id = ?",
                (now_iso(), str(album["albumId"])),
            )
        item_count = conn.execute(
            "SELECT COUNT(*) AS n FROM photo_album_items WHERE album_id = ?",
            (str(album["albumId"]),),
        ).fetchone()
        operation = self.record_photo_album_items_operation(
            operation_type="album_items_remove",
            label=f"Remove from {str(album.get('name', '') or 'album')}",
            album_id=str(album["albumId"]),
            previous=previous,
            affected_count=removed,
            conn=conn,
        ) if removed else None
        return {
            "albumId": str(album["albumId"]),
            "removed": removed,
            "missing": missing,
            "requested": len(paths) + duplicate_inputs,
            "itemCount": int(item_count["n"] if item_count else 0),
            "operation": operation,
        }

    def reorder_photo_album_items(
        self,
        album_id: str,
        source_paths: Iterable[Any],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.reorder_photo_album_items(album_id, source_paths, local_conn)
        album = self._require_manual_album(album_id, conn)
        previous = self._photo_album_items_snapshot(str(album["albumId"]), conn)
        paths, duplicate_inputs = self._clean_album_source_paths(source_paths)
        previous_items = [item for item in previous.get("items", []) if isinstance(item, dict)]
        previous_asset_ids = [str(item.get("assetId", "") or "") for item in previous_items if str(item.get("assetId", "") or "")]
        previous_position_by_asset = {
            str(item.get("assetId", "") or ""): int(item.get("position", 0) or 0)
            for item in previous_items
            if str(item.get("assetId", "") or "")
        }
        existing_asset_ids = set(previous_asset_ids)
        ordered_asset_ids: list[str] = []
        ordered_asset_set: set[str] = set()
        missing = 0
        for source in paths:
            asset = self.photo_asset_by_path(source, conn)
            asset_id = str(asset.get("assetId", "") or "") if asset else ""
            if not asset_id or asset_id not in existing_asset_ids:
                missing += 1
                continue
            if asset_id in ordered_asset_set:
                continue
            ordered_asset_ids.append(asset_id)
            ordered_asset_set.add(asset_id)
        appended_asset_ids = [asset_id for asset_id in previous_asset_ids if asset_id not in ordered_asset_set]
        next_asset_ids = ordered_asset_ids + appended_asset_ids
        if not ordered_asset_ids:
            return {
                "albumId": str(album["albumId"]),
                "updated": 0,
                "requested": len(paths) + duplicate_inputs,
                "missing": missing,
                "duplicates": duplicate_inputs,
                "appended": 0,
                "operation": None,
            }
        updated = 0
        for position, asset_id in enumerate(next_asset_ids):
            if previous_position_by_asset.get(asset_id) == position:
                continue
            cur = conn.execute(
                """
                UPDATE photo_album_items
                SET position = ?
                WHERE album_id = ? AND asset_id = ?
                """,
                (position, str(album["albumId"]), asset_id),
            )
            updated += int(cur.rowcount or 0)
        if updated:
            conn.execute(
                "UPDATE photo_albums SET updated_at = ? WHERE album_id = ?",
                (now_iso(), str(album["albumId"])),
            )
        current = self._photo_album_items_snapshot(str(album["albumId"]), conn)
        previous_order = [str(item.get("assetId", "") or "") for item in previous.get("items", [])]
        current_order = [str(item.get("assetId", "") or "") for item in current.get("items", [])]
        operation = self.record_photo_album_items_operation(
            operation_type="album_items_reorder",
            label=f"Reorder {str(album.get('name', '') or 'album')}",
            album_id=str(album["albumId"]),
            previous=previous,
            affected_count=updated,
            conn=conn,
        ) if updated and previous_order != current_order else None
        return {
            "albumId": str(album["albumId"]),
            "updated": updated,
            "requested": len(paths) + duplicate_inputs,
            "missing": missing,
            "duplicates": duplicate_inputs,
            "appended": len(appended_asset_ids),
            "operation": operation,
        }

    def list_photo_album_assets(self, album_id: str, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_album_assets(album_id, local_conn)
        self._require_manual_album(album_id, conn)
        rows = conn.execute(
            """
            SELECT a.*, i.position AS album_position, i.added_at AS album_added_at
            FROM photo_album_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            WHERE i.album_id = ?
            ORDER BY i.position ASC, i.added_at ASC, a.source_path ASC
            """,
            (str(album_id or ""),),
        ).fetchall()
        assets: list[dict[str, Any]] = []
        for row in rows:
            asset = self._photo_asset_row(row, conn, {})
            asset["albumPosition"] = int(row["album_position"] or 0)
            asset["albumAddedAt"] = str(row["album_added_at"] or "")
            assets.append(asset)
        return assets

    def list_photo_album_source_paths(
        self,
        album_id: str,
        *,
        include_hidden: bool = False,
        include_deleted: bool = False,
        conn: sqlite3.Connection | None = None,
    ) -> list[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_album_source_paths(
                    album_id,
                    include_hidden=include_hidden,
                    include_deleted=include_deleted,
                    conn=local_conn,
                )
        self._require_manual_album(album_id, conn)
        visibility_sql = ""
        if not include_hidden:
            visibility_sql += " AND COALESCE(m.hidden, 0) = 0"
        if not include_deleted:
            visibility_sql += " AND m.deleted_at IS NULL"
        rows = conn.execute(
            f"""
            SELECT a.source_path
            FROM photo_album_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id = ?
                {visibility_sql}
            ORDER BY i.position ASC, i.added_at ASC, a.source_path ASC
            """,
            (str(album_id or ""),),
        ).fetchall()
        return [str(row["source_path"] or "") for row in rows if str(row["source_path"] or "")]

    def photo_manual_album_summary(
        self,
        album_id: str,
        *,
        cover_source_path: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_manual_album_summary(album_id, cover_source_path=cover_source_path, conn=local_conn)
        self._require_manual_album(album_id, conn)
        count_row = conn.execute(
            """
            SELECT COUNT(*) AS n
            FROM photo_album_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id = ?
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            """,
            (str(album_id or ""),),
        ).fetchone()
        clean_cover = str(cover_source_path or "")
        cover_match = False
        if clean_cover:
            cover_row = conn.execute(
                """
                SELECT 1
                FROM photo_album_items AS i
                JOIN photo_assets AS a ON a.asset_id = i.asset_id
                LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
                WHERE i.album_id = ?
                    AND a.source_path = ?
                    AND COALESCE(m.hidden, 0) = 0
                    AND m.deleted_at IS NULL
                LIMIT 1
                """,
                (str(album_id or ""), clean_cover),
            ).fetchone()
            cover_match = cover_row is not None
        fallback_row = conn.execute(
            """
            SELECT a.source_path
            FROM photo_album_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id = ?
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY i.position ASC, i.added_at ASC, a.source_path ASC
            LIMIT 1
            """,
            (str(album_id or ""),),
        ).fetchone()
        fallback_cover = str(fallback_row["source_path"] or "") if fallback_row else ""
        return {
            "count": int(count_row["n"] if count_row else 0),
            "coverSourcePath": clean_cover if cover_match else fallback_cover,
            "coverMatches": cover_match,
        }

    def photo_manual_album_visible_source_paths(
        self,
        album_id: str,
        conn: sqlite3.Connection | None = None,
    ) -> list[str]:
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_manual_album_visible_source_paths(album_id, local_conn)
        self._require_manual_album(album_id, conn)
        rows = conn.execute(
            """
            SELECT a.source_path
            FROM photo_album_items AS i
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id = ?
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY i.position ASC, i.added_at ASC, a.source_path ASC
            """,
            (str(album_id or ""),),
        ).fetchall()
        return [str(row["source_path"] or "") for row in rows if str(row["source_path"] or "")]

    def photo_manual_album_folder_summary(
        self,
        album_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        clean_ids: list[str] = []
        seen: set[str] = set()
        for album_id in album_ids:
            clean_id = str(album_id or "").strip()
            if clean_id and clean_id not in seen:
                seen.add(clean_id)
                clean_ids.append(clean_id)
        if not clean_ids:
            return {"count": 0, "coverSourcePath": ""}
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_manual_album_folder_summary(clean_ids, local_conn)
        placeholders = ",".join("?" for _ in clean_ids)
        count_row = conn.execute(
            f"""
            SELECT COUNT(DISTINCT a.source_path) AS n
            FROM photo_album_items AS i
            JOIN photo_albums AS al ON al.album_id = i.album_id
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id IN ({placeholders})
                AND al.album_kind = 'manual'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            """,
            tuple(clean_ids),
        ).fetchone()
        cover_row = conn.execute(
            f"""
            SELECT a.source_path
            FROM photo_album_items AS i
            JOIN photo_albums AS al ON al.album_id = i.album_id
            JOIN photo_assets AS a ON a.asset_id = i.asset_id
            LEFT JOIN photo_asset_metadata AS m ON m.asset_id = a.asset_id
            WHERE i.album_id IN ({placeholders})
                AND al.album_kind = 'manual'
                AND COALESCE(m.hidden, 0) = 0
                AND m.deleted_at IS NULL
            ORDER BY al.folder_id ASC,
                al.folder_position ASC,
                al.updated_at DESC,
                al.name ASC,
                al.album_id ASC,
                i.position ASC,
                i.added_at ASC,
                a.source_path ASC
            LIMIT 1
            """,
            tuple(clean_ids),
        ).fetchone()
        return {
            "count": int(count_row["n"] if count_row else 0),
            "coverSourcePath": str(cover_row["source_path"] or "") if cover_row else "",
        }

    def list_photo_asset_album_memberships(self, asset_id: str, conn: sqlite3.Connection | None = None) -> list[dict[str, Any]]:
        if conn is None:
            with self.connect() as local_conn:
                return self.list_photo_asset_album_memberships(asset_id, local_conn)
        rows = conn.execute(
            """
            SELECT a.album_id, a.name, a.album_kind, i.position, i.added_at
            FROM photo_album_items AS i
            JOIN photo_albums AS a ON a.album_id = i.album_id
            WHERE i.asset_id = ?
            ORDER BY a.name ASC, a.album_id ASC
            """,
            (str(asset_id or ""),),
        ).fetchall()
        return [
            {
                "albumId": str(row["album_id"] or ""),
                "name": str(row["name"] or ""),
                "albumKind": str(row["album_kind"] or "manual"),
                "position": int(row["position"] or 0),
                "addedAt": str(row["added_at"] or ""),
                "derived": False,
            }
            for row in rows
        ]

    def photo_asset_album_memberships_by_ids(
        self,
        asset_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, list[dict[str, Any]]]:
        clean_ids = [str(value or "").strip() for value in dict.fromkeys(asset_ids or []) if str(value or "").strip()]
        if not clean_ids:
            return {}
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_asset_album_memberships_by_ids(clean_ids, conn=local_conn)
        result: dict[str, list[dict[str, Any]]] = {asset_id: [] for asset_id in clean_ids}
        for start in range(0, len(clean_ids), 800):
            chunk = clean_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT i.asset_id, a.album_id, a.name, a.album_kind, i.position, i.added_at
                FROM photo_album_items AS i
                JOIN photo_albums AS a ON a.album_id = i.album_id
                WHERE i.asset_id IN ({placeholders})
                ORDER BY i.asset_id ASC, a.name ASC, a.album_id ASC
                """,
                tuple(chunk),
            ).fetchall()
            for row in rows:
                asset_id = str(row["asset_id"] or "")
                result.setdefault(asset_id, []).append({
                    "albumId": str(row["album_id"] or ""),
                    "name": str(row["name"] or ""),
                    "albumKind": str(row["album_kind"] or "manual"),
                    "position": int(row["position"] or 0),
                    "addedAt": str(row["added_at"] or ""),
                    "derived": False,
                })
        return result

    def photo_asset_ids_with_album_memberships(
        self,
        asset_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> set[str]:
        clean_ids: list[str] = []
        seen: set[str] = set()
        for value in asset_ids:
            asset_id = str(value or "").strip()
            if asset_id and asset_id not in seen:
                seen.add(asset_id)
                clean_ids.append(asset_id)
        if not clean_ids:
            return set()
        if conn is None:
            with self.connect() as local_conn:
                return self.photo_asset_ids_with_album_memberships(clean_ids, local_conn)
        matched: set[str] = set()
        for start in range(0, len(clean_ids), 800):
            chunk = clean_ids[start:start + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT DISTINCT asset_id
                FROM photo_album_items
                WHERE asset_id IN ({placeholders})
                """,
                tuple(chunk),
            ).fetchall()
            matched.update(str(row["asset_id"] or "") for row in rows if str(row["asset_id"] or ""))
        return matched

    def update_scan_run(
        self,
        run_id: str,
        metrics: dict[str, int],
        status: str = "running",
        last_path: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> None:
        completed_at = now_iso() if status in {"complete", "cancelled", "error"} else None
        if conn is None:
            with self.connect() as local_conn:
                self.update_scan_run(run_id, metrics, status, last_path, local_conn)
            return
        conn.execute(
            """
            UPDATE scan_runs SET
                status = ?,
                completed_at = COALESCE(?, completed_at),
                updated_at = ?,
                total = ?,
                processed = ?,
                added = ?,
                matched = ?,
                clustered = ?,
                skipped = ?,
                errors = ?,
                unmatched = ?,
                safe_filtered = ?,
                video_files = ?,
                video_frames = ?,
                video_protected = ?,
                cancelled = ?,
                last_path = ?
            WHERE run_id = ?
            """,
            (
                status,
                completed_at,
                now_iso(),
                int(metrics.get("total", 0)),
                int(metrics.get("processed", 0)),
                int(metrics.get("added", 0)),
                int(metrics.get("matched", 0)),
                int(metrics.get("clustered", 0)),
                int(metrics.get("skipped", 0)),
                int(metrics.get("errors", 0)),
                int(metrics.get("unmatched", 0)),
                int(metrics.get("safeFiltered", 0)),
                int(metrics.get("videoFiles", 0)),
                int(metrics.get("videoFrames", 0)),
                int(metrics.get("videoProtected", 0)),
                int(metrics.get("cancelled", 0)),
                last_path,
                run_id,
            ),
        )
        self._upsert_photo_import_session_from_scan_run(run_id, conn)

    def relink_scan_paths(self, old_root: Path, new_root: Path) -> dict[str, int]:
        old_base = old_root.expanduser().resolve()
        new_base = new_root.expanduser().resolve()

        def remap(value: str, require_exists: bool = False) -> str:
            if not value:
                return value
            try:
                original = Path(value).expanduser().resolve()
                relative = original.relative_to(old_base)
            except (OSError, ValueError):
                return value
            target = new_base / relative
            if require_exists and not target.exists():
                return value
            try:
                return str(target.resolve())
            except OSError:
                return str(target)

        runs_updated = 0
        files_updated = 0
        with self.connect() as conn:
            runs = conn.execute("SELECT run_id, label, root_path, last_path FROM scan_runs").fetchall()
            for row in runs:
                next_label = remap(str(row["label"]))
                next_root = remap(str(row["root_path"]))
                next_last = remap(str(row["last_path"]), require_exists=True)
                if next_label != row["label"] or next_root != row["root_path"] or next_last != row["last_path"]:
                    conn.execute(
                        "UPDATE scan_runs SET label = ?, root_path = ?, last_path = ?, updated_at = ? WHERE run_id = ?",
                        (next_label, next_root, next_last, now_iso(), row["run_id"]),
                    )
                    runs_updated += 1
            rows = conn.execute("SELECT * FROM scan_files").fetchall()
            for row in rows:
                old_path = Path(str(row["path"]))
                new_path = Path(remap(str(row["path"]), require_exists=True))
                if str(new_path) == str(row["path"]):
                    continue
                try:
                    signature = path_signature(new_path)
                except OSError:
                    continue
                conn.execute(
                    "DELETE FROM scan_files WHERE run_id = ? AND path = ? AND path_key = ?",
                    (row["run_id"], row["path"], row["path_key"]),
                )
                conn.execute(
                    """
                    INSERT OR REPLACE INTO scan_files(
                        run_id, path, path_key, size, mtime_ns, content_hash, status, phase,
                        message, candidate_id, safety_score, processed_at
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        row["run_id"],
                        str(new_path),
                        str(signature["pathKey"]),
                        int(signature["size"]),
                        int(signature["mtimeNs"]),
                        row["content_hash"],
                        row["status"],
                        row["phase"],
                        row["message"],
                        row["candidate_id"],
                        row["safety_score"],
                        row["processed_at"],
                    ),
                )
                del old_path
                files_updated += 1
        return {"scanRuns": runs_updated, "scanFiles": files_updated}

    def safety_lookup(
        self,
        file_hash: str,
        model_version: str,
        threshold: float,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.safety_lookup(file_hash, model_version, threshold, local_conn)
        row = conn.execute(
            """
            SELECT * FROM safety_cache
            WHERE file_hash = ? AND model_version = ? AND threshold = ?
            LIMIT 1
            """,
            (file_hash, model_version, float(threshold)),
        ).fetchone()
        if not row:
            return None
        return {
            "sensitive": bool(row["sensitive"]),
            "score": float(row["score"]),
            "reason": str(row["reason"]),
            "engine": str(row["engine"]),
            "model_name": str(row["model_name"]),
            "labels": json.loads(row["labels_json"] or "{}"),
        }

    def safety_store(
        self,
        file_hash: str,
        model_version: str,
        threshold: float,
        assessment: Any,
        conn: sqlite3.Connection | None = None,
    ) -> None:
        labels = getattr(assessment, "labels", {}) or {}
        if conn is None:
            with self.connect() as local_conn:
                self.safety_store(file_hash, model_version, threshold, assessment, local_conn)
            return
        conn.execute(
            """
            INSERT OR REPLACE INTO safety_cache(
                file_hash, model_version, threshold, sensitive, score, reason,
                engine, model_name, labels_json, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                file_hash,
                model_version,
                float(threshold),
                1 if bool(getattr(assessment, "sensitive", False)) else 0,
                float(getattr(assessment, "score", 0.0)),
                str(getattr(assessment, "reason", ""))[:1200],
                str(getattr(assessment, "engine", "")),
                str(getattr(assessment, "model_name", "")),
                json.dumps(labels, separators=(",", ":")),
                now_iso(),
            ),
        )

    def set_safe_mode_override(
        self,
        content_hash: str,
        override_sensitive: Any,
        reason: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> "bool | None":
        """Set (True/False) or clear (None) a per-image Safe Mode override — the user
        confirming or overturning the classifier's verdict. Keyed by content_hash (the
        same identity as safety_cache) so the ingest gate can enforce it on re-scan.
        Returns the stored value, or None when cleared."""
        if conn is None:
            with self.connect() as local_conn:
                return self.set_safe_mode_override(content_hash, override_sensitive, reason, local_conn)
        content_hash = str(content_hash or "").strip()
        if not content_hash:
            return None
        if override_sensitive is None:
            conn.execute("DELETE FROM safe_mode_overrides WHERE content_hash = ?", (content_hash,))
            return None
        value = 1 if bool(override_sensitive) else 0
        conn.execute(
            """
            INSERT OR REPLACE INTO safe_mode_overrides(content_hash, override_sensitive, reason, created_at)
            VALUES(?, ?, ?, ?)
            """,
            (content_hash, value, str(reason or "")[:500], now_iso()),
        )
        return bool(value)

    def safe_mode_override_for(self, content_hash: str, conn: sqlite3.Connection | None = None) -> "bool | None":
        if conn is None:
            with self.connect() as local_conn:
                return self.safe_mode_override_for(content_hash, local_conn)
        row = conn.execute(
            "SELECT override_sensitive FROM safe_mode_overrides WHERE content_hash = ? LIMIT 1",
            (str(content_hash or "").strip(),),
        ).fetchone()
        if not row:
            return None
        return bool(row["override_sensitive"])

    def list_safe_mode_flagged(
        self,
        limit: int = 200,
        offset: int = 0,
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        """Photo assets the Safe Mode classifier flagged (latest cached verdict) or
        that carry a user override. Each item reports the stored verdict, the override,
        and the resulting effective state so the review UI can show and change it.
        Additive read path — does not touch the main photo serialization."""
        if conn is None:
            with self.connect() as local_conn:
                return self.list_safe_mode_flagged(limit, offset, local_conn)
        limit = max(1, min(int(limit or 200), 2000))
        offset = max(0, int(offset or 0))
        where = "sc.sensitive = 1 OR smo.override_sensitive IS NOT NULL"
        latest = (
            "SELECT file_hash, sensitive, score, reason, model_name, labels_json, MAX(created_at) AS created_at "
            "FROM safety_cache GROUP BY file_hash"
        )
        rows = conn.execute(
            f"""
            SELECT pa.asset_id AS asset_id, pa.source_path AS source_path,
                   sc.sensitive AS sensitive, sc.score AS score, sc.reason AS reason,
                   sc.model_name AS model_name, sc.labels_json AS labels_json,
                   smo.override_sensitive AS override_sensitive
            FROM photo_assets pa
            JOIN ({latest}) sc ON sc.file_hash = pa.content_hash
            LEFT JOIN safe_mode_overrides smo ON smo.content_hash = pa.content_hash
            WHERE {where}
            ORDER BY sc.score DESC, pa.source_path ASC
            LIMIT ? OFFSET ?
            """,
            (limit, offset),
        ).fetchall()
        total_row = conn.execute(
            f"""
            SELECT COUNT(*) AS n FROM photo_assets pa
            JOIN ({latest}) sc ON sc.file_hash = pa.content_hash
            LEFT JOIN safe_mode_overrides smo ON smo.content_hash = pa.content_hash
            WHERE {where}
            """
        ).fetchone()
        items: list[dict[str, Any]] = []
        for row in rows:
            stored = bool(row["sensitive"])
            raw_override = row["override_sensitive"]
            override = None if raw_override is None else bool(raw_override)
            try:
                labels = json.loads(row["labels_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                labels = {}
            if not isinstance(labels, dict):
                labels = {}
            items.append({
                "assetId": str(row["asset_id"]),
                "sourcePath": str(row["source_path"]),
                "storedSensitive": stored,
                "override": override,
                "effectiveSensitive": stored if override is None else override,
                "score": float(row["score"] or 0.0),
                "reason": str(row["reason"] or ""),
                "modelName": str(row["model_name"] or ""),
                "categoryScores": {
                    str(key).removeprefix("policy:"): float(value)
                    for key, value in labels.items()
                    if str(key).startswith("policy:") and isinstance(value, (int, float))
                },
            })
        return {
            "items": items,
            "total": int(total_row["n"]) if total_row else len(items),
            "limit": limit,
            "offset": offset,
        }

    def embedding_lookup(
        self,
        file_hash: str,
        model_version: str,
        detector_size: int,
        conn: sqlite3.Connection | None = None,
    ) -> list[dict[str, Any]] | None:
        if conn is None:
            with self.connect() as local_conn:
                return self.embedding_lookup(file_hash, model_version, detector_size, local_conn)
        row = conn.execute(
            """
            SELECT embeddings_json FROM embedding_cache
            WHERE file_hash = ? AND model_version = ? AND detector_size = ?
            LIMIT 1
            """,
            (file_hash, model_version, int(detector_size)),
        ).fetchone()
        if not row:
            return None
        value = json.loads(row["embeddings_json"] or "[]")
        return value if isinstance(value, list) else []

    def embedding_store(
        self,
        file_hash: str,
        model_version: str,
        detector_size: int,
        embeddings: list[dict[str, Any]],
        conn: sqlite3.Connection | None = None,
    ) -> None:
        if conn is None:
            with self.connect() as local_conn:
                self.embedding_store(file_hash, model_version, detector_size, embeddings, local_conn)
            return
        conn.execute(
            """
            INSERT OR REPLACE INTO embedding_cache(
                file_hash, model_version, detector_size, embeddings_json, created_at
            ) VALUES(?, ?, ?, ?, ?)
            """,
            (
                file_hash,
                model_version,
                int(detector_size),
                json.dumps(embeddings, separators=(",", ":")),
                now_iso(),
            ),
        )

    @staticmethod
    def _encode_pair_center(value: Any) -> sqlite3.Binary | None:
        if value is None:
            return None
        if hasattr(value, "tolist"):
            value = value.tolist()
        if not isinstance(value, (list, tuple)):
            raise ValueError("Adaptive calibration pair centers must be numeric vectors.")
        if not value:
            return None
        if len(value) != 512:
            raise ValueError("Adaptive calibration pair centers must contain exactly 512 values.")
        try:
            values = [float(item) for item in value]
        except (TypeError, ValueError) as exc:
            raise ValueError("Adaptive calibration pair centers must contain only numbers.") from exc
        if not all(math.isfinite(item) for item in values):
            raise ValueError("Adaptive calibration pair centers must contain only finite values.")
        norm = math.sqrt(sum(item * item for item in values))
        if not math.isfinite(norm) or norm <= 1e-12:
            raise ValueError("Adaptive calibration pair centers must have a non-zero norm.")
        unit = [item / norm for item in values]
        return sqlite3.Binary(struct.pack("<512f", *unit))

    @staticmethod
    def _decode_pair_center(value: Any) -> list[float]:
        if value is None:
            return []
        try:
            payload = bytes(value)
        except (TypeError, ValueError):
            return []
        if len(payload) != 512 * 4:
            return []
        try:
            values = [float(item) for item in struct.unpack("<512f", payload)]
        except struct.error:
            return []
        if not all(math.isfinite(item) for item in values):
            return []
        norm = math.sqrt(sum(item * item for item in values))
        if not math.isfinite(norm) or norm <= 1e-12:
            return []
        return [item / norm for item in values]

    def upsert_candidate_match_context(
        self,
        candidate_id: str,
        best_ref_id: str,
        model_name: str,
        pair_center: Any,
        cohort_z: float | None,
        cohort_version: str,
        conn: sqlite3.Connection | None = None,
    ) -> None:
        candidate_key = str(candidate_id or "").strip()
        reference_key = str(best_ref_id or "").strip()
        model_key = str(model_name or "").strip()
        if not candidate_key or not reference_key or not model_key:
            raise ValueError("Candidate match context requires candidate, reference, and model identifiers.")
        encoded_center = self._encode_pair_center(pair_center)
        if encoded_center is None:
            raise ValueError("Candidate match context requires a pair center.")
        normalized_cohort_z: float | None = None
        if cohort_z is not None:
            normalized_cohort_z = float(cohort_z)
            if not math.isfinite(normalized_cohort_z):
                raise ValueError("Candidate match context cohort scores must be finite.")
        if conn is None:
            with self.connect() as local_conn:
                self.upsert_candidate_match_context(
                    candidate_key,
                    reference_key,
                    model_key,
                    pair_center,
                    normalized_cohort_z,
                    cohort_version,
                    local_conn,
                )
            return
        conn.execute(
            """
            INSERT INTO candidate_match_context(
                candidate_id, best_ref_id, model_name, pair_center, cohort_z,
                cohort_version, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(candidate_id) DO UPDATE SET
                best_ref_id=excluded.best_ref_id,
                model_name=excluded.model_name,
                pair_center=excluded.pair_center,
                cohort_z=excluded.cohort_z,
                cohort_version=excluded.cohort_version,
                created_at=excluded.created_at
            """,
            (
                candidate_key,
                reference_key,
                model_key,
                encoded_center,
                normalized_cohort_z,
                str(cohort_version or "")[:160],
                now_iso(),
            ),
        )

    def candidate_match_context(
        self,
        candidate_id: str,
        *,
        best_ref_id: str = "",
        model_name: str = "",
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any] | None:
        candidate_key = str(candidate_id or "").strip()
        if not candidate_key:
            return None
        if conn is None:
            with self.connect() as local_conn:
                return self.candidate_match_context(
                    candidate_key,
                    best_ref_id=best_ref_id,
                    model_name=model_name,
                    conn=local_conn,
                )
        row = conn.execute(
            """
            SELECT candidate_id, best_ref_id, model_name, pair_center, cohort_z,
                cohort_version, created_at
            FROM candidate_match_context
            WHERE candidate_id = ?
            LIMIT 1
            """,
            (candidate_key,),
        ).fetchone()
        if row is None:
            return None
        stored_reference = str(row["best_ref_id"] or "")
        stored_model = str(row["model_name"] or "")
        if best_ref_id and stored_reference != str(best_ref_id):
            return None
        if model_name and stored_model != str(model_name):
            return None
        center = self._decode_pair_center(row["pair_center"])
        if not center:
            return None
        cohort_z = row["cohort_z"]
        if cohort_z is not None and not math.isfinite(float(cohort_z)):
            return None
        return {
            "candidateId": str(row["candidate_id"] or ""),
            "bestRefId": stored_reference,
            "modelName": stored_model,
            "pairCenter": center,
            "cohortZ": None if cohort_z is None else float(cohort_z),
            "cohortVersion": str(row["cohort_version"] or ""),
            "createdAt": str(row["created_at"] or ""),
        }

    def candidate_match_contexts(
        self,
        candidate_ids: Iterable[str],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, dict[str, Any]]:
        ids = [str(value or "").strip() for value in dict.fromkeys(candidate_ids or []) if str(value or "").strip()]
        if not ids:
            return {}
        if conn is None:
            with self.connect() as local_conn:
                return self.candidate_match_contexts(ids, local_conn)
        result: dict[str, dict[str, Any]] = {}
        for offset in range(0, len(ids), 800):
            chunk = ids[offset:offset + 800]
            placeholders = ",".join("?" for _ in chunk)
            rows = conn.execute(
                f"""
                SELECT candidate_id, best_ref_id, model_name, pair_center, cohort_z,
                    cohort_version, created_at
                FROM candidate_match_context
                WHERE candidate_id IN ({placeholders})
                """,
                chunk,
            ).fetchall()
            for row in rows:
                center = self._decode_pair_center(row["pair_center"])
                cohort_z = row["cohort_z"]
                if not center or (cohort_z is not None and not math.isfinite(float(cohort_z))):
                    continue
                candidate_id = str(row["candidate_id"] or "")
                result[candidate_id] = {
                    "candidateId": candidate_id,
                    "bestRefId": str(row["best_ref_id"] or ""),
                    "modelName": str(row["model_name"] or ""),
                    "pairCenter": center,
                    "cohortZ": None if cohort_z is None else float(cohort_z),
                    "cohortVersion": str(row["cohort_version"] or ""),
                    "createdAt": str(row["created_at"] or ""),
                }
        return result

    def delete_candidate_match_context(
        self,
        candidate_id: str,
        conn: sqlite3.Connection | None = None,
    ) -> int:
        candidate_key = str(candidate_id or "").strip()
        if not candidate_key:
            return 0
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_candidate_match_context(candidate_key, local_conn)
        return int(
            conn.execute(
                "DELETE FROM candidate_match_context WHERE candidate_id = ?",
                (candidate_key,),
            ).rowcount or 0
        )

    def add_calibration_label(
        self,
        label_id: str,
        row: dict[str, Any],
        conn: sqlite3.Connection | None = None,
    ) -> None:
        def _opt_float(value: Any) -> float | None:
            try:
                result = None if value is None else float(value)
            except (TypeError, ValueError):
                return None
            return result if result is None or math.isfinite(result) else None

        pair_center = self._encode_pair_center(row.get("pairCenter"))

        if conn is None:
            with self.connect() as local_conn:
                self.add_calibration_label(label_id, row, local_conn)
            return
        conn.execute(
            """
            INSERT OR REPLACE INTO calibration_labels(
                label_id, source_path, file_hash, expected_person, actual_person,
                match_score, is_match, safe_label, pose_bucket, media_kind, age_gap_years,
                raw_cosine, model_name, best_ref_id, pair_center, cohort_z,
                context_version, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                label_id,
                str(row.get("sourcePath", "")),
                str(row.get("fileHash", "")),
                str(row.get("expectedPerson", "")),
                str(row.get("actualPerson", "")),
                row.get("matchScore"),
                None if row.get("isMatch") is None else (1 if bool(row.get("isMatch")) else 0),
                str(row.get("safeLabel", "")),
                str(row.get("poseBucket", "") or ""),
                str(row.get("mediaKind", "") or "")[:40],
                _opt_float(row.get("ageGapYears")),
                _opt_float(row.get("rawCosine")),
                str(row.get("modelName", "") or ""),
                str(row.get("bestRefId", "") or ""),
                pair_center,
                _opt_float(row.get("cohortZ")),
                str(row.get("contextVersion", "") or "")[:100],
                now_iso(),
            )
        )

    def calibration_label_rows(self) -> list[dict[str, Any]]:
        """Labeled (score, raw_cosine, is_match, pose, age-gap) rows for calibration.

        Only rows with a definite match/non-match and a usable score are returned;
        raw_cosine falls back to match_score for pre-1.2 rows that predate capture.
        """
        with self.connect() as conn:
            cursor = conn.execute(
                """
                SELECT match_score, raw_cosine, is_match, pose_bucket, age_gap_years,
                    media_kind, model_name, expected_person, best_ref_id, pair_center, cohort_z,
                    context_version
                FROM calibration_labels
                WHERE is_match IS NOT NULL AND match_score IS NOT NULL
                ORDER BY created_at ASC
                """
            )
            rows: list[dict[str, Any]] = []
            for record in cursor.fetchall():
                match_score = float(record["match_score"])
                raw = record["raw_cosine"]
                rows.append(
                    {
                        "matchScore": match_score,
                        "rawCosine": match_score if raw is None else float(raw),
                        "isMatch": bool(record["is_match"]),
                        "poseBucket": str(record["pose_bucket"] or ""),
                        "mediaKind": str(record["media_kind"] or ""),
                        "ageGapYears": None if record["age_gap_years"] is None else float(record["age_gap_years"]),
                        "modelName": str(record["model_name"] or ""),
                        "expectedPerson": str(record["expected_person"] or ""),
                        "bestRefId": str(record["best_ref_id"] or ""),
                        "pairCenter": self._decode_pair_center(record["pair_center"]),
                        "cohortZ": None if record["cohort_z"] is None else float(record["cohort_z"]),
                        "contextVersion": str(record["context_version"] or ""),
                    }
                )
            return rows

    def _training_natural_key(self, row: dict[str, Any]) -> str:
        candidate_id = str(row.get("candidateId") or row.get("candidate_id") or "").strip()
        if candidate_id:
            return f"candidate:{candidate_id}"
        source = str(row.get("sourceHash") or row.get("fileHash") or row.get("sourcePath") or "").strip()
        expected = str(row.get("expectedPerson") or "").strip().casefold()
        model = str(row.get("modelName") or "").strip().casefold()
        label = "1" if bool(row.get("isMatch")) else "0"
        digest = hashlib.sha256(f"{source}|{expected}|{model}|{label}".encode("utf-8")).hexdigest()
        return f"pair:{digest}"

    def add_training_example(
        self,
        example_id: str,
        row: dict[str, Any],
        conn: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        """Persist one human-reviewed learning example for future adapters.

        Candidate-backed examples are keyed by candidate id, so changing a review
        from accepted to rejected replaces the current learning example instead of
        leaving both labels active in the adapter dataset.
        """
        def _opt_float(value: Any) -> float | None:
            try:
                return None if value is None else float(value)
            except (TypeError, ValueError):
                return None

        def _json_obj(value: Any) -> str:
            return json.dumps(value if isinstance(value, dict) else {}, separators=(",", ":"), sort_keys=True)

        natural_key = str(row.get("naturalKey") or "").strip() or self._training_natural_key(row)
        is_match = 1 if bool(row.get("isMatch")) else 0
        payload = dict(row)
        payload["naturalKey"] = natural_key
        payload["isMatch"] = bool(is_match)
        features = row.get("features")
        if conn is None:
            with self.connect() as local_conn:
                return self.add_training_example(example_id, row, local_conn)
        conn.execute(
            """
            INSERT INTO training_examples(
                example_id, natural_key, label_id, candidate_id, source_path, source_hash,
                expected_person, actual_person, is_match, match_score, raw_cosine, quality,
                model_name, detector_size, candidate_embedding_key, best_ref_id, best_ref_path,
                reference_model_name, pose_bucket, age_gap_years, align_error, ied_px,
                media_kind, features_json, payload_json, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(natural_key) DO UPDATE SET
                example_id=excluded.example_id,
                label_id=excluded.label_id,
                candidate_id=excluded.candidate_id,
                source_path=excluded.source_path,
                source_hash=excluded.source_hash,
                expected_person=excluded.expected_person,
                actual_person=excluded.actual_person,
                is_match=excluded.is_match,
                match_score=excluded.match_score,
                raw_cosine=excluded.raw_cosine,
                quality=excluded.quality,
                model_name=excluded.model_name,
                detector_size=excluded.detector_size,
                candidate_embedding_key=excluded.candidate_embedding_key,
                best_ref_id=excluded.best_ref_id,
                best_ref_path=excluded.best_ref_path,
                reference_model_name=excluded.reference_model_name,
                pose_bucket=excluded.pose_bucket,
                age_gap_years=excluded.age_gap_years,
                align_error=excluded.align_error,
                ied_px=excluded.ied_px,
                media_kind=excluded.media_kind,
                features_json=excluded.features_json,
                payload_json=excluded.payload_json,
                created_at=excluded.created_at
            """,
            (
                example_id,
                natural_key,
                str(row.get("labelId", "") or ""),
                str(row.get("candidateId", "") or ""),
                str(row.get("sourcePath", "") or ""),
                str(row.get("sourceHash", "") or row.get("fileHash", "") or ""),
                str(row.get("expectedPerson", "") or ""),
                str(row.get("actualPerson", "") or ""),
                is_match,
                _opt_float(row.get("matchScore")),
                _opt_float(row.get("rawCosine")),
                _opt_float(row.get("quality")),
                str(row.get("modelName", "") or ""),
                int(row.get("detectorSize", 0) or 0),
                str(row.get("candidateEmbeddingKey", "") or ""),
                str(row.get("bestRefId", "") or ""),
                str(row.get("bestRefPath", "") or ""),
                str(row.get("referenceModelName", "") or ""),
                str(row.get("poseBucket", "") or ""),
                _opt_float(row.get("ageGapYears")),
                _opt_float(row.get("alignError")),
                _opt_float(row.get("iedPx")),
                str(row.get("mediaKind", "image") or "image"),
                _json_obj(features),
                json.dumps(payload, separators=(",", ":"), sort_keys=True),
                str(row.get("createdAt", "") or now_iso()),
            ),
        )
        return {"exampleId": example_id, "naturalKey": natural_key}

    def training_example_rows(self, limit: int = 0) -> list[dict[str, Any]]:
        sql = """
            SELECT *
            FROM training_examples
            ORDER BY created_at ASC, example_id ASC
        """
        args: tuple[Any, ...] = ()
        if limit and int(limit) > 0:
            sql += " LIMIT ?"
            args = (max(1, int(limit)),)
        with self.connect() as conn:
            rows = conn.execute(sql, args).fetchall()
        result: list[dict[str, Any]] = []
        for row in rows:
            item = dict(row)
            for key in ("features_json", "payload_json"):
                try:
                    item[key.removesuffix("_json")] = json.loads(str(item.get(key) or "{}"))
                except json.JSONDecodeError:
                    item[key.removesuffix("_json")] = {}
            payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
            context = payload.get("trainingContext") if isinstance(payload.get("trainingContext"), dict) else {}
            if context:
                item["trainingContext"] = context
            result.append(item)
        return result

    def training_example_summary(self) -> dict[str, Any]:
        with self.connect() as conn:
            stats = conn.execute(
                """
                SELECT
                    COUNT(*) AS total,
                    SUM(CASE WHEN is_match = 1 THEN 1 ELSE 0 END) AS positive,
                    SUM(CASE WHEN is_match = 0 THEN 1 ELSE 0 END) AS negative,
                    COUNT(DISTINCT expected_person) AS people,
                    COUNT(DISTINCT model_name) AS models
                FROM training_examples
                """
            ).fetchone()
            by_model_rows = conn.execute(
                """
                SELECT model_name, COUNT(*) AS n
                FROM training_examples
                GROUP BY model_name
                ORDER BY n DESC, model_name ASC
                """
            ).fetchall()
        return {
            "totalExamples": int(stats["total"] or 0),
            "positiveExamples": int(stats["positive"] or 0),
            "negativeExamples": int(stats["negative"] or 0),
            "people": int(stats["people"] or 0),
            "models": int(stats["models"] or 0),
            "byModel": {str(row["model_name"] or ""): int(row["n"] or 0) for row in by_model_rows},
        }

    def delete_training_examples_for_candidates(self, candidate_ids: Iterable[str], conn: sqlite3.Connection | None = None) -> int:
        ids = [str(candidate_id) for candidate_id in candidate_ids if str(candidate_id)]
        if conn is None:
            with self.connect() as local_conn:
                return self.delete_training_examples_for_candidates(ids, local_conn)
        if not ids:
            return 0
        placeholders = ",".join("?" for _ in ids)
        count = int(
            conn.execute(
                f"SELECT COUNT(*) AS n FROM training_examples WHERE candidate_id IN ({placeholders})",
                tuple(ids),
            ).fetchone()["n"]
        )
        conn.executemany("DELETE FROM training_examples WHERE candidate_id = ?", [(candidate_id,) for candidate_id in ids])
        return count

    def _artifact_hash(self, row: dict[str, Any], metrics: dict[str, Any], payload: dict[str, Any]) -> str:
        body = {
            "artifactType": str(row.get("artifactType", "") or ""),
            "modelName": str(row.get("modelName", "") or ""),
            "versionKey": str(row.get("versionKey", "") or ""),
            "trainingDataHash": str(row.get("trainingDataHash", "") or ""),
            "metrics": metrics,
            "payload": payload,
        }
        return hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    def upsert_learned_artifact(self, artifact_id: str, row: dict[str, Any]) -> dict[str, Any]:
        status = str(row.get("status", "candidate") or "candidate")
        if status not in {"candidate", "staged", "promoted", "rejected", "rolled_back"}:
            raise ValueError("Learned artifact status must be candidate, staged, promoted, rejected, or rolled_back.")
        metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
        payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        artifact_hash = str(row.get("artifactHash", "") or "") or self._artifact_hash(row, metrics, payload)
        with self.connect() as conn:
            conn.execute(
                """
                INSERT OR REPLACE INTO learned_artifacts(
                    artifact_id, artifact_type, status, model_name, version_key, training_data_hash,
                    input_count, positive_count, negative_count, metrics_json, payload_json,
                    artifact_hash, parent_artifact_id, created_at, promoted_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    artifact_id,
                    str(row.get("artifactType", "") or ""),
                    status,
                    str(row.get("modelName", "") or ""),
                    str(row.get("versionKey", "") or ""),
                    str(row.get("trainingDataHash", "") or ""),
                    int(row.get("inputCount", 0) or 0),
                    int(row.get("positiveCount", 0) or 0),
                    int(row.get("negativeCount", 0) or 0),
                    json.dumps(metrics, separators=(",", ":"), sort_keys=True),
                    json.dumps(payload, separators=(",", ":"), sort_keys=True),
                    artifact_hash,
                    str(row.get("parentArtifactId", "") or ""),
                    str(row.get("createdAt", "") or now_iso()),
                    row.get("promotedAt"),
                ),
            )
        return {"artifactId": artifact_id, "artifactHash": artifact_hash, "status": status}

    def learned_artifact_rows(self, artifact_type: str = "", status: str = "", limit: int = 20) -> list[dict[str, Any]]:
        clauses: list[str] = []
        args: list[Any] = []
        if artifact_type:
            clauses.append("artifact_type = ?")
            args.append(str(artifact_type))
        if status:
            clauses.append("status = ?")
            args.append(str(status))
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        args.append(max(1, min(200, int(limit or 20))))
        with self.connect() as conn:
            rows = conn.execute(
                f"""
                SELECT *
                FROM learned_artifacts
                {where}
                ORDER BY created_at DESC, artifact_id DESC
                LIMIT ?
                """,
                tuple(args),
            ).fetchall()
        result: list[dict[str, Any]] = []
        for row in rows:
            item = dict(row)
            for key in ("metrics_json", "payload_json"):
                try:
                    item[key.removesuffix("_json")] = json.loads(str(item.get(key) or "{}"))
                except json.JSONDecodeError:
                    item[key.removesuffix("_json")] = {}
            result.append(item)
        return result

    def all_learned_artifact_rows(self, artifact_type: str = "", status: str = "") -> list[dict[str, Any]]:
        clauses: list[str] = []
        args: list[Any] = []
        if artifact_type:
            clauses.append("artifact_type = ?")
            args.append(str(artifact_type))
        if status:
            clauses.append("status = ?")
            args.append(str(status))
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        with self.connect() as conn:
            rows = conn.execute(
                f"""
                SELECT *
                FROM learned_artifacts
                {where}
                ORDER BY created_at DESC, artifact_id DESC
                """,
                tuple(args),
            ).fetchall()
        return [self._decode_artifact_row(row) for row in rows]

    def _decode_artifact_row(self, row: sqlite3.Row) -> dict[str, Any]:
        item = dict(row)
        for key in ("metrics_json", "payload_json"):
            try:
                item[key.removesuffix("_json")] = json.loads(str(item.get(key) or "{}"))
            except json.JSONDecodeError:
                item[key.removesuffix("_json")] = {}
        return item

    def learned_artifact_by_id(self, artifact_id: str) -> dict[str, Any] | None:
        artifact_id = str(artifact_id or "").strip()
        if not artifact_id:
            return None
        with self.connect() as conn:
            row = conn.execute(
                """
                SELECT *
                FROM learned_artifacts
                WHERE artifact_id = ?
                LIMIT 1
                """,
                (artifact_id,),
            ).fetchone()
        return self._decode_artifact_row(row) if row else None

    def latest_learned_artifact(self, artifact_type: str, status: str = "") -> dict[str, Any] | None:
        rows = self.learned_artifact_rows(artifact_type=artifact_type, status=status, limit=1)
        return rows[0] if rows else None

    def update_learned_artifact_status(self, artifact_id: str, status: str, promoted_at: str | None = None) -> None:
        if status not in {"candidate", "staged", "promoted", "rejected", "rolled_back"}:
            raise ValueError("Learned artifact status must be candidate, staged, promoted, rejected, or rolled_back.")
        with self.connect() as conn:
            conn.execute(
                """
                UPDATE learned_artifacts
                SET status = ?, promoted_at = ?
                WHERE artifact_id = ?
                """,
                (status, promoted_at, str(artifact_id)),
            )

    def delete_learned_artifacts(self, artifact_ids: Iterable[str]) -> int:
        ids = list(dict.fromkeys(str(item) for item in artifact_ids if str(item)))
        if not ids:
            return 0
        with self.connect() as conn:
            cursor = conn.executemany(
                "DELETE FROM learned_artifacts WHERE artifact_id = ?",
                [(artifact_id,) for artifact_id in ids],
            )
        return int(cursor.rowcount or 0)

    def delete_suggested_reference_artifacts(
        self,
        candidate_ids: Iterable[str] | None = None,
        person_names: Iterable[str] | None = None,
        statuses: Iterable[str] | None = None,
        all_candidates: bool = False,
    ) -> int:
        candidate_set = {str(item) for item in (candidate_ids or []) if str(item)}
        person_set = {str(item).strip().casefold() for item in (person_names or []) if str(item).strip()}
        status_set = {str(item) for item in (statuses or []) if str(item)}
        if not candidate_set and not person_set and not all_candidates:
            return 0
        with self.connect() as conn:
            rows = conn.execute(
                """
                SELECT artifact_id, status, payload_json
                FROM learned_artifacts
                WHERE artifact_type = 'suggested_reference'
                """
            ).fetchall()
            delete_ids: list[str] = []
            for row in rows:
                if status_set and str(row["status"] or "") not in status_set:
                    continue
                try:
                    payload = json.loads(str(row["payload_json"] or "{}"))
                except json.JSONDecodeError:
                    payload = {}
                if not isinstance(payload, dict):
                    payload = {}
                candidate_id = str(payload.get("candidateId", payload.get("candidate_id", "")) or "")
                person_name = str(payload.get("personName", payload.get("person_name", "")) or "").strip().casefold()
                if all_candidates or candidate_id in candidate_set or person_name in person_set:
                    delete_ids.append(str(row["artifact_id"]))
            if not delete_ids:
                return 0
            cursor = conn.executemany("DELETE FROM learned_artifacts WHERE artifact_id = ?", [(artifact_id,) for artifact_id in delete_ids])
            return int(cursor.rowcount if cursor.rowcount is not None else len(delete_ids))

    def calibration_summary(self) -> dict[str, Any]:
        training = self.training_example_summary()
        with self.connect() as conn:
            total = int(conn.execute("SELECT COUNT(*) AS n FROM calibration_labels").fetchone()["n"])
            blocked = int(conn.execute("SELECT COUNT(*) AS n FROM blocked_pairs").fetchone()["n"])
            learned = int(conn.execute("SELECT COUNT(*) AS n FROM learned_artifacts").fetchone()["n"])
            stats = conn.execute(
                """
                SELECT
                    COUNT(*) AS match_labels,
                    SUM(CASE WHEN is_match = 1 THEN 1 ELSE 0 END) AS positive_pairs,
                    SUM(CASE WHEN is_match = 0 THEN 1 ELSE 0 END) AS negative_pairs,
                    MIN(CASE WHEN is_match = 1 THEN match_score END) AS min_positive_score,
                    MAX(CASE WHEN is_match = 0 THEN match_score END) AS max_negative_score
                FROM calibration_labels
                WHERE is_match IS NOT NULL AND match_score IS NOT NULL
                """
            ).fetchone()
            safe_rows = conn.execute(
                "SELECT safe_label, COUNT(*) AS n FROM calibration_labels WHERE safe_label != '' GROUP BY safe_label"
            ).fetchall()
        match_labels = int(stats["match_labels"] or 0)
        positive_pairs = int(stats["positive_pairs"] or 0)
        negative_pairs = int(stats["negative_pairs"] or 0)
        min_pos = None if stats["min_positive_score"] is None else float(stats["min_positive_score"])
        max_neg = None if stats["max_negative_score"] is None else float(stats["max_negative_score"])
        recommended = None
        if min_pos is not None and max_neg is not None:
            recommended = max(0.0, min(1.0, (min_pos + max_neg) / 2.0))
        return {
            "totalLabels": total,
            "matchLabels": match_labels,
            "positivePairs": positive_pairs,
            "negativePairs": negative_pairs,
            "minPositiveScore": min_pos,
            "maxNegativeScore": max_neg,
            "recommendedLikelyThreshold": recommended,
            "safeLabels": {str(row["safe_label"]): int(row["n"]) for row in safe_rows},
            "falseMatchBlocks": blocked,
            "trainingExamples": training,
            "learnedArtifacts": learned,
        }

    def add_blocked_pair(self, row: dict[str, Any], conn: sqlite3.Connection | None = None) -> None:
        file_hash = str(row.get("fileHash", "")).strip()
        person_name = str(row.get("personName", "")).strip()
        if not file_hash or not person_name:
            raise ValueError("Blocked false-match pairs require a file hash and person name.")
        if conn is None:
            with self.connect() as local_conn:
                self.add_blocked_pair(row, local_conn)
            return
        conn.execute(
            """
            INSERT OR REPLACE INTO blocked_pairs(
                file_hash, person_name, best_ref_id, source_path, note, created_at
            ) VALUES(?, ?, ?, ?, ?, ?)
            """,
            (
                file_hash,
                person_name.casefold(),
                str(row.get("bestRefId", "") or ""),
                str(row.get("sourcePath", "")),
                str(row.get("note", ""))[:600],
                now_iso(),
            ),
        )

    def blocked_pair_exists(
        self,
        file_hash: str,
        person_name: str,
        best_ref_id: str | None = "",
        conn: sqlite3.Connection | None = None,
    ) -> bool:
        file_hash = str(file_hash or "").strip()
        person_key = str(person_name or "").strip().casefold()
        ref_id = str(best_ref_id or "")
        if not file_hash or not person_key:
            return False
        if conn is None:
            with self.connect() as local_conn:
                return self.blocked_pair_exists(file_hash, person_key, ref_id, local_conn)
        row = conn.execute(
            """
            SELECT 1 FROM blocked_pairs
            WHERE file_hash = ? AND person_name = ? AND (best_ref_id = ? OR best_ref_id = '')
            LIMIT 1
            """,
            (file_hash, person_key, ref_id),
        ).fetchone()
        return bool(row)

    def blocked_pairs_summary(self, limit: int = 20) -> dict[str, Any]:
        with self.connect() as conn:
            total = int(conn.execute("SELECT COUNT(*) AS n FROM blocked_pairs").fetchone()["n"])
            rows = conn.execute(
                """
                SELECT file_hash, person_name, best_ref_id, source_path, note, created_at
                FROM blocked_pairs
                ORDER BY created_at DESC
                LIMIT ?
                """,
                (max(0, int(limit)),),
            ).fetchall()
        return {
            "total": total,
            "recent": [dict(row) for row in rows],
        }

    def add_benchmark_run(self, run_id: str, payload: dict[str, Any]) -> None:
        with self.connect() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO benchmark_runs(run_id, generated_at, payload_json) VALUES(?, ?, ?)",
                (run_id, now_iso(), json.dumps(payload, separators=(",", ":"))),
            )

    def recent_benchmark_runs(self, limit: int = 8) -> list[dict[str, Any]]:
        limit = max(1, min(50, int(limit)))
        with self.connect() as conn:
            rows = conn.execute(
                """
                SELECT run_id, generated_at, payload_json
                FROM benchmark_runs
                ORDER BY generated_at DESC
                LIMIT ?
                """,
                (limit,),
            ).fetchall()
        history: list[dict[str, Any]] = []
        for row in rows:
            try:
                payload = json.loads(str(row["payload_json"] or "{}"))
            except json.JSONDecodeError:
                payload = {}
            if not isinstance(payload, dict):
                payload = {}
            payload.setdefault("runId", row["run_id"])
            payload.setdefault("generatedAt", row["generated_at"])
            history.append(payload)
        return history

    def clear_private_data(self, include_scan_history: bool = True) -> dict[str, int]:
        tables = [
            "safety_cache",
            "safe_mode_overrides",
            "photo_asset_events",
            "embedding_cache",
            "calibration_labels",
            "candidate_match_context",
            "training_examples",
            "learned_artifacts",
            "blocked_pairs",
            "photo_relationship_name_reviews",
            "review_candidates",
        ]
        if include_scan_history:
            tables.extend(["scan_files", "scan_runs"])
        deleted: dict[str, int] = {}
        with self.connect() as conn:
            for table in tables:
                cursor = conn.execute(f"DELETE FROM {table}")
                deleted[table] = int(cursor.rowcount if cursor.rowcount is not None else 0)
        return deleted

    def subject_private_person_names(self) -> list[str]:
        with self.connect() as conn:
            rows = conn.execute(
                """
                SELECT person_name AS person FROM review_candidates WHERE TRIM(person_name) != ''
                UNION
                SELECT person_name AS person FROM photo_asset_people WHERE TRIM(person_name) != ''
                UNION
                SELECT person_name AS person FROM photo_people_profiles WHERE TRIM(person_name) != ''
                UNION
                SELECT person_name AS person FROM photo_external_people_hints WHERE TRIM(person_name) != ''
                UNION
                SELECT expected_person AS person FROM calibration_labels WHERE TRIM(expected_person) != ''
                UNION
                SELECT actual_person AS person FROM calibration_labels WHERE TRIM(actual_person) != ''
                UNION
                SELECT expected_person AS person FROM training_examples WHERE TRIM(expected_person) != ''
                UNION
                SELECT actual_person AS person FROM training_examples WHERE TRIM(actual_person) != ''
                UNION
                SELECT person_name AS person FROM blocked_pairs WHERE TRIM(person_name) != ''
                ORDER BY person COLLATE NOCASE
                """
            ).fetchall()
        return [str(row["person"] or "").strip() for row in rows if str(row["person"] or "").strip()]

    def delete_subject_private_data(
        self,
        person_name: str,
        *,
        candidate_ids: Iterable[str] = (),
    ) -> dict[str, int]:
        person = " ".join(str(person_name or "").strip().split())
        if not person:
            raise ValueError("A person name is required.")
        person_key = person.casefold()
        person_pattern = re.compile(re.escape(person), re.IGNORECASE)
        explicit_candidate_ids = {str(value) for value in candidate_ids if str(value)}

        def remove_person(value: Any) -> tuple[Any, bool]:
            if isinstance(value, str):
                if value.strip().casefold() == person_key:
                    return None, True
                if person_key in value.casefold():
                    return person_pattern.sub("[redacted subject]", value), True
                return value, False
            if isinstance(value, list):
                result: list[Any] = []
                changed = False
                for item in value:
                    cleaned, item_changed = remove_person(item)
                    changed = changed or item_changed
                    if cleaned is not None:
                        result.append(cleaned)
                return result, changed
            if isinstance(value, dict):
                field = str(value.get("field", "")).strip().casefold()
                if field in {"person", "people", "personname", "person_name"}:
                    cleaned_value, value_changed = remove_person(value.get("value"))
                    if value_changed and cleaned_value in (None, [], ""):
                        return None, True
                result: dict[str, Any] = {}
                changed = False
                for key, item in value.items():
                    cleaned, item_changed = remove_person(item)
                    changed = changed or item_changed
                    if cleaned is not None:
                        result[str(key)] = cleaned
                return result, changed
            return value, False

        def rewrite_json_column(
            conn: sqlite3.Connection,
            table: str,
            key_column: str,
            json_columns: tuple[str, ...],
            updated_keys: set[str] | None = None,
        ) -> int:
            rows = conn.execute(
                f"SELECT {key_column}, {', '.join(json_columns)} FROM {table}"
            ).fetchall()
            updated = 0
            for row in rows:
                replacements: dict[str, str] = {}
                for column in json_columns:
                    try:
                        parsed = json.loads(str(row[column] or "{}"))
                    except json.JSONDecodeError:
                        continue
                    cleaned, changed = remove_person(parsed)
                    if changed:
                        replacements[column] = json.dumps(
                            {} if cleaned is None else cleaned,
                            sort_keys=True,
                            separators=(",", ":"),
                        )
                if not replacements:
                    continue
                assignments = ", ".join(f"{column} = ?" for column in replacements)
                conn.execute(
                    f"UPDATE {table} SET {assignments} WHERE {key_column} = ?",
                    (*replacements.values(), row[key_column]),
                )
                if updated_keys is not None:
                    updated_keys.add(str(row[key_column]))
                updated += 1
            return updated

        deleted: dict[str, int] = {}
        with self.connect() as conn:
            rows = conn.execute(
                "SELECT candidate_id FROM review_candidates WHERE person_key = ?",
                (person_key,),
            ).fetchall()
            all_candidate_ids = explicit_candidate_ids | {
                str(row["candidate_id"] or "") for row in rows if str(row["candidate_id"] or "")
            }
            affected_assets = {
                str(row["asset_id"] or "")
                for row in conn.execute(
                    "SELECT DISTINCT asset_id FROM photo_asset_people WHERE LOWER(person_name) = ?",
                    (person_key,),
                ).fetchall()
                if str(row["asset_id"] or "")
            }
            photo_people_rows = int(
                conn.execute(
                    "SELECT COUNT(*) AS n FROM photo_asset_people WHERE LOWER(person_name) = ?",
                    (person_key,),
                ).fetchone()["n"]
            )

            if all_candidate_ids:
                deleted["trainingExamples"] = self.delete_training_examples_for_candidates(all_candidate_ids, conn)
                deleted["reviewCandidates"] = self.delete_candidates(all_candidate_ids, conn)
            else:
                deleted["trainingExamples"] = 0
                deleted["reviewCandidates"] = 0

            cursor = conn.execute(
                """
                DELETE FROM training_examples
                WHERE LOWER(expected_person) = ? OR LOWER(actual_person) = ?
                """,
                (person_key, person_key),
            )
            deleted["trainingExamples"] += int(cursor.rowcount or 0)
            cursor = conn.execute(
                """
                DELETE FROM calibration_labels
                WHERE LOWER(expected_person) = ? OR LOWER(actual_person) = ?
                """,
                (person_key, person_key),
            )
            deleted["calibrationLabels"] = int(cursor.rowcount or 0)
            deleted["blockedPairs"] = int(
                conn.execute("DELETE FROM blocked_pairs WHERE LOWER(person_name) = ?", (person_key,)).rowcount or 0
            )

            conn.execute("DELETE FROM photo_asset_people WHERE LOWER(person_name) = ?", (person_key,))
            deleted["photoPeopleRows"] = photo_people_rows
            deleted["photoPeopleProfiles"] = int(
                conn.execute("DELETE FROM photo_people_profiles WHERE LOWER(person_name) = ?", (person_key,)).rowcount or 0
            )
            deleted["externalPeopleHints"] = int(
                conn.execute("DELETE FROM photo_external_people_hints WHERE LOWER(person_name) = ?", (person_key,)).rowcount or 0
            )
            deleted["relationshipNameReviews"] = self.delete_photo_relationship_name_reviews_for_people([person], conn)

            group_rows = conn.execute(
                """
                SELECT group_id, member_people_json, excluded_people_json,
                       member_pets_json, excluded_pets_json
                FROM photo_people_groups
                """
            ).fetchall()
            groups_updated = 0
            groups_deleted = 0
            for row in group_rows:
                try:
                    member_people = json.loads(str(row["member_people_json"] or "[]"))
                    excluded_people = json.loads(str(row["excluded_people_json"] or "[]"))
                    member_pets = json.loads(str(row["member_pets_json"] or "[]"))
                except json.JSONDecodeError:
                    continue
                next_members, members_changed = remove_person(member_people)
                next_excluded, excluded_changed = remove_person(excluded_people)
                if not members_changed and not excluded_changed:
                    continue
                if len(next_members or []) + len(member_pets if isinstance(member_pets, list) else []) < 2:
                    conn.execute("DELETE FROM photo_people_groups WHERE group_id = ?", (row["group_id"],))
                    groups_deleted += 1
                else:
                    conn.execute(
                        """
                        UPDATE photo_people_groups
                        SET member_people_json = ?, excluded_people_json = ?, updated_at = ?
                        WHERE group_id = ?
                        """,
                        (
                            json.dumps(next_members or [], separators=(",", ":")),
                            json.dumps(next_excluded or [], separators=(",", ":")),
                            now_iso(),
                            row["group_id"],
                        ),
                    )
                    groups_updated += 1
            deleted["peopleGroupsUpdated"] = groups_updated
            deleted["peopleGroupsDeleted"] = groups_deleted

            deleted["photoAlbumsUpdated"] = rewrite_json_column(
                conn,
                "photo_albums",
                "album_id",
                ("include_people_json", "exclude_people_json", "rules_json"),
            )
            deleted["savedFiltersUpdated"] = rewrite_json_column(
                conn,
                "photo_saved_filters",
                "filter_id",
                ("filters_json", "rules_json"),
            )
            deleted["operationRowsPseudonymized"] = rewrite_json_column(
                conn,
                "photo_operation_journal",
                "operation_id",
                ("payload_json", "undo_payload_json"),
            )
            deleted["assetEventsPseudonymized"] = rewrite_json_column(
                conn,
                "photo_asset_events",
                "event_id",
                ("metadata_json",),
            )
            deleted["assetMetadataPseudonymized"] = rewrite_json_column(
                conn,
                "photo_assets",
                "asset_id",
                ("metadata_json",),
                affected_assets,
            )

            # Aggregate local models cannot reliably subtract one subject. Remove
            # them and let the operator retrain from the remaining consented rows.
            # Per-subject synthetic age-image reviews are erased selectively by
            # ProjectState so another person's reviewed reference is not orphaned.
            deleted["learnedArtifacts"] = int(
                conn.execute(
                    "DELETE FROM learned_artifacts WHERE artifact_type != 'synthetic_age_image_review'"
                ).rowcount
                or 0
            )
            deleted["embeddingCache"] = int(conn.execute("DELETE FROM embedding_cache").rowcount or 0)
            deleted["safetyCache"] = int(conn.execute("DELETE FROM safety_cache").rowcount or 0)
            deleted["safeModeOverrides"] = int(conn.execute("DELETE FROM safe_mode_overrides").rowcount or 0)
            deleted["smartAlbumMaterializedRows"] = int(
                conn.execute("DELETE FROM photo_smart_album_materialized_items").rowcount or 0
            )
            self._bump_photo_smart_album_materialization_revision(conn, reason="delete_subject_private_data")
            for asset_id in sorted(affected_assets):
                self._index_photo_asset(asset_id, conn)
        return deleted

    def prune_scan_manifests(self, keep_runs: int = 20) -> dict[str, int]:
        keep_runs = max(1, min(1000, int(keep_runs)))
        with self.connect() as conn:
            before_runs = int(conn.execute("SELECT COUNT(*) AS n FROM scan_runs").fetchone()["n"])
            before_files = int(conn.execute("SELECT COUNT(*) AS n FROM scan_files").fetchone()["n"])
            rows = conn.execute(
                """
                SELECT run_id FROM scan_runs
                ORDER BY updated_at DESC
                LIMIT -1 OFFSET ?
                """,
                (keep_runs,),
            ).fetchall()
            run_ids = [str(row["run_id"]) for row in rows]
            deleted_files = 0
            deleted_runs = 0
            for run_id in run_ids:
                file_cursor = conn.execute("DELETE FROM scan_files WHERE run_id = ?", (run_id,))
                deleted_files += int(file_cursor.rowcount if file_cursor.rowcount is not None else 0)
                run_cursor = conn.execute("DELETE FROM scan_runs WHERE run_id = ?", (run_id,))
                deleted_runs += int(run_cursor.rowcount if run_cursor.rowcount is not None else 0)
            after_runs = int(conn.execute("SELECT COUNT(*) AS n FROM scan_runs").fetchone()["n"])
            after_files = int(conn.execute("SELECT COUNT(*) AS n FROM scan_files").fetchone()["n"])
        return {
            "keepRuns": keep_runs,
            "runsBefore": before_runs,
            "filesBefore": before_files,
            "runsDeleted": deleted_runs,
            "filesDeleted": deleted_files,
            "runsAfter": after_runs,
            "filesAfter": after_files,
        }

    def optimize(self) -> dict[str, int]:
        before = os.path.getsize(self.path) if self.path.exists() else 0
        wal_path = Path(str(self.path) + "-wal")
        shm_path = Path(str(self.path) + "-shm")
        before_wal = os.path.getsize(wal_path) if wal_path.exists() else 0
        before_shm = os.path.getsize(shm_path) if shm_path.exists() else 0
        with self.connect() as conn:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            conn.execute("VACUUM")
        after = os.path.getsize(self.path) if self.path.exists() else 0
        after_wal = os.path.getsize(wal_path) if wal_path.exists() else 0
        after_shm = os.path.getsize(shm_path) if shm_path.exists() else 0
        return {
            "dbBytesBefore": before + before_wal + before_shm,
            "dbBytesAfter": after + after_wal + after_shm,
            "dbBytesReclaimed": max(0, before + before_wal + before_shm - after - after_wal - after_shm),
        }

    def snapshot_to(self, target: Path) -> None:
        # data-persistence-3: write a transactionally-consistent single-file copy
        # of the database via VACUUM INTO. Unlike byte-copying the live
        # main+WAL+SHM, this is safe to take while another writer is active and
        # produces a self-contained file that needs no -wal/-shm sidecars.
        target = Path(target)
        if target.exists():
            target.unlink()
        target.parent.mkdir(parents=True, exist_ok=True)
        conn = self._open_connection(timeout=30, isolation_level=None)
        try:
            conn.execute("PRAGMA busy_timeout=30000")
            conn.execute("VACUUM INTO ?", (str(target),))
        finally:
            conn.close()
        verify = self._open_connection(target, timeout=30)
        try:
            integrity = [str(row[0]) for row in verify.execute("PRAGMA integrity_check").fetchall()]
            foreign_key_errors = verify.execute("PRAGMA foreign_key_check").fetchmany(1)
            if integrity != ["ok"] or foreign_key_errors:
                raise sqlite3.DatabaseError("Snapshot failed SQLite integrity verification.")
        finally:
            verify.close()

    def rekey(self, new_key: bytes) -> dict[str, Any]:
        parsed = WorkspaceEncryption(self.path.parent, new_key, required=True).key
        assert parsed is not None
        if self._key is None:
            raise WorkspaceEncryptionError("A plaintext development database cannot be rotated in place; migrate it first.")
        old_key = self._key
        conn = self._open_connection(timeout=30, isolation_level=None)
        try:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            conn.execute(f"PRAGMA rekey=\"x'{parsed.hex()}'\"")
        except Exception:
            self._key = old_key
            raise
        finally:
            conn.close()
        self._key = parsed
        self.encryption.set_primary_key(parsed, retain=[old_key, *self.encryption.key_candidates])
        self._verify_encrypted_database(self.path, parsed)
        return self.encryption_status()

    def encryption_status(self) -> dict[str, Any]:
        encrypted_header = bool(self.path.exists() and not self._is_plaintext_database(self.path))
        cipher_integrity: list[str] = []
        if self._key is not None and self.path.exists():
            conn = self._open_connection(timeout=30, isolation_level=None)
            try:
                cipher_integrity = [str(row[0]) for row in conn.execute("PRAGMA cipher_integrity_check").fetchall()]
            finally:
                conn.close()
        return {
            "required": self.encryption.required,
            "enabled": self._key is not None,
            "encryptedHeader": encrypted_header,
            "keyId": workspace_key_id(self._key),
            "cipherVersion": self._cipher_version,
            "cipherIntegrity": cipher_integrity,
            "plaintextHeader": self._is_plaintext_database(self.path) if self.path.exists() else False,
            "walEncryptedByDatabaseCodec": self._key is not None,
            "temporaryStorage": "memory" if self._key is not None else "default",
        }

    def integrity_report(self) -> dict[str, Any]:
        wal_path = Path(str(self.path) + "-wal")
        shm_path = Path(str(self.path) + "-shm")
        result: dict[str, Any] = {
            "generatedAt": now_iso(),
            "path": str(self.path),
            "exists": self.path.exists(),
            "ok": False,
            "integrity": [],
            "foreignKeyErrors": [],
            "tableCounts": {},
            "dbBytes": os.path.getsize(self.path) if self.path.exists() else 0,
            "walBytes": os.path.getsize(wal_path) if wal_path.exists() else 0,
            "shmBytes": os.path.getsize(shm_path) if shm_path.exists() else 0,
            "error": "",
        }
        try:
            with self.connect() as conn:
                integrity_rows = [str(row[0]) for row in conn.execute("PRAGMA integrity_check").fetchall()]
                fk_rows = [dict(row) for row in conn.execute("PRAGMA foreign_key_check").fetchall()]
                counts: dict[str, int] = {}
                for table in (
                    "scan_runs",
                    "scan_files",
                    "safety_cache",
                    "embedding_cache",
                    "calibration_labels",
                    "training_examples",
                    "learned_artifacts",
                    "blocked_pairs",
                    "benchmark_runs",
                    "review_candidates",
                    "photo_relationship_name_reviews",
                ):
                    try:
                        counts[table] = int(conn.execute(f"SELECT COUNT(*) AS n FROM {table}").fetchone()["n"])
                    except sqlite3.Error:
                        counts[table] = -1
                result["integrity"] = integrity_rows
                result["foreignKeyErrors"] = fk_rows[:50]
                result["tableCounts"] = counts
                result["ok"] = integrity_rows == ["ok"] and not fk_rows and all(value >= 0 for value in counts.values())
        except sqlite3.Error as exc:
            result["error"] = str(exc)
        return result

    def snapshot_files(self, reason: str = "repair") -> dict[str, Any]:
        stamp = now_iso().replace(":", "").replace("-", "").replace("Z", "")
        safe_reason = "".join(character if character.isalnum() or character in {"-", "_"} else "-" for character in reason)[:48] or "snapshot"
        backup_dir = self.path.parent / "db-backups" / f"{stamp}-{safe_reason}"
        backup_dir.mkdir(parents=True, exist_ok=True)
        copied: list[dict[str, Any]] = []
        for source in (self.path, Path(str(self.path) + "-wal"), Path(str(self.path) + "-shm")):
            if not source.exists():
                continue
            target = backup_dir / source.name
            shutil.copy2(source, target)
            copied.append({"from": str(source), "to": str(target), "bytes": target.stat().st_size})
        return {
            "generatedAt": now_iso(),
            "backupDir": str(backup_dir),
            "files": copied,
            "bytes": sum(int(item["bytes"]) for item in copied),
        }

    def rebuild_empty(self) -> None:
        for source in (self.path, Path(str(self.path) + "-wal"), Path(str(self.path) + "-shm")):
            try:
                source.unlink()
            except OSError:
                pass
        self._init_schema()

    def scale_summary(self) -> dict[str, Any]:
        cache_key = self._scale_summary_stat_key()
        if self._scale_summary_cache_key == cache_key and self._scale_summary_cache_value is not None:
            return copy.deepcopy(self._scale_summary_cache_value)
        with self.connect() as conn:
            scan_files = int(conn.execute("SELECT COUNT(*) AS n FROM scan_files").fetchone()["n"])
            scan_runs = int(conn.execute("SELECT COUNT(*) AS n FROM scan_runs").fetchone()["n"])
            safety_cache = int(conn.execute("SELECT COUNT(*) AS n FROM safety_cache").fetchone()["n"])
            embedding_cache = int(conn.execute("SELECT COUNT(*) AS n FROM embedding_cache").fetchone()["n"])
            calibration = int(conn.execute("SELECT COUNT(*) AS n FROM calibration_labels").fetchone()["n"])
            training_examples = int(conn.execute("SELECT COUNT(*) AS n FROM training_examples").fetchone()["n"])
            learned_artifacts = int(conn.execute("SELECT COUNT(*) AS n FROM learned_artifacts").fetchone()["n"])
            review_candidates = int(conn.execute("SELECT COUNT(*) AS n FROM review_candidates").fetchone()["n"])
            relationship_name_reviews = int(conn.execute("SELECT COUNT(*) AS n FROM photo_relationship_name_reviews").fetchone()["n"])
            photo_assets = int(conn.execute("SELECT COUNT(*) AS n FROM photo_assets").fetchone()["n"])
            photo_metadata_rows = int(conn.execute("SELECT COUNT(*) AS n FROM photo_asset_metadata").fetchone()["n"])
            photo_albums = int(conn.execute("SELECT COUNT(*) AS n FROM photo_albums").fetchone()["n"])
            photo_edit_versions = int(conn.execute("SELECT COUNT(*) AS n FROM photo_edit_stack_versions").fetchone()["n"])
            photo_media_pairs = int(conn.execute("SELECT COUNT(*) AS n FROM photo_media_pairs").fetchone()["n"])
            photo_external_sources = int(conn.execute("SELECT COUNT(*) AS n FROM photo_external_sources").fetchone()["n"])
            photo_external_asset_links = int(conn.execute("SELECT COUNT(*) AS n FROM photo_asset_external_ids").fetchone()["n"])
            photo_tether_sessions = int(conn.execute("SELECT COUNT(*) AS n FROM photo_tether_sessions").fetchone()["n"])
            photo_tether_captures = int(conn.execute("SELECT COUNT(*) AS n FROM photo_tether_captures").fetchone()["n"])
            photo_curation_preferences = int(conn.execute(
                "SELECT COUNT(*) AS n FROM meta WHERE key = 'photo_curation_preferences'"
            ).fetchone()["n"])
            hash_resume_entries = int(conn.execute(
                "SELECT COUNT(*) AS n FROM scan_files WHERE content_hash != ''"
            ).fetchone()["n"])
            latest = conn.execute(
                "SELECT * FROM scan_runs ORDER BY updated_at DESC, started_at DESC, rowid DESC LIMIT 1"
            ).fetchone()
        try:
            db_bytes = os.path.getsize(self.path)
        except OSError:
            db_bytes = 0
        result = {
            "dbPath": str(self.path),
            "dbBytes": db_bytes,
            "scanRuns": scan_runs,
            "manifestFiles": scan_files,
            "hashResumeEntries": hash_resume_entries,
            "safetyCacheEntries": safety_cache,
            "embeddingCacheEntries": embedding_cache,
            "calibrationLabels": calibration,
            "trainingExamples": training_examples,
            "learnedArtifacts": learned_artifacts,
            "reviewCandidateRows": review_candidates,
            "relationshipNameReviews": relationship_name_reviews,
            "photoAssets": photo_assets,
            "photoMetadataRows": photo_metadata_rows,
            "photoAlbums": photo_albums,
            "photoEditVersions": photo_edit_versions,
            "photoMediaPairs": photo_media_pairs,
            "photoExternalSources": photo_external_sources,
            "photoExternalAssetLinks": photo_external_asset_links,
            "photoTetherSessions": photo_tether_sessions,
            "photoTetherCaptures": photo_tether_captures,
            "photoCurationPreferences": photo_curation_preferences,
            "latestScan": dict(latest) if latest else None,
        }
        self._scale_summary_cache_key = self._scale_summary_stat_key()
        self._scale_summary_cache_value = copy.deepcopy(result)
        return result
